window.PP_BANKS=window.PP_BANKS||{};window.PP_BANKS["econ-150-ch16"]={"schema":"precise-practice/1","bank_id":"econ-150-ch16","book":"econ-150","chapter":16,"title":"Institutions","storage_version":1,"status":"draft","blueprint":"docs/blueprints/econ-150-ch16-institutions.md","source":{"converted_on":"2026-11-01","from":"items/econ-150/ch16-institutions.json (PR #112 bank)","dropped":["Missing Piece items (retirement candidate)","written advanced prompts (Tier 3 has no text boxes)","odd-one-out sets (not approved)","the six chapter-end FRQ drafts (the chapter's harbor-town FRQ is the Tier 4 task)"],"note":"Structure converted; wording unchanged. Content repairs follow the audit in docs/audits/econ-150-ch16-bank-audit-2026-11-01.md."},"settings":{"goals":{"1":10,"2":5,"3":3}},"concepts":[{"id":"c1","number":1,"name":"Markets Are Built","activities":[{"id":"c1-sort","type":"sort","tier":1,"title":"Sort the cases","targets":["16.1a"],"status":"draft","bins":["Ownership","Enforcement","Open entry","Predictability"],"round_size":6,"cards":[{"id":"E16-C1-F01","text":"A recorded deed identifies who may sell a farm","bin":0,"why":"Documented title helps a buyer verify a seller's ownership claim.","_v":"60b37c40d9"},{"id":"E16-C1-F02","text":"A court orders payment for goods already delivered under contract","bin":1,"why":"An enforceable promise makes the exchange more credible.","_v":"85f248e9b9"},{"id":"E16-C1-F03","text":"A newcomer may open a bakery under the same rules as incumbents","bin":2,"why":"New firms have access to the market rather than facing insider vetoes.","_v":"f314f556dd"},{"id":"E16-C1-F04","text":"Permit requirements are published before applications open","bin":3,"why":"Advance rules help firms plan and reduce arbitrary surprises.","_v":"08c0c6e562"},{"id":"E16-C1-F05","text":"A buyer checks the land registry before purchasing a house","bin":0,"why":"A registry clarifies who holds a claim to the asset.","_v":"b35eba3c2a"},{"id":"E16-C1-F06","text":"A supplier can obtain a remedy when a buyer refuses to pay","bin":1,"why":"Legal remedies support contract performance.","_v":"87ecf81f73"},{"id":"E16-C1-F07","text":"New competitors receive equal access to licenses","bin":2,"why":"The opportunity to enter is not reserved for established firms.","_v":"9d6f3214f4"},{"id":"E16-C1-F08","text":"Businesses receive notice before a new tax rule takes effect","bin":3,"why":"Stable, disclosed rules help firms anticipate legal obligations.","_v":"64d204a647"},{"id":"E16-C1-F09","text":"A vehicle seller can document a legally transferable title","bin":0,"why":"Credible transferable ownership supports voluntary sale.","_v":"071ecfce5b"},{"id":"E16-C1-F10","text":"A neutral judge hears a dispute between an incumbent and newcomer","bin":1,"why":"Impartial enforcement does not privilege the politically connected.","_v":"83086ab389"},{"id":"E16-C1-F11","text":"A family receives legal title to the house it has lived in for years","bin":0,"why":"A recognized title settles who owns the house and may sell or borrow against it.","_v":"6fe4db222a"},{"id":"E16-C1-F12","text":"A small business proves it owns its delivery van before pledging it as collateral","bin":0,"why":"A lender needs proof of ownership before accepting an asset as collateral.","_v":"109a421455"},{"id":"E16-C1-F13","text":"Each founder's share of a startup is recorded so everyone knows who owns what","bin":0,"why":"Recorded ownership claims let founders sell or borrow against their shares.","_v":"0d3a007a65"},{"id":"E16-C1-F14","text":"An arbitrator orders a supplier to replace a shipment that arrived damaged","bin":1,"why":"A neutral ruling with consequences makes the supplier's promise worth something.","_v":"52a0e0073d"},{"id":"E16-C1-F15","text":"A tenant can take a landlord to court for keeping a deposit without cause","bin":1,"why":"A legal remedy makes the rental agreement binding on both sides.","_v":"21d68d9789"},{"id":"E16-C1-F16","text":"A trade association expels a member who refused to pay for goods","bin":1,"why":"Losing access to the whole network is a penalty that makes members keep their promises.","_v":"72408bd485"},{"id":"E16-C1-F17","text":"Anyone who passes the same safety test can get a food-truck permit","bin":2,"why":"The permit depends on a test everyone can take, not on who you know.","_v":"7f926a6620"},{"id":"E16-C1-F18","text":"A rule letting existing shops block new ones is repealed","bin":2,"why":"Removing the veto lets newcomers compete. Sometimes the fix is removing a rule.","_v":"bee7986164"},{"id":"E16-C1-F19","text":"A new airline can apply for airport landing slots through the same process as established airlines","bin":2,"why":"Newcomers get the same access as incumbents.","_v":"4c33695d07"},{"id":"E16-C1-F20","text":"Registering a business takes one online form instead of months of office visits","bin":2,"why":"A cheaper, faster process lets more people enter the market.","_v":"16cc67d683"},{"id":"E16-C1-F21","text":"Zoning rules are posted online and change only after public notice","bin":3,"why":"Firms can see the rules ahead of time and plan around them.","_v":"681a9bb793"},{"id":"E16-C1-F22","text":"A business license lasts five years under the terms set when it was issued","bin":3,"why":"Stable terms let the owner plan without fearing a sudden change.","_v":"000eec1ed2"},{"id":"E16-C1-F23","text":"Import fees are set a year ahead so shops can plan their orders","bin":3,"why":"Known costs make planning possible.","_v":"c071928832"},{"id":"E16-C1-F24","text":"A city publishes how long each kind of permit takes and meets those deadlines","bin":3,"why":"Applicants know what to expect and when.","_v":"0beefd6309"}]},{"id":"c1-quick-failure","type":"quick","tier":1,"title":"Which failure?","targets":["16.1b"],"status":"draft","note":"Ported from the Chapter 16 pilot (Quick Sort · Which failure?), items E16-C1-QF01 to QF14; QF15 onward added November 6, 2026.","instructions":"Did the market fail, or did the rules underneath it fail? A market failure can happen even when the rules work: costs spill over, benefits can't be charged for, one seller has too much power, or buyers can't judge quality. An institutional failure means the rules are missing, unenforced, or bent toward insiders.","labels":["Market failure","Institutional failure"],"round_size":8,"items":[{"id":"E16-C1-QF01","prompt":"A town’s land registry is six years behind, so a company cannot prove who owns the lot it wants to buy.","answer":1,"why":"Institutional failure: the registry is a rule-system institution that cannot establish a clear, transferable title.","_v":"841002e631"},{"id":"E16-C1-QF02","prompt":"A bank will not lend because local courts routinely ignore loan contracts they dislike.","answer":1,"why":"Institutional failure: unreliable courts make contracts unenforceable, so the rule of law underneath exchange is broken.","_v":"b3184861b8"},{"id":"E16-C1-QF03","prompt":"A permit official delays a bakery’s application until the owner pays an unofficial fee.","answer":1,"why":"Institutional failure: the official is selling access to a rule through corruption, making exchange unpredictable and costly.","_v":"624883404a"},{"id":"E16-C1-QF04","prompt":"New firms may enter a market only if an incumbent grants permission.","answer":1,"why":"Institutional failure: the rules restrict open entry and protect insiders rather than allowing fair participation.","_v":"54850fff05"},{"id":"E16-C1-QF05","prompt":"A factory follows every rule and the courts work well, but its smoke still damages a laundry next door.","answer":0,"why":"Market failure: the rules work, yet the smoke's cost falls on the laundry instead of the factory, so there is too much harm.","_v":"30125af423"},{"id":"E16-C1-QF06","prompt":"An open-access fishery is depleted because each fisher ignores the cost imposed on other fishers, even though the town's rules and courts work as intended.","answer":0,"why":"Market failure: a common resource is overused because individual choices do not fully account for the shared cost.","_v":"3ad9ac4327"},{"id":"E16-C1-QF07","prompt":"A town’s flood-warning siren benefits everyone nearby, but households can listen without paying, even though the town's rules and courts work as intended.","answer":0,"why":"Market failure: the benefit is hard to exclude others from, so free riding can lead to underprovision.","_v":"9b68d6e4f9"},{"id":"E16-C1-QF08","prompt":"A crowded, unpriced city road becomes slower as each additional driver adds congestion, even though the city's rules work as intended.","answer":0,"why":"Market failure: each driver imposes a congestion cost on others that is not included in the private decision.","_v":"6bb9d6a1cb"},{"id":"E16-C1-QF09","prompt":"A lighthouse signal is available to every nearby ship, and one ship’s use does not reduce the signal available to others, even though the town's rules and courts work as intended.","answer":0,"why":"Market failure: a non-excludable, non-rival benefit is difficult to fund through ordinary individual purchases.","_v":"b89acb6de5"},{"id":"E16-C1-QF10","prompt":"A licensing office publishes one set of rules but applies different standards to connected businesses.","answer":1,"why":"Institutional failure: arbitrary, favoritist enforcement makes the rules less predictable and protects insiders.","_v":"3ab7af0fe6"},{"id":"E16-C1-QF11","prompt":"A used-car seller hides a defect he knows about, and the town never enforces its fraud law, so buyers stop trusting sellers.","answer":1,"why":"Institutional failure: fraud is tolerated, so the rule that should protect buyers isn't working.","_v":"3af16a1258"},{"id":"E16-C1-QF12","prompt":"A vaccination protects nearby people, but each buyer considers only the private benefit when deciding whether to get one.","answer":0,"why":"Market failure: markets assume private choices capture the relevant benefits. A positive spillover is left out of the buyer’s decision.","_v":"f726c726fd"},{"id":"E16-C1-QF13","prompt":"One water network can serve a town at much lower cost than competing networks, so one provider remains the only practical seller and can restrict output.","answer":0,"why":"Market failure: markets assume competition can discipline sellers. A natural monopoly can leave too much power in one firm’s hands.","_v":"26c9504b6e"},{"id":"E16-C1-QF14","prompt":"A builder's faulty work damages a neighbor's house, but the only court that hears such claims takes years to rule, so the neighbor gives up.","answer":1,"why":"Institutional failure: the rule exists, but slow enforcement means it can't do its job.","_v":"bf3091c271"},{"id":"E16-C1-QF15","prompt":"A city requires nine separate permits for a food truck and takes two years to issue them.","answer":1,"why":"Institutional failure: cooks and customers are ready to trade, but a slow, tangled permit rule keeps sellers out. Easing or removing the rule could fix it.","_v":"34c131b0db"},{"id":"E16-C1-QF16","prompt":"A court takes eight years to rule on an unpaid invoice, so suppliers stop selling on credit.","answer":1,"why":"Institutional failure: contracts are hard to enforce, so sellers stop trusting buyers' promises to pay later.","_v":"f3fe1c3e0d"},{"id":"E16-C1-QF17","prompt":"Two families hold deeds to the same lot because the registry recorded both sales.","answer":1,"why":"Institutional failure: the registry can't establish who owns the lot, so no one can sell or build on it with confidence.","_v":"ddc1ac9b25"},{"id":"E16-C1-QF18","prompt":"A judge's rulings in contract cases depend on which side is related to the governor.","answer":1,"why":"Institutional failure: courts that favor insiders make every contract less reliable for everyone else.","_v":"721e085574"},{"id":"E16-C1-QF19","prompt":"A city lets current taxi owners decide whether any new taxi licenses are issued.","answer":1,"why":"Institutional failure: the people who benefit from less competition control the rule on entry.","_v":"601c11bfe1"},{"id":"E16-C1-QF20","prompt":"A farmer can't use the land she has worked for decades as collateral because the village has no legal title system.","answer":1,"why":"Institutional failure: without title, the land can't back a loan. Her wealth is real but hard to use.","_v":"75f0edd1b0"},{"id":"E16-C1-QF21","prompt":"Police in a market district ignore theft from stalls unless the owner pays them.","answer":1,"why":"Institutional failure: protection of property is being sold, so vendors who can't pay face risk the rules should cover.","_v":"db312658bd"},{"id":"E16-C1-QF22","prompt":"A new tax is applied to sales that businesses already made last year.","answer":1,"why":"Institutional failure: the rule changed after the fact, so firms can't plan around it.","_v":"e2e965e57a"},{"id":"E16-C1-QF23","prompt":"A building inspector approves unsafe buildings for builders who pay him.","answer":1,"why":"Institutional failure: the safety rule exists, but the person enforcing it sells exceptions.","_v":"f010e96979"},{"id":"E16-C1-QF24","prompt":"A delivery contract signed online can't be enforced because the law doesn't recognize online contracts.","answer":1,"why":"Institutional failure: a missing rule leaves a willing buyer and seller unable to make their promises binding.","_v":"f45c207def"},{"id":"E16-C1-QF25","prompt":"A license to sell fruit at the train station goes only to vendors who belong to the mayor's party.","answer":1,"why":"Institutional failure: entry depends on political connections rather than on fair, open rules.","_v":"e9bff2344d"},{"id":"E16-C1-QF26","prompt":"Buyers of leaf blowers pay the full price, but neighbors bear the noise.","answer":0,"why":"Market failure: the rules work, but part of the cost falls on people outside the sale, so too many leaf blowers get used.","_v":"df7acfe94e"},{"id":"E16-C1-QF27","prompt":"Bees from a beekeeper's hives pollinate nearby orchards, but the orchards don't pay, so the beekeeper keeps fewer hives than would be best.","answer":0,"why":"Market failure: a benefit spills over to others, so the market produces too little of something valuable.","_v":"53b75bd612"},{"id":"E16-C1-QF28","prompt":"Every household would gain from mosquito spraying across town, but each one hopes the others will pay for it, even though the town's rules and courts work as intended.","answer":0,"why":"Market failure: people benefit whether or not they pay, so free riding leaves the spraying underfunded.","_v":"15f56758f0"},{"id":"E16-C1-QF29","prompt":"Only one rail line can practically serve a remote mining town, and its owner charges far above cost.","answer":0,"why":"Market failure: competition can't discipline a seller that faces no practical rival.","_v":"4b9e130f67"},{"id":"E16-C1-QF30","prompt":"The only cement plant in a region cuts output to raise its price, though its permits and contracts are all in order.","answer":0,"why":"Market failure: the rules work, but one seller has too much power over the price.","_v":"9b25f3de36"},{"id":"E16-C1-QF31","prompt":"Each family's car adds a little to city smog, but no family counts that cost when deciding how much to drive, even though the city's rules and courts work as intended.","answer":0,"why":"Market failure: a cost spills over onto everyone breathing the air, so there is more driving than would be best.","_v":"bc729611ce"},{"id":"E16-C1-QF32","prompt":"A town's only grocery store, 60 miles from the next one, charges far above cost.","answer":0,"why":"Market failure: with no nearby rival, competition can't hold the store's prices down.","_v":"d004039df8"}]},{"id":"c1-match","type":"match","tier":1,"title":"Memory Match","targets":["16.1a"],"status":"draft","board_size":6,"pairs":[{"id":"E16-C1-MM01","left":"Institutions","right":"Formal and informal rules that structure how people interact and exchange.","_v":"bbce12b64c"},{"id":"E16-C1-MM02","left":"Rule of law","right":"Rules applied predictably and impartially, with credible enforcement.","_v":"92b1c19126"},{"id":"E16-C1-MM03","left":"Property rights","right":"Defined, recognized claims about how resources may be used and transferred.","_v":"b4ea4611b6"},{"id":"E16-C1-MM04","left":"Open entry","right":"Opportunities for newcomers to compete under fair, accessible rules.","_v":"f8bf4864c8"},{"id":"E16-C1-MM05","left":"Contract enforcement","right":"Reliable processes for ensuring that promised agreements are honored.","_v":"c11bb421a4"},{"id":"E16-C1-MM06","left":"Transaction costs","right":"The costs of finding partners, negotiating, monitoring, and enforcing exchange.","_v":"fc77e173e3"},{"id":"E16-C1-MM07","left":"Courts","right":"Institutions that resolve disputes, enforce contracts, and order compensation.","_v":"f5cd23f77b"},{"id":"E16-C1-MM08","left":"Liability","right":"Legal responsibility for harm or breach, which decides who must compensate whom.","_v":"69b710bd4b"},{"id":"E16-C1-MM09","left":"Institutional failure","right":"A bad outcome caused by rules that are missing, unenforced, or captured by insiders.","_v":"04ac3762c3"},{"id":"E16-C1-MM10","left":"Market failure","right":"A bad outcome that buyers and sellers produce even when the rules work.","_v":"71e057dc38"},{"id":"E16-C1-MM11","left":"Dead capital","right":"Assets people hold but can't borrow against because they lack legal title.","_v":"def048e64c"},{"id":"E16-C1-MM12","left":"Informal institutions","right":"Unwritten rules, like reputation and custom, that people follow and enforce among themselves.","_v":"f55082b0ac"},{"id":"E16-C1-MM13","left":"Private arbitration","right":"Settling a dispute before a neutral judge the parties choose, outside the state courts.","_v":"6e4797c905"},{"id":"E16-C1-MM14","left":"Collateral","right":"An asset a borrower pledges, which the lender can claim if the loan isn't repaid.","_v":"e6f55f2d41"},{"id":"E16-C1-MM15","left":"Fraud","right":"Deceiving a trading partner about what is being sold or promised.","_v":"d87bb192e5"},{"id":"E16-C1-MM16","left":"Title","right":"A record that proves who owns an asset and may transfer it.","_v":"36bd9372b2"}]},{"id":"c1-detective","type":"detective","tier":1,"title":"Definition Detective","targets":["16.1a"],"status":"draft","rounds":[{"id":"E16-C1-DD01","term":"Market institutions","answers":[{"text":"Markets depend on rules that support ownership, contracts, enforcement, and participation.","grade":"A","why":"Market exchange depends on several supporting institutions, including enforceable rights and contracts."},{"text":"Markets depend on recognized ownership rights.","grade":"A-","why":"Ownership matters, but reliable exchange also depends on enforcement and other institutions."},{"text":"Markets work best when no rules or enforcement institutions exist.","grade":"F","why":"Without predictable rights and enforcement, many exchanges become difficult or risky."}],"_v":"2a9b915200"},{"id":"E16-C1-DD02","term":"Open entry","answers":[{"text":"Open entry means firms can join a market under clear, reasonably accessible rules without favoritism.","grade":"A","why":"Open entry requires meaningful access, not merely permission on paper."},{"text":"Open entry means new firms are legally allowed to register.","grade":"A-","why":"Legal permission alone may not overcome discriminatory fees, corruption, or practical barriers."},{"text":"Open entry means the government chooses which favored businesses may compete.","grade":"F","why":"Favoring insiders restricts rather than opens entry."}],"_v":"ca4b8bc3f7"},{"id":"E16-C1-DD03","term":"Institutional failure","answers":[{"text":"A bad outcome caused by rules that are missing, unenforced, or captured by insiders, rather than by the market itself.","grade":"A","why":"It names all three ways the rules can fail and separates them from market failure."},{"text":"A bad outcome caused by rules that aren't enforced.","grade":"A-","why":"Unenforced rules are one kind, but rules can also be missing or bent toward insiders."},{"text":"Any bad market outcome, such as pollution or a monopoly.","grade":"F","why":"Those can happen even when the rules work. That's market failure."}],"_v":"e938258c7b"},{"id":"E16-C1-DD04","term":"Rule of law","answers":[{"text":"Rules that are public, stable, general, and predictably enforced, rather than arbitrary.","grade":"A","why":"It covers what the rules are like and how they are applied."},{"text":"Rules that are written down and published.","grade":"A-","why":"Publishing matters, but the rules also have to apply to everyone and be enforced predictably."},{"text":"Whatever the people in power decide is the law.","grade":"F","why":"That is rule by people, which can be arbitrary. The rule of law binds the people in power too."}],"_v":"7fb3178c9f"},{"id":"E16-C1-DD05","term":"Transaction costs","answers":[{"text":"The costs of finding partners, measuring quality or harm, negotiating, and enforcing an agreement.","grade":"A","why":"It lists every stage of making a deal happen."},{"text":"The cost of hiring lawyers to write contracts.","grade":"A-","why":"That is one transaction cost, but searching, measuring, negotiating, and enforcing count too."},{"text":"The price a buyer pays the seller for the good.","grade":"F","why":"The price is the deal itself, not the cost of making the deal happen."}],"_v":"8f9f252db7"},{"id":"E16-C1-DD06","term":"Contract enforcement","answers":[{"text":"Reliable enforcement of voluntary agreements, so promises about payment, delivery, quality, work, and credit have force.","grade":"A","why":"It explains what is enforced and why it matters."},{"text":"Courts making someone pay when they fail to deliver what they promised.","grade":"A-","why":"That is one case. Enforcement covers many kinds of promises and can come from arbitration as well as courts."},{"text":"The government setting the terms of every contract.","grade":"F","why":"Enforcing a promise is different from deciding what the promise says."}],"_v":"c0e8012f17"},{"id":"E16-C1-DD07","term":"Market failure","answers":[{"text":"Buyers and sellers, even under good rules, producing too much of something harmful, too little of something valuable, or too much power in one firm's hands.","grade":"A","why":"It covers all three outcomes and notes that the rules are working."},{"text":"A market producing too much of something harmful, like pollution.","grade":"A-","why":"Right as far as it goes, but it leaves out too little of something valuable and too much market power."},{"text":"A business losing money and closing.","grade":"F","why":"Losses and exit are how markets normally work, not a failure."}],"_v":"039f4948ce"},{"id":"E16-C1-DD08","term":"Free market","answers":[{"text":"A market that is free within rules on property, contracts, and enforcement.","grade":"A","why":"Free means free within rules, not free of them."},{"text":"A market where the government doesn't set prices.","grade":"A-","why":"True of many free markets, but it leaves out the rules on property and contracts they depend on."},{"text":"A market with no rules or government at all.","grade":"F","why":"Without property, contracts, and enforcement there is no market, just a contest over who can grab what."}],"_v":"c675a385f8"}]},{"id":"c1-odd","type":"choice","tier":1,"title":"Odd one out","targets":["16.1a","16.1b"],"status":"draft","note":"Ported from the Chapter 16 pilot's Odd One Out (a pilot interaction, not yet approved), run as single choice. OO01 and OO02 are the pilot's sets.","instructions":"Three of these belong together. Pick the one that doesn't.","items":[{"id":"E16-C1-OO01","prompt":"Three of these help strangers exchange with confidence. Which is the odd one out?","options":["Enforceable contracts","Clear ownership records","Predictable legal remedies","Guaranteed profits for every business"],"answer":3,"why":"Contracts, ownership records, and legal remedies support reliable exchange. A promise of guaranteed profits is different: institutions cannot ensure every business succeeds.","_v":"71dd824df2"},{"id":"E16-C1-OO02","prompt":"Three of these support fair entry into markets. Which is the odd one out?","options":["Transparent registration","Equal access to permits","Impartial contract enforcement","Exclusive licenses for officials' friends"],"answer":3,"why":"Transparent registration, equal permit access, and impartial enforcement make entry more open. Exclusive licenses for friends of officials favor insiders.","_v":"2c63d14a0e"},{"id":"E16-C1-OO03","prompt":"Three of these are institutional failures. Which is the odd one out?","options":["A town's only water company cutting output to raise its price","A land registry years behind on recording sales","A court that won't enforce contracts","An official who wants a bribe for a permit"],"answer":0,"why":"The registry, the court, and the bribe are rules that are missing, unenforced, or for sale. A single seller using its market power can happen even when the rules work, so it's a market failure.","_v":"4377039075"},{"id":"E16-C1-OO04","prompt":"Three of these are market failures. Which is the odd one out?","options":["A town's only water company restricting output","A judge who rules for whoever pays him","Neighbors free riding on a flood siren","Fumes from a plant harming nearby homes"],"answer":1,"why":"Market power, free riding, and spillover costs can happen even under good rules. A judge for sale is a broken rule, an institutional failure.","_v":"ae6046197b"},{"id":"E16-C1-OO05","prompt":"Three of these are ways a promise can be enforced. Which is the odd one out?","options":["A court ordering damages","Private arbitration between club members","A posted price list","Expulsion from a trading network"],"answer":2,"why":"Courts, arbitration, and expulsion all punish a broken promise. A price list tells people the terms but does nothing if someone breaks the deal.","_v":"762b3e3783"},{"id":"E16-C1-OO06","prompt":"Three of these fix an institutional failure by removing or simplifying a rule. Which is the odd one out?","options":["Cutting a nine-step permit process to one step","Ending a rule that lets current firms veto newcomers","Dropping a license requirement for selling homemade bread","Adding a second approval office for new businesses"],"answer":3,"why":"The first three take away barriers. Adding another approval office adds one.","_v":"bc3d310017"},{"id":"E16-C1-OO07","prompt":"Three of these are transaction costs. Which is the odd one out?","options":["The flour a bakery turns into bread","Searching for a reliable supplier","Negotiating the terms of a deal","Hiring a lawyer to enforce a contract"],"answer":0,"why":"Searching, negotiating, and enforcing are costs of making a deal happen. Flour is an input to production, not a cost of trading.","_v":"fd94e5c3d0"},{"id":"E16-C1-OO08","prompt":"Three of these help a buyer trust a stranger's promise. Which is the odd one out?","options":["A contract a court will enforce","The seller saying the deal is a bargain","Ratings from the seller's past buyers","A deposit held by a neutral third party"],"answer":1,"why":"Enforcement, reputation, and a held deposit all make breaking the promise costly. The seller's own claim costs nothing to break.","_v":"6b8562d8e3"},{"id":"E16-C1-OO09","prompt":"Three of these describe the rule of law. Which is the odd one out?","options":["Rules are published in advance","The same rules apply to everyone","Officials decide each case however they see fit","Rules are enforced predictably"],"answer":2,"why":"Published, general, predictable rules are the rule of law. Case-by-case discretion is the arbitrary rule it replaces.","_v":"81347b72ae"},{"id":"E16-C1-OO10","prompt":"Three of these are informal institutions that support a market. Which is the odd one out?","options":["Vendors' association settling disputes among members","Trade group banning members who cheat customers","Neighbors keeping a shared record of who farms which plot","A national tax law passed by the legislature"],"answer":3,"why":"The first three are rules people make and enforce among themselves. A law passed by a legislature is a formal institution.","_v":"b91e7c2b84"}],"pool_target":10},{"id":"c1-missing","type":"choice","tier":1,"title":"Find the missing piece","targets":["16.1a"],"status":"draft","note":"Ported unchanged from the Chapter 16 pilot. Missing Piece is a retirement candidate (bank audit, November 1, 2026), so it is not expanded.","instructions":"Choose the idea that completes the sentence.","items":[{"id":"E16-C1-MP01","prompt":"A price can coordinate exchange only if sellers can credibly ______ the goods they offer.","options":["transfer rights to","guarantee future profits on","make non-scarce"],"answer":0,"why":"A valid sale presupposes rights that can be transferred.","_v":"2164a136a2"},{"id":"E16-C1-MP02","prompt":"A contract is much more credible when a dispute can be resolved through ______.","options":["an impartial enforcement process","a private friendship only","higher advertising spending"],"answer":0,"why":"Promises are more valuable when performance can be enforced.","_v":"ea5d0e9f00"}],"pool_exception":"Find the Missing Piece is a retirement candidate; it keeps its ported items only."},{"id":"c1-applied","type":"choice","tier":2,"title":"Applied cases","targets":["16.1a","16.1c"],"status":"draft","items":[{"id":"E16-C1-AP01","prompt":"A town removes entry restrictions but stops enforcing private contracts. Which prediction best follows?","options":["Trade will necessarily rise because entry is now free.","Entry becomes easier, but unreliable enforcement can still discourage exchange.","No trade can occur under any circumstances.","Removing licensing rules automatically establishes secure property titles."],"answer":1,"why":"Open entry and credible enforcement are different institutional supports. Improving one while weakening another creates competing effects.","_v":"5240939826"},{"id":"E16-C1-AP02","prompt":"A seller cannot prove title to land. The main problem is…","options":["Unclear rights obstruct legitimate sale","Low demand","Overproduction"],"answer":0,"why":"Ownership is necessary to transfer rights.","_v":"cd3cae90a6"},{"id":"E16-C1-AP03","prompt":"An incumbent can veto all new competitors. Which reform helps most?","options":["Raise prices","Open fair entry","Prohibit contracts"],"answer":1,"why":"Competition needs entry opportunities.","_v":"f6b3f87d15"},{"id":"E16-C1-AP04","prompt":"Contracts are enforced only for the mayor's allies. What is missing?","options":["More consumer spending","Lower wages","Impartial enforcement"],"answer":2,"why":"Favoritism damages trust.","_v":"0bbd021fff"},{"id":"E16-C1-AP05","prompt":"A reliable land registry is introduced. What may improve?","options":["Investment due to clearer title","Weather forecasts","Physical land supply"],"answer":0,"why":"Clear title lowers uncertainty.","_v":"e1c6bf660b"},{"id":"E16-C1-AP06","prompt":"A city requires a $4,000 license and three inspections before anyone can sell coffee from a cart. Many people want coffee, but few carts open. What kind of problem is this, and what fix fits?","options":["A market failure: the city should run its own coffee carts.","An institutional failure: easing or removing the license rule could let sellers enter.","A market failure: demand for coffee is too low to support carts.","An institutional failure: a higher license fee would screen out weak sellers."],"answer":1,"why":"Willing buyers and sellers exist, but a rule blocks entry. Here the repair is likely easing or removing the rule, not adding one.","_v":"75383982ba"},{"id":"E16-C1-AP07","prompt":"A factory follows every rule and the courts work well, but its noise lowers the value of nearby homes, and the factory doesn't pay for that harm. How is this best classified?","options":["An institutional failure, because the court must not be working","An institutional failure, because the factory holds title to its land","A market failure, because a cost spills over onto people outside the deal","No failure, because the factory followed every rule"],"answer":2,"why":"The rules are working, yet the market still produces too much of something harmful. That is a market failure.","_v":"870d08881b"},{"id":"E16-C1-AP08","prompt":"Farmers in a village have worked the same plots for decades, but none hold legal title. Banks won't lend to them. Which explanation fits best?","options":["Without title, the land can't serve as collateral, so the farmers' wealth is hard to use.","The land must produce too little to be worth anything to a bank.","It is a market failure: the farmers are free riding on each other.","Lending to the farmers directly would solve the title problem."],"answer":0,"why":"This is dead capital. The land has value, but without a recognized title it can't back a loan.","_v":"cac4a49e39"},{"id":"E16-C1-AP09","prompt":"A town's courts are fair and fast, yet a town-wide flood wall never gets built because each household waits for others to pay. Which diagnosis fits best?","options":["Institutional failure: the courts must be the cause.","Institutional failure: households lack titles to their homes.","Market failure: one firm holds too much market power.","Market failure: everyone is protected whether or not they pay, so few pay."],"answer":3,"why":"The rules work. The trouble is that non-payers can't be kept from the benefit, so free riding leaves the wall unfunded.","_v":"a345049929"},{"id":"E16-C1-AP10","prompt":"Sellers in a busy market can be sued only in a court three days' travel away. Which change would most directly make buyers more willing to pay in advance?","options":["A rule requiring all sellers to charge the same price","A local, reliable way to settle disputes, such as a court or an arbitration panel","More buyers coming to the market","A rule letting only long-established sellers stay in the market"],"answer":1,"why":"Buyers pay in advance when a broken promise has consequences. Closer enforcement makes that more likely. Shutting out newer sellers restricts entry without making anyone's promise enforceable.","_v":"e11fc8198a"},{"id":"E16-C1-AP11","prompt":"A licensing board made up of current electricians rejects most new applicants, even qualified ones. What kind of problem is this?","options":["Market failure: electricians have too few customers","Market failure: electrical work is a public good","Institutional failure: the people who control the rule use it to shut out competitors","Institutional failure: the board has too little power to enforce contracts"],"answer":2,"why":"The rule has been captured by insiders who gain from less competition. That is an institutional failure.","_v":"6b3822c667"},{"id":"E16-C1-AP12","prompt":"A neighborhood's online marketplace works well until sellers learn the site never acts on fraud complaints. Sales fall. Which statement fits best?","options":["Buyers stopped trusting sellers' promises because breaking them had no consequence.","Sales fell because the site had too many sellers.","It is a market failure caused by too much competition.","Prices were the real problem, since the price is what makes buyers trust sellers."],"answer":0,"why":"Trade depends on promises that can be enforced. When fraud goes unpunished, buyers pull back.","_v":"c315ce427f"}]},{"id":"c1-predict","type":"choice","tier":2,"title":"What changes?","targets":["16.1a"],"status":"draft","items":[{"id":"E16-C1-PR01","prompt":"A city replaces unpredictable licensing decisions with published rules and an independent appeal. Which change is most plausible?","options":["Entrants can plan with less uncertainty, although success is not guaranteed.","Property rights and contracts cease to matter.","Competition necessarily disappears.","Permits become public goods."],"answer":0,"why":"Stable, reviewable rules reduce an institutional uncertainty without guaranteeing any particular outcome.","_v":"0cf538e70d"},{"id":"E16-C1-PR02","prompt":"A market abolishes contract enforcement but keeps posted prices. What is the likely effect?","options":["Exchange can become riskier because posted prices alone cannot guarantee performance.","Posted prices automatically create enforceable rights.","All goods become non-rival.","All transactions must stop immediately."],"answer":0,"why":"Prices coordinate intentions, but credible enforcement can help parties trust promises.","_v":"dac237b246"},{"id":"E16-C1-PR03","prompt":"A country cuts the steps to register a business from twelve to two. Which change is most likely?","options":["More small businesses register and operate legally, though some still fail.","Courts may become slower, since registration no longer screens out weak firms.","Every informal business registers within a year.","Existing firms may gain market power, since fewer rules protect customers."],"answer":0,"why":"A cheaper entry process lets more firms join the formal economy. It doesn't guarantee they succeed.","_v":"b0203b2e18"},{"id":"E16-C1-PR04","prompt":"A village begins issuing legal titles for land that families already farm. Which change is most plausible?","options":["Banks may lend less, since titled land is harder to sell.","Families can more easily borrow against their land.","The amount of farmland in the village grows.","Crop prices must rise."],"answer":1,"why":"Title turns land into usable collateral. It doesn't create more land.","_v":"a15a254698"},{"id":"E16-C1-PR05","prompt":"A city's courts start resolving small business disputes in weeks instead of years. What may change?","options":["Firms may sign fewer contracts, since disputes now end faster.","Businesses no longer need contracts at all.","Suppliers may become more willing to sell on credit.","Every dispute is now settled before it reaches court."],"answer":2,"why":"Faster enforcement makes a promise to pay later more credible.","_v":"cd950e3d9d"},{"id":"E16-C1-PR06","prompt":"A trading association that used to expel cheaters stops doing so, and no court steps in. What is the likely effect?","options":["Trade among members may rise, since fewer people are expelled.","Members' promises become more reliable.","Prices in the association fall to zero.","Members may demand payment up front and trade less on trust."],"answer":3,"why":"Without a penalty for cheating, members protect themselves by trusting less.","_v":"cfd21ea218"},{"id":"E16-C1-PR07","prompt":"A province announces that its rules for mining leases will stay fixed for 20 years unless changed through a public process. Which effect is most plausible?","options":["Mining firms may be more willing to make long-term investments.","Investment may fall, since fixed rules give firms less flexibility.","The amount of ore in the ground increases.","Every mining firm becomes profitable."],"answer":0,"why":"Predictable rules lower the risk of investments that take years to pay off.","_v":"6b99262ae8"},{"id":"E16-C1-PR08","prompt":"A town ends a rule letting its three existing pharmacies veto any new pharmacy. What is the most likely result?","options":["Prices may rise, since new pharmacies raise costs for the existing ones.","New pharmacies can open, which may lower prices and widen choice.","The existing pharmacies must close.","Medicine becomes a public good."],"answer":1,"why":"Removing a rule that blocks entry lets competition work. The fix here was taking a rule away.","_v":"2b88c713fb"},{"id":"E16-C1-PR09","prompt":"An online marketplace starts refunding buyers when a seller fails to deliver, and it bans sellers who don't deliver. What is the likely effect?","options":["Fewer buyers may trade, since the rule adds risk for them.","Sellers will never fail to deliver again.","Buyers may be more willing to buy from sellers they've never met.","Prices on the site must fall."],"answer":2,"why":"Refunds and bans give sellers' promises consequences, so buyers can trust strangers more.","_v":"5b025a8156"},{"id":"E16-C1-PR10","prompt":"A land registry that was ten years behind is brought up to date. Which result is most defensible?","options":["Land values may fall, since buyers learn more about who owns what.","Land disputes end completely.","Fewer homes are sold, since the registry makes sales slower.","Buyers can check ownership more easily, though disputes over old claims may continue."],"answer":3,"why":"Better records make ownership easier to verify. They don't settle every old dispute.","_v":"429faf0565"},{"id":"E16-C1-PR11","prompt":"Police in a market district start protecting stalls only for vendors who pay them. What is the likely effect?","options":["Vendors who can't pay may invest less or leave, and trade may shrink.","Trade may grow, since more money flows to the police.","Every vendor is now equally safe.","The police now set market prices."],"answer":0,"why":"When protection of property is for sale, those who can't pay face more risk and invest less.","_v":"4ed9b30428"},{"id":"E16-C1-PR12","prompt":"A government replaces a rule that the minister personally approves every import license with a rule that any firm meeting published standards gets one. Which change is most plausible?","options":["Imports may fall, since published standards are harder to meet than a minister's approval.","More firms may import, and fewer may seek favors from the minister.","The minister gains more power over imports.","The new rule fixes import prices."],"answer":1,"why":"Clear, general standards open entry and leave less room for favoritism.","_v":"e41a1739cf"}]},{"id":"c1-repair","type":"choice","tier":2,"title":"Repair the reasoning","targets":["16.1a"],"status":"draft","note":"Carried over from #112's error items; the audit recommends rebuilding these as Spot the Blunder sorts.","items":[{"id":"E16-C1-ER01","prompt":"A mayor says: 'If we eliminate the courts, the market will become freer because we have removed a regulation.'","options":["Explain that courts can enforce rights and support voluntary exchange.","Agree, because contract enforcement is unnecessary.","Conclude all government regulation improves markets."],"answer":0,"why":"Removing enforcement can undermine, not liberate, exchange.","_v":"52f5250bbf"},{"id":"E16-C1-ER02","prompt":"A student argues: 'Allowing new firms to enter is irrelevant as long as existing firms are privately owned.'","options":["Explain that open entry affects competition and opportunities.","Treat private ownership as sufficient for competitive markets.","Ban all new firms to protect investment."],"answer":0,"why":"Private ownership and open competition are separate institutional features.","_v":"bbf3775f8c"},{"id":"E16-C1-ER03","prompt":"A student says: 'Lima's informal economy proves markets don't need rules, since people traded anyway.'","options":["Agree: the informal economy shows rules only get in the way.","People traded, but without titles and enforceable contracts they struggled to borrow, settle disputes, or grow.","The informal economy had no rules at all, which is why it stayed small.","The lesson is that the state should run the businesses itself."],"answer":1,"why":"Lima's traders built informal rules, but those couldn't do everything formal law does.","_v":"9caf7cd706"},{"id":"E16-C1-ER04","prompt":"A student says: 'Pollution is an institutional failure, because a market with good rules never produces harm.'","options":["Agree: any harm means the courts failed.","Pollution isn't a failure of any kind if the polluter followed the law.","Even under good rules, a market can produce too much of something harmful. That's a market failure.","It's an institutional failure only if the polluter is publicly owned."],"answer":2,"why":"The chapter separates the two: market failures happen even when the rules work.","_v":"32ed4484be"},{"id":"E16-C1-ER05","prompt":"A student says: 'Every institutional failure is fixed by adding more government rules.'","options":["Agree: institutional failures always come from too few rules.","Institutional failures can't be fixed, only lived with.","The fix is always to remove government from the market entirely.","Sometimes the fix is removing a rule that blocks people, like a permit no one can get."],"answer":3,"why":"The repair is a better rule. Sometimes that means a clearer title or a working court, and sometimes it means removing a rule.","_v":"ecc70bd942"},{"id":"E16-C1-ER06","prompt":"A student says: 'A contract is binding just because both people signed it.'","options":["A signature records the promise, but it has force only if someone can enforce it.","Agree: once signed, a contract can't be broken.","A contract is binding only if the government wrote its terms.","Contracts matter only for large companies."],"answer":0,"why":"A promise is worth what its enforcement is worth.","_v":"0f2ea9ac1b"},{"id":"E16-C1-ER07","prompt":"A student says: 'The diamond dealers trade on handshakes, so their market has escaped governance.'","options":["Agree: handshake deals mean no rules apply.","They rely on arbitration, membership rules, and the threat of expulsion. The market has its own governance.","Handshake deals work only because diamonds are cheap.","The handshake works because state courts enforce every one of those deals."],"answer":1,"why":"The handshake works because it calls on a dense system of private rules and penalties.","_v":"dd7afaafdf"},{"id":"E16-C1-ER08","prompt":"A student says: 'If a market has prices, it must have working institutions.'","options":["Agree: prices prove that property and contracts are enforced.","Prices appear only when the government sets them.","Prices can appear even where rules are weak. That doesn't make trade secure or able to grow.","A market with prices can't have an institutional failure."],"answer":2,"why":"Lima had prices and trade, yet weak formal rules kept businesses small.","_v":"f686e02f60"},{"id":"E16-C1-ER09","prompt":"A student says: 'A bribe-taking permit officer is a market failure, because the market for permits isn't working.'","options":["Agree: any problem involving money is a market failure.","It's a market failure because too few permits are produced.","It's not a failure, since the business got its permit.","The rule is being sold to insiders. That's an institutional failure."],"answer":3,"why":"The trouble is with the rule and its enforcement, not with buyers and sellers under working rules.","_v":"7f1cab2a81"},{"id":"E16-C1-ER10","prompt":"A student says: 'Transaction costs are just the price of the good, so they can't block a deal both sides want.'","options":["Transaction costs are the costs of finding, negotiating, and enforcing. When they're high, good deals can fail to happen.","Agree: if both sides want a deal, it always happens.","Transaction costs exist only in markets with no rules.","Only the government pays transaction costs."],"answer":0,"why":"High transaction costs can stop deals that would help everyone.","_v":"c306f516bc"},{"id":"E16-C1-ER11","prompt":"A student says: 'Removing a rule always makes a market freer.'","options":["Agree: every rule limits freedom.","Removing a rule that blocks entry can help, but removing courts or titles can make trade harder.","Removing rules always makes a market less free.","Rules have no effect on how free a market is."],"answer":1,"why":"The question is never rules versus freedom. It's which rules.","_v":"7e09a82041"},{"id":"E16-C1-ER12","prompt":"A student says: 'Seller ratings on a website are useless, because only courts can enforce promises.'","options":["Agree: only government can make a promise credible.","Ratings enforce promises only when a court reviews them.","Reputation can enforce promises too, since cheaters lose future buyers.","Ratings affect prices but not trust."],"answer":2,"why":"Reputation networks are a real enforcement institution, as the diamond dealers show.","_v":"8e3c1ecb9c"}]},{"id":"c1-ap","type":"choice","tier":3,"title":"AP-style questions","targets":["16.1a","16.1c"],"status":"draft","items":[{"id":"E16-EX-001","prompt":"A farmer and a buyer agree on the price of a parcel, but two families claim to own it. The transaction stalls. Which explanation best identifies the obstacle?","options":["The parties' agreement proves legal transfer is possible, so the remaining barrier must be low demand.","Competing ownership claims make a credible transfer difficult despite the agreed price.","The obstacle is chiefly weak competition among buyers, not the title itself.","The deal can proceed securely if the buyer promises to accept any later court ruling."],"answer":1,"why":"The parties have found a price, but a market transaction also requires a credible claim to transfer the parcel. Clarifying title addresses an institutional problem.","_v":"57295cec01"},{"id":"E16-EX-002","prompt":"A city eliminates permit fees, but the mayor still chooses which new firms may enter based on personal connections. Which conclusion is most defensible?","options":["Removing official fees necessarily makes entry competitive, even if approvals stay discretionary.","Lower fees remove one cost, but selective permission still protects some firms from entry.","The main remaining obstacle is a lack of enforceable private titles rather than the approval rule.","Personal discretion matters only if an official actually collects a bribe."],"answer":1,"why":"Removing a fee may reduce one cost; arbitrary favoritism can still obstruct open entry and investment.","_v":"0bda95bdaf"},{"id":"E16-EX-004","prompt":"A port official demands a payment to process routine documents. One firm pays and ships early. What is the strongest evaluation of the payment's broader effects?","options":["The faster shipment is evidence that the permit system's net social benefits exceed its costs.","The payment changes only the distribution of government revenue and not firm incentives.","One applicant may benefit while officials gain incentives to delay others or favor payers.","If the payment is unofficial, the firm cannot receive any genuine private benefit."],"answer":2,"why":"Separate the firm's private incentive from the institution-wide incentive for officials to create or exploit bottlenecks.","_v":"d8aab8930d"},{"id":"E16-EX-006","prompt":"A lighthouse shines toward a busy shipping channel. Its visible warning signal is available to every passing vessel, and one ship's use does not meaningfully diminish its usefulness to others. The operator cannot feasibly restrict who sees the signal. Which conclusion follows?","options":["The signal is rival because additional ships require separate light, though access is hard to restrict.","The signal is non-rival and hard to exclude, so some beneficiaries may avoid paying.","The signal is excludable whenever the lighthouse has a private operator, even without access controls.","The signal is non-rival, but that alone establishes no financing concern because every user benefits."],"answer":1,"why":"The signal is non-rival and hard to exclude from use. Free riding may make selling access difficult.","_v":"bd872f02c2"},{"id":"E16-EX-007","prompt":"Two countries have similar resources and entrepreneurial talent. In one, newcomers can register land and enforce contracts cheaply; in the other, officials favor insiders. Which inference is warranted?","options":["The contrast suggests a mechanism by which institutions could affect entry and investment, but cannot alone isolate their causal effect.","Similar resources and talent are sufficient controls to establish that institutional differences caused all later growth.","The countries must invest equally because productive opportunities are initially similar.","Political favoritism matters only for income distribution, not entry or expected returns."],"answer":0,"why":"Economic mechanisms support a plausible prediction, but cross-country comparisons do not independently establish causation.","_v":"dcf9818395"},{"id":"E16-EX-013","prompt":"A market platform verifies sellers' identities but cannot ensure they deliver goods after payment. Which additional institution would most directly improve exchange?","options":["A reputation system eliminates the need for any enforcement if enough sellers receive favorable ratings.","Credible contract enforcement adds consequences when a verified seller fails to perform.","Allowing buyers to pay later removes the problem without introducing another risk.","Publishing ownership claims guarantees that every verified seller will deliver."],"answer":1,"why":"Verification helps identify counterparties; enforcement makes promises credible. Both support exchange.","_v":"c74a60801f"},{"id":"E16-EX-014","prompt":"Two equally productive firms apply for permits. The incumbent receives approval automatically, while the newcomer must negotiate a discretionary payment. Which principle is most threatened?","options":["The firms face unequal entry conditions because discretionary approval privileges the incumbent.","The market chiefly suffers from weak enforcement of contracts between the applicants and their customers.","The problem is only a higher administrative fee, not how approvals are allocated.","Entry is competitive if both companies can submit applications regardless of unequal decisions."],"answer":0,"why":"Discretionary advantage changes the terms of entry, potentially protecting insiders regardless of productivity.","_v":"85ac05e4f6"},{"id":"E16-EX-015","prompt":"A digital marketplace permits anyone to list products, but sellers cannot establish legal ownership. Which conclusion best follows?","options":["Open listing access cannot establish the seller's authority to transfer the claimed asset.","Open entry guarantees that buyers can enforce ownership rights against third parties.","The main obstacle is insufficient demand rather than disputed entitlements.","An advertised price determines ownership once a buyer accepts it."],"answer":0,"why":"An open platform is not enough when sellers lack credible rights to transfer what they offer.","_v":"67cb6dddb2"},{"id":"E16-EX-016","prompt":"An impartial court system exists, but changes in permit eligibility are announced only after applications close. What institutional improvement is most relevant?","options":["Raise eligibility requirements to ensure that fewer unsuccessful applicants waste resources.","Permit only incumbent firms so firms can invest under known rules.","Announce entry criteria before applications and apply them consistently.","Shift all entry decisions to the same courts that enforce private contracts."],"answer":2,"why":"Predictable rules allow firms to plan; impartial courts cannot undo every cost of arbitrary regulatory surprises.","_v":"addc759d3a"},{"id":"E16-EX-019","prompt":"A factory's emissions damage a neighbor's crops. Both parties own their land. Which conclusion is most defensible?","options":["The factory's title automatically authorizes any use that increases its profits.","The neighbor may claim damages only if the factory never held title.","The rights and remedies must account for the factory's use and the neighbor's harm; ownership is not unlimited.","The relevant entitlements can be determined from total production alone without legal rules."],"answer":2,"why":"Clear rights are essential precisely because ownership does not entail unrestricted harm to others.","_v":"083cebb972"},{"id":"E16-EX-020","prompt":"A buyer obtains a clear title but lenders still refuse collateral because courts rarely execute judgments. What is the remaining problem?","options":["Poor enforcement can make recorded collateral rights hard to realize after default.","Accurate title automatically makes foreclosure reliable even if courts will not act.","The main unresolved problem is simply whether buyers can find the property on a map.","Lenders' reluctance proves that the asset has no economic value."],"answer":0,"why":"Title clarifies the claim; enforceability helps make the claim credible to lenders.","_v":"3eabc32bb2"},{"id":"E16-EX-022","prompt":"A company spends more on lobbying for an exclusive license than improving its product. Which economic mechanism best explains the concern?","options":["The firm may be rent-seeking: expending resources to secure privileges rather than compete on productivity.","The firm's lobbying expenditures show that the license will necessarily reduce prices.","Seeking special protection is economically equivalent to investing in a new production method.","The lobbying demonstrates corruption in every case, independent of legality or influence."],"answer":0,"why":"The issue is the incentive to gain through special protection rather than productivity; not all lobbying is illegal.","_v":"d0ba17fd9a"},{"id":"E16-EX-024","prompt":"A well-connected supplier receives a contract despite a higher bid and weaker quality. Which consequence is most plausible?","options":["A higher winning bid establishes that the supplier's quality-adjusted costs must be lowest.","Favoritism may reduce competitive discipline and the value obtained for public spending.","The outcome shows only a distributional change among suppliers, not any potential efficiency cost.","Competition must increase because other suppliers will respond with stronger bids regardless of future access."],"answer":1,"why":"Favored selection can distort competition and reduce value, though the magnitude requires evidence.","_v":"98d7c3db97"},{"id":"E16-EX-028","prompt":"A village considers both stocking a depleted fishery and constructing a warning siren. Which policy comparison is best?","options":["Both problems can be solved solely by producing more physical resources, without changing incentives.","The fishery and siren should both charge identical per-use prices because both are non-rival.","The fishery's chief issue is free riding on consumption; the siren's chief issue is depletion from use.","The fishery needs institutions that manage rival harvesting; siren financing must address benefits that are hard to exclude."],"answer":3,"why":"Common-resource overuse and public-good underprovision involve different mechanisms and need not have the same solution.","_v":"1f09db5b81"},{"id":"E16-EX-101","prompt":"City A's restaurant permit takes 14 months and needs approval from a board of existing restaurant owners. City B issues permits in two weeks under published criteria, but fumes from a nearby plant keep diners away from its downtown. Which comparison is most accurate?","options":["Both cities face market failures, since demand for restaurants is low in each.","Both cities face institutional failures, since any bad outcome traces back to the rules.","City A faces an institutional failure that easing the rule might fix; City B faces a market failure from a spillover cost.","City A faces a market failure, since restaurants have few competitors; City B faces an institutional failure, since its rules are published."],"answer":2,"why":"City A's barrier is a captured entry rule. City B's rules work, but a cost spills onto diners and restaurants, which is a market failure.","_v":"b624caf1be"},{"id":"E16-EX-102","prompt":"Two regions have similar soil. In one, farmers hold legal titles and borrow against them. In the other, families farm the same plots by custom, without title, and few loans are made. Which conclusion is most defensible?","options":["The untitled region must have poorer land, since banks lend only on productive land.","Low demand for credit probably explains the gap, so titles would likely make little difference.","Granting titles will necessarily double farm output within a few years.","Untitled land is hard to use as collateral, so formal title may help farmers invest, though custom can still support farming."],"answer":3,"why":"Custom can organize farming, but lenders need a claim they can enforce. Title may unlock investment, though the comparison alone can't show how much.","_v":"1b2811cea9"}]}]},{"id":"c2","number":2,"name":"Property Rights","activities":[{"id":"c2-sort","type":"sort","tier":1,"title":"Sort the cases","targets":["16.2a"],"status":"draft","bins":["Use","Exclude","Transfer","Enforce"],"round_size":6,"cards":[{"id":"E16-C2-F01","text":"A landowner grows vegetables on land they are entitled to cultivate","bin":0,"why":"Cultivating permitted land is an exercise of use rights.","_v":"c1b9653159"},{"id":"E16-C2-F02","text":"An owner lawfully bars unauthorized access to a locked workshop","bin":1,"why":"Exclusion is the ability to restrict access.","_v":"f10678c04f"},{"id":"E16-C2-F03","text":"A farmer sells legally transferable land to a neighbor","bin":2,"why":"Transfer means moving ownership claims to another party.","_v":"8e40d4f644"},{"id":"E16-C2-F04","text":"A property owner seeks a legal remedy after unlawful damage","bin":3,"why":"Enforcement protects a recognized claim through remedies.","_v":"76e1c45cc4"},{"id":"E16-C2-F05","text":"An owner changes an approved workshop into a permitted shop","bin":0,"why":"Ordinary use can change within the limits of existing rights.","_v":"512ceef61f"},{"id":"E16-C2-F06","text":"A tenant bars entry by someone who has no permission to enter","bin":1,"why":"Even a tenant can hold defined exclusion rights.","_v":"95aff8be66"},{"id":"E16-C2-F07","text":"A parent gives a bicycle they own to a child","bin":2,"why":"Gifting a claim transfers ownership without a sale.","_v":"a46036d272"},{"id":"E16-C2-F08","text":"A landowner asks a court to enforce a recorded easement","bin":3,"why":"Seeking a remedy is enforcement of an existing entitlement.","_v":"6fc039e3f4"},{"id":"E16-C2-F09","text":"A tenant with subletting permission leases a room to another tenant","bin":2,"why":"The contract transfers a limited right of occupancy, not necessarily title.","_v":"9a43a388a0"},{"id":"E16-C2-F10","text":"An author licenses specified publishing rights to a company","bin":2,"why":"A license grants defined rights for a specified use or term.","_v":"078f0f942a"},{"id":"E16-C2-F11","text":"A homeowner turns her garage into a home office, as local rules allow","bin":0,"why":"Putting your own property to a permitted purpose is use.","_v":"875bd93d7d"},{"id":"E16-C2-F12","text":"A farmer plants corn instead of wheat on his own field","bin":0,"why":"Deciding what to grow on your land is part of the right to use it.","_v":"e9c539a350"},{"id":"E16-C2-F13","text":"A student rides her own bike to class","bin":0,"why":"Riding a bike you own is ordinary use.","_v":"ec17c7a32e"},{"id":"E16-C2-F14","text":"A renter cooks meals in the apartment kitchen her lease covers","bin":0,"why":"A lease gives the renter a right to use the space it covers.","_v":"7ade50b9f1"},{"id":"E16-C2-F15","text":"A farmer stops hunters from entering his land without permission","bin":1,"why":"Keeping others off your land is the right to exclude.","_v":"2c2496a139"},{"id":"E16-C2-F16","text":"A software company's program won't open without a paid account login","bin":1,"why":"The login keeps people who haven't paid from using the program.","_v":"c73bb23b01"},{"id":"E16-C2-F17","text":"A homeowner tells a stranger to leave her backyard","bin":1,"why":"Telling someone without permission to leave is exclusion.","_v":"cdfd58443b"},{"id":"E16-C2-F18","text":"A gym lets only members through its front door","bin":1,"why":"Checking membership at the door keeps non-members out.","_v":"524d59a2f9"},{"id":"E16-C2-F19","text":"A grandmother leaves her house to her grandson in her will","bin":2,"why":"Inheritance passes ownership to someone else.","_v":"a58913e87a"},{"id":"E16-C2-F20","text":"A musician sells the rights to one of her songs to a record label","bin":2,"why":"Selling the song's rights moves them to the label.","_v":"167aa32f28"},{"id":"E16-C2-F21","text":"A shop owner sues a supplier who took payment but never delivered","bin":3,"why":"Going to court for a remedy is enforcement.","_v":"bb5627abaf"},{"id":"E16-C2-F22","text":"A car owner asks the police to return her stolen car","bin":3,"why":"Calling on police to restore a recognized claim is enforcement.","_v":"4dda50a4f7"},{"id":"E16-C2-F23","text":"A farmer goes to court after a neighbor's cattle trample his crops","bin":3,"why":"Asking a court for compensation after damage is enforcement.","_v":"c66d47020e"},{"id":"E16-C2-F24","text":"A landlord gets a court order to remove a tenant who stopped paying rent","bin":3,"why":"A court order backs up the landlord's claim; that is enforcement.","_v":"7c80b2a476"}]},{"id":"c2-match","type":"match","tier":1,"title":"Memory Match","targets":["16.2a"],"status":"draft","board_size":6,"pairs":[{"id":"E16-C2-MM01","left":"Use","right":"Exercise a legally recognized use of a resource, within its limits.","_v":"22dd3a6be9"},{"id":"E16-C2-MM02","left":"Exclude","right":"Restrict unauthorized use or access.","_v":"057e131bf4"},{"id":"E16-C2-MM03","left":"Transfer","right":"Sell, gift, license, or otherwise convey specified rights.","_v":"4d2a62db40"},{"id":"E16-C2-MM04","left":"Enforce","right":"Obtain a remedy when a recognized right is violated.","_v":"fb6d5f1941"},{"id":"E16-C2-MM05","left":"Enforcement","right":"Making agreed rights and obligations meaningful through consistent remedies.","_v":"3468755523"},{"id":"E16-C2-MM06","left":"Secure title","right":"Credible evidence of ownership that enables transfer and collateral.","_v":"2c3398898f"},{"id":"E16-C2-MM07","left":"Property rights","right":"A bundle of claims: use, sell, improve, exclude, transfer, and seek compensation.","_v":"6e657a7f3a"},{"id":"E16-C2-MM08","left":"Rule of law","right":"Rules are public, stable, and applied to everyone the same way.","_v":"dc3a52af80"},{"id":"E16-C2-MM09","left":"Liability rules","right":"Decide who must pay when one party's actions harm another.","_v":"31835737bf"},{"id":"E16-C2-MM10","left":"Enforceable contract","right":"An agreement a court will stand behind if one side breaks it.","_v":"d2d9e15f6f"},{"id":"E16-C2-MM11","left":"Improve","right":"Invest in a resource to make it worth more, such as building on land.","_v":"50225aef61"},{"id":"E16-C2-MM12","left":"Dead capital","right":"Assets people hold but can't borrow against because they lack legal title.","_v":"def048e64c"},{"id":"E16-C2-MM13","left":"Collateral","right":"Something a borrower pledges that the lender can claim if the loan isn't repaid.","_v":"5366204154"},{"id":"E16-C2-MM14","left":"Charter city","right":"A new jurisdiction built on a trusted package of rules for property, courts, and contracts.","_v":"9241afe9d3"},{"id":"E16-C2-MM15","left":"Market for institutions","right":"Places compete to offer better rules, and people and capital move toward the best ones.","_v":"c386d066ae"},{"id":"E16-C2-MM16","left":"Friedman's airplane","right":"Nothing in nature marks where airspace rights end, so someone has to draw the line.","_v":"78bfa16a7f"}]},{"id":"c2-detective","type":"detective","tier":1,"title":"Definition Detective","targets":["16.2a"],"status":"draft","rounds":[{"id":"E16-C2-DD01","term":"Property rights","answers":[{"text":"Property rights specify recognized claims to use, exclude, transfer, and seek enforcement within lawful limits.","grade":"A","why":"Ownership involves a set of rights and responsibilities, not unlimited control."},{"text":"Property rights let owners use resources.","grade":"A-","why":"Use is important, but exclusion, transfer, and enforcement are also part of the bundle."},{"text":"Property rights permit owners to ignore all laws and obligations.","grade":"F","why":"Rights can have legitimate limits and duties."}],"_v":"1307a8e6c4"},{"id":"E16-C2-DD02","term":"Transfer rights","answers":[{"text":"Transfer rights allow a holder to sell, gift, or otherwise convey specified rights to someone else.","grade":"A","why":"Transfer is about passing recognized rights to another party, subject to applicable rules."},{"text":"Transfer rights let an owner sell an asset.","grade":"A-","why":"A sale is one example, but rights may also be conveyed through gifts, leases, or licenses."},{"text":"Transfer rights mean that anyone may sell a resource even if they have no claim to it.","grade":"F","why":"Valid transfer requires an underlying right to convey."}],"_v":"3739626c39"},{"id":"E16-C2-DD03","term":"Rule of law","answers":[{"text":"Rules are public, stable, and known in advance, and they apply to everyone the same way.","grade":"A","why":"It names both parts: rules people can know ahead of time, applied equally."},{"text":"Rule of law means a country has written laws.","grade":"A-","why":"Written laws help, but they also have to be stable and applied the same way to everyone."},{"text":"Rule of law means whoever holds power decides each case as they see fit.","grade":"F","why":"That is the opposite: outcomes that depend on power or favoritism."}],"_v":"40a6de3a77"},{"id":"E16-C2-DD04","term":"Liability rules","answers":[{"text":"Rules that decide who is responsible, and who must pay, when one party harms another.","grade":"A","why":"It names both the responsibility and the compensation."},{"text":"Liability rules say that people who cause harm are to blame.","grade":"A-","why":"Blame is part of it, but the rules also decide who must compensate whom."},{"text":"Liability rules make sure no one ever pays for harm they cause by accident.","grade":"F","why":"Liability rules exist to assign who pays, accidents included."}],"_v":"3b0ce9bbaf"},{"id":"E16-C2-DD05","term":"Contract enforcement","answers":[{"text":"Reliable enforcement of voluntary agreements, so promises about payment, delivery, or work have legal force.","grade":"A","why":"It says what is enforced and why it matters: promises gain teeth."},{"text":"Contract enforcement means people sign written agreements.","grade":"A-","why":"Signing is only the start; enforcement means someone will make the promise hold."},{"text":"Contract enforcement means the government decides what every contract must say.","grade":"F","why":"Enforcement backs up what the parties agreed; it doesn't write their deals."}],"_v":"d01512c757"},{"id":"E16-C2-DD06","term":"Dead capital","answers":[{"text":"Assets people own informally but can't use as collateral or sell easily, because they lack recognized title.","grade":"A","why":"It names the asset, what it can't do, and why."},{"text":"Dead capital is property without legal title.","grade":"A-","why":"That's the cause, but the term is about what it costs: the asset can't back loans or easy sales."},{"text":"Dead capital is property that has lost all its value.","grade":"F","why":"A house without title can still be valuable to live in; it just can't be used as collateral."}],"_v":"bd7c1769d9"},{"id":"E16-C2-DD07","term":"Courts","answers":[{"text":"Institutions that resolve disputes, enforce contracts, assign liability, and order compensation.","grade":"A","why":"It lists the jobs the chapter gives courts."},{"text":"Courts are where people go to settle disputes.","grade":"A-","why":"True, but courts also enforce contracts, assign liability, and order compensation."},{"text":"Courts are only needed when a market has failed.","grade":"F","why":"Courts support ordinary exchange every day; a working court is part of what lets markets run."}],"_v":"de9b387c79"},{"id":"E16-C2-DD08","term":"Right to exclude","answers":[{"text":"The recognized right to keep others from using or entering what you own, backed by rules that enforce it.","grade":"A","why":"It names the right and the rules that make it real."},{"text":"The right to exclude means you can lock your door.","grade":"A-","why":"A lock helps, but the right is the recognized claim to keep others out, which rules and courts back up."},{"text":"The right to exclude exists in nature, so no rule or court is needed to protect it.","grade":"F","why":"Rights are defined and enforced by people; without enforcement the right does little.","misconception":null}],"_v":"1e35592d64"}]},{"id":"c2-odd","type":"choice","tier":1,"title":"Odd one out","targets":["16.2a","16.2c","16.2d"],"status":"draft","note":"Ported from the Chapter 16 pilot (Odd One Out, a pilot interaction), shown as single choice.","items":[{"id":"E16-C2-OO01","prompt":"Three of these are parts of a property owner's recognized rights. Which is the odd one out?","options":["Lawful use","Exclusion of unauthorized users","Transfer of recognized claims","Freedom to ignore every safety rule"],"answer":3,"why":"Lawful use, exclusion, and transfer are elements of property rights. Unlimited freedom to ignore safety laws is not.","_v":"e7823bb57d"},{"id":"E16-C2-OO02","prompt":"Three of these make ownership claims more secure. Which is the odd one out?","options":["Reliable title records","Fair contract enforcement","Accessible dispute resolution","Selling land without proof of ownership"],"answer":3,"why":"Records, fair enforcement, and dispute resolution make ownership credible. Allowing unverified sales undermines those safeguards.","_v":"02138d6d3a"},{"id":"E16-C2-OO03","prompt":"Three of these are quiet assumptions behind an ordinary exchange. Which is the odd one out?","options":["Rule of law","A guaranteed profit for every seller","Liability rules","Enforceable contracts"],"answer":1,"why":"Rule of law, liability rules, and enforceable contracts are rows in the chapter's table. No working market guarantees anyone a profit.","_v":"e3732d9a5b"},{"id":"E16-C2-OO04","prompt":"Three of these use the right to transfer. Which is the odd one out?","options":["Selling a house","Giving a bike to a cousin","Locking a shed so no one else can use it","Licensing a song to a film studio"],"answer":2,"why":"Selling, giving, and licensing pass rights to someone else. Locking a shed is exclusion.","_v":"b5790548ef"},{"id":"E16-C2-OO05","prompt":"Three of these use the right to exclude. Which is the odd one out?","options":["A farmer enforces a \"No trespassing\" sign","A theater checks tickets at the door","A homeowner paints her kitchen","An app requires a paid login"],"answer":2,"why":"Signs, ticket checks, and logins keep people out. Painting your kitchen is use.","_v":"6c6415da19"},{"id":"E16-C2-OO06","prompt":"Three of these enforce a right. Which is the odd one out?","options":["Planting a garden on your own lot","Suing a driver who damaged your car","Asking police to remove someone from your land","A dealers' club expelling a member who broke a deal"],"answer":0,"why":"Suing, calling the police, and a club's expulsion all impose a consequence for breaking a right or promise. Planting a garden is use.","_v":"5009ccb0f5"},{"id":"E16-C2-OO07","prompt":"Three of these are rights that exist on paper but do little. Which is the odd one out?","options":["A contract the courts won't enforce","A land title the police won't defend","A lease the landlord can break with no penalty","A deed a court enforces within a week"],"answer":3,"why":"The first three lack enforcement. A deed that a court backs quickly is a working right.","_v":"bdcc5720e9"},{"id":"E16-C2-OO08","prompt":"Three of these are reasons secure ownership encourages investment. Which is the odd one out?","options":["Owners keep the gains from improving their land","A title can back a loan","A guaranteed price for the owner's crops","Owners can sell their improvements later"],"answer":2,"why":"Keeping gains, borrowing against title, and selling improvements all come from secure rights. Secure ownership doesn't guarantee any price.","_v":"52a92d1cd8"},{"id":"E16-C2-OO09","prompt":"Three of these lower the cost and risk of exchange. Which is the odd one out?","options":["A reliable court","A rule that changes depending on who asks","A working land registry","A trusted payment system"],"answer":1,"why":"Courts, registries, and payment systems work like tools that make trade safer. A rule that shifts with the asker adds risk.","_v":"ec94b9b56e"},{"id":"E16-C2-OO10","prompt":"Three of these show a broken quiet assumption. Which is the odd one out?","options":["A judge sides with whoever pays more","A shop raises its price when demand rises","A land registry is years behind","No rule says who pays when a dam floods a farm"],"answer":1,"why":"A biased judge, a stalled registry, and a missing liability rule are institutional failures. A price rising with demand is the market working as usual.","_v":"740b0d1d95"}],"pool_target":10},{"id":"c2-missing","type":"choice","tier":1,"title":"Find the missing piece","targets":["16.2a","16.2c"],"status":"draft","note":"Ported from the Chapter 16 pilot. Missing Piece is a retirement candidate (bank audit, November 1, 2026); kept at its pilot size.","items":[{"id":"E16-C2-MP01","prompt":"To sell a parcel legitimately, the seller needs a recognized right to ______.","options":["transfer","eliminate all scarcity of","ignore all neighboring rights to"],"answer":0,"why":"Transfer is a distinct element in the bundle.","_v":"c847f9b337"},{"id":"E16-C2-MP02","prompt":"Clear title and reliable remedies can lower the cost of ______ ownership before exchange.","options":["verifying","turning rival land into non-rival","abolishing"],"answer":0,"why":"Records and courts make ownership easier to verify.","_v":"9d27d19176"}],"pool_exception":"Find the Missing Piece is a retirement candidate; it keeps its ported items only."},{"id":"c2-applied","type":"choice","tier":2,"title":"Applied cases","targets":["16.2c","16.2d"],"status":"draft","items":[{"id":"E16-C2-AP01","prompt":"Two neighbors dispute where a fence belongs. Best first step?","options":["Identify and document the boundary","Raise the fence immediately","Ignore ownership"],"answer":0,"why":"Clear entitlements can support bargaining.","_v":"100fc4e3ea"},{"id":"E16-C2-AP02","prompt":"A lease contract is valid but cannot be enforced. Which right is undermined?","options":["Use","Enforcement","Transfer"],"answer":1,"why":"Rights need practical remedies.","_v":"2760800a27"},{"id":"E16-C2-AP03","prompt":"Nine owners agree to grant access but the tenth holds out. This suggests…","options":["No scarcity","Non-rival consumption","A bargaining or holdout problem"],"answer":2,"why":"Multiple rights holders complicate negotiation.","_v":"3bca3400a8"},{"id":"E16-C2-AP04","prompt":"A farmer has a title but cannot transfer it. Which part of ownership is restricted?","options":["Transfer","Use","Exclusion"],"answer":0,"why":"Ownership bundles can differ.","_v":"40322bc3de"},{"id":"E16-C2-AP05","prompt":"A city offers compensation to acquire private land for a road. Why might a dispute still remain?","options":["Payment automatically settles all questions about rights.","The land immediately becomes non-rival.","Valuation, procedure, and the legitimacy of the taking can remain contested.","All property rights disappear whenever infrastructure is proposed."],"answer":2,"why":"Compensation may matter, but ownership disputes also involve legal process, valuation, and limits on state authority.","_v":"19e2f7ee65"},{"id":"E16-C2-AP06","prompt":"A town's land registry is accurate, but its judges rule for whoever pays them the most. Which quiet assumption has broken?","options":["Clear property rights","Rule of law","Excludability","Liability rules"],"answer":1,"why":"The records are fine. The rules aren't applied the same way to everyone, so outcomes depend on money and favoritism.","_v":"ee1215473c"},{"id":"E16-C2-AP07","prompt":"A chemical plant leaks into a stream and ruins a fish farm downstream. No rule says who must pay for the damage. Which quiet assumption is missing?","options":["Excludability","Enforceable contracts","Liability rules","Rule of law"],"answer":2,"why":"Liability rules decide who must compensate whom when one party harms another. Without them, the cost lands on the fish farm.","_v":"b4ef9da163"},{"id":"E16-C2-AP08","prompt":"A city decides each building permit by a council vote, and the rules for approval change from month to month. Developers stop starting long projects. Which quiet assumption has broken?","options":["Excludability","Clear property rights","Liability rules","Rule of law"],"answer":3,"why":"Rule of law means rules are known in advance and stable. When they shift unpredictably, investing becomes a bet on politics.","_v":"dae040e015"},{"id":"E16-C2-AP09","prompt":"A bakery delivers bread to a café every week, but the café often skips payment, and local courts won't hear small claims. What is most likely to happen to trade?","options":["The bakery raises its price, and the amount of bread it sells stays the same.","The bakery deals only with customers it already trusts or asks for cash up front, so trade shrinks.","This is a market failure, so the fix is a price cap on bread.","Nothing changes, since the bakery and café already agreed on a price."],"answer":1,"why":"When agreements can't be enforced, sellers protect themselves by trading less and only with people they trust.","_v":"bc0c6a6b6d"},{"id":"E16-C2-AP10","prompt":"No rule once said how low a drone could fly over a farm. A town now sets a limit: drones must stay at least 200 feet up. What does this show about property rights?","options":["The farm's airspace right existed in nature, and the town just discovered where it ends.","Property rights cover only land on the ground, not the air above it.","Property rights are drawn by people; someone had to decide where the farm's airspace ends.","Setting a limit takes away the farmer's property rights."],"answer":2,"why":"Like Friedman's airplane, nothing in nature marks the line. A social rule has to draw it and enforce it.","targets":["16.2b"],"_v":"ab67184399"},{"id":"E16-C2-AP11","prompt":"A family holds a recorded title to their house, but the police won't remove squatters, and courts take ten years to hear a case. How much does the title protect them?","options":["Little. A right no one will enforce does not keep the squatters out.","Fully, because the record proves who owns the house.","Fully, because the squatters can't legally sell the house.","It depends only on how much buyers want the house."],"answer":0,"why":"A recorded title names the owner, but without enforcement the family can't actually use or exclude.","_v":"5c2a3d0cc4"},{"id":"E16-C2-AP12","prompt":"A shop owner in a city with no formal titles has a valuable building but can't get a bank loan. Which explanation fits the chapter best?","options":["Banks don't lend to small businesses when demand is low.","The building can't be used as collateral, so the bank can't count on claiming it if the loan isn't repaid.","The owner needs a lower interest rate, not a title.","The building has no value until it has a title."],"answer":1,"why":"This is de Soto's dead capital: without recognized title, an asset can't back a loan, even though it is worth something.","_v":"f4c57e93b1"}]},{"id":"c2-predict","type":"choice","tier":2,"title":"What changes?","targets":["16.2d"],"status":"draft","items":[{"id":"E16-C2-PR01","prompt":"A land-title registry becomes searchable online, while fraud penalties remain unenforced. Which outcome is most defensible?","options":["Verification can get easier, but fraudulent transfer risks can remain.","Land becomes non-rival.","All mortgages are automatically safe.","The registry eliminates every dispute."],"answer":0,"why":"Records and enforceable remedies are complementary, not identical.","_v":"cb523821b5"},{"id":"E16-C2-PR02","prompt":"Neighbors define and record access rights for a shared driveway. What is likely to change?","options":["Uncertainty over permitted uses may decline, though disputes or congestion can persist.","Every owner loses their title.","The driveway becomes a pure public good.","Access must now be free to everyone."],"answer":0,"why":"Specified rights help coordinate use without eliminating every physical or bargaining problem.","_v":"149acffb07"},{"id":"E16-C2-PR03","prompt":"A country moves its land records from paper books in one office to a public online registry. Courts keep enforcing titles as before. What is the most likely change?","options":["Checking who owns a parcel gets cheaper, so more land is bought, sold, and used as collateral.","Land prices must fall because buyers now know more.","Trade in land may grow somewhat, but only if the government also cuts land taxes.","Banks stop asking for collateral because the records are public."],"answer":0,"why":"Easier verification lowers the cost of exchange. With courts still enforcing titles, the records become more useful.","_v":"e024bfd833"},{"id":"E16-C2-PR04","prompt":"A city that took six months to approve a home bakery now publishes a clear checklist and approves applications in a week. What is likely to change?","options":["Fewer bakeries may open, since easy approval tends to scare off customers.","More people start small bakeries legally, since the rules are known and quick to meet.","Nothing changes, since a license is still required.","Bread prices must rise because the city added a checklist."],"answer":1,"why":"Rules that are clear and known in advance lower the cost of entry. The license still exists; it just no longer blocks people.","_v":"b96877414a"},{"id":"E16-C2-PR05","prompt":"A state passes a rule that a factory must pay for crop damage its smoke causes nearby farms. What is the most likely change?","options":["The farms lose their property rights over their crops.","Smoke damage may continue unchanged, since rules rarely affect a firm's choices.","The factory's land stops being private property.","The factory now counts the damage as a cost, for example by adding filters or cutting output."],"answer":3,"why":"A liability rule puts the cost of harm on the party causing it, which gives the factory a reason to reduce the harm.","_v":"07cf406199"},{"id":"E16-C2-PR06","prompt":"A town's courts start ruling quickly and the same way for every business, not just for the mayor's friends. How are newcomers likely to respond?","options":["Only existing firms benefit, because newcomers had no contracts yet.","Investment may fall, since fair courts make winning a case less certain for everyone.","Newcomers are more willing to invest and sign long contracts, since outcomes depend less on who they know.","Nothing changes for newcomers, since courts matter only after a dispute."],"answer":2,"why":"Equal, predictable enforcement makes promises reliable for everyone, which lowers the risk of entering and investing.","_v":"e88ff6aadf"},{"id":"E16-C2-PR07","prompt":"A fishing village records which family farms each oyster bed and lets families sell or rent their beds. What is the most likely change?","options":["Families may harvest faster, since recorded beds can be sold.","Families have more reason to care for their beds, since they keep the gains.","Oysters stop being rival once beds are recorded.","The beds become public goods because the village keeps the records."],"answer":1,"why":"Clear use and transfer rights let families capture the payoff from looking after a bed, so they invest in it.","_v":"cec4e776dd"},{"id":"E16-C2-PR08","prompt":"A country lets people use their land titles as collateral for loans for the first time. What is the most likely change?","options":["Land stops being worth anything because a lender might claim it.","Borrowing may rise, but mainly among people who don't own land.","Nothing changes, since the land itself is the same.","Owners can borrow against their land to start or grow businesses."],"answer":3,"why":"Assets that could not back a loan become usable. This is the opposite of de Soto's dead capital.","_v":"1942907f3c"},{"id":"E16-C2-PR09","prompt":"A city stops enforcing parking-space leases, so anyone can take a rented spot. What is the most likely change?","options":["Fewer people pay to rent spaces, since paying no longer guarantees a spot.","Rents for spaces rise because spaces are now scarcer.","More people may rent spaces to be safe, since spots are harder to find.","More spaces get built because demand has grown."],"answer":0,"why":"A lease is only worth paying for if the right to exclude others is enforced. Without that, the value of renting collapses.","_v":"6c0a63030b"},{"id":"E16-C2-PR10","prompt":"A charter city adopts trusted rules for property, courts, and contracts. Suppose people believe the rules will last. What is the most plausible early change?","options":["Investment can't change until the city's natural resources improve.","People may invest less there, since strict contract rules tend to scare off buyers.","People and firms are more willing to invest and move there, since their claims are safer.","The city's land becomes non-rival."],"answer":2,"why":"Romer's idea is that the value lives in the rules. Safer claims draw investment and people.","_v":"7d749bd58e"},{"id":"E16-C2-PR11","prompt":"A website for used bikes starts requiring proof of ownership, such as a registered serial number, before a bike can be listed. What is likely to change?","options":["Bike theft stops entirely.","Honest sellers may be hurt most, since buyers now distrust every listing.","Buyers trust listings more, so stolen bikes are harder to sell there.","Sellers lose their right to transfer their bikes."],"answer":2,"why":"Proof of ownership makes transfer claims credible. That helps honest sellers and makes the site less useful for selling stolen bikes.","_v":"1a011ba700"},{"id":"E16-C2-PR12","prompt":"A government announces it may take any farm \"when needed,\" with no set rules and no payment. How are farmers likely to respond?","options":["They invest more, to make their farms too valuable to take.","They invest less in long-term improvements like wells and orchards, since they may not keep the gains.","They invest about the same, since they still hold title today.","Crop prices must fall right away."],"answer":1,"why":"When rules can change at someone's whim, improving land is a gamble. People invest less in what they may lose.","_v":"b7498b26d0"}]},{"id":"c2-repair","type":"choice","tier":2,"title":"Repair the reasoning","targets":["16.2c"],"status":"draft","note":"Carried over from #112's error items; the audit recommends rebuilding these as Spot the Blunder sorts.","items":[{"id":"E16-C2-ER01","prompt":"A student says: 'If you own the land, you automatically own the right to flood your neighbor's basement.'","options":["Separate ordinary use from liability for external harms.","Agree because ownership always permits any activity.","Assume all uses of land require unanimous neighbors' consent."],"answer":0,"why":"Property rights do not cancel neighboring claims.","_v":"a8c76d0f81"},{"id":"E16-C2-ER02","prompt":"A developer calls a recorded easement a mere preference.","options":["Recognize the easement as a potentially enforceable right.","Ignore all easements as objections.","Assume the developer can transfer rights belonging to others."],"answer":0,"why":"A documented entitlement differs from dislike.","_v":"2ce38cabaa"},{"id":"E16-C2-ER03","prompt":"A student says: \"Property rights are natural. Governments just write down what was already true.\" What's wrong with this reasoning?","options":["Nothing. Rights exist before any rule.","Property rights apply only to land, so the claim is too broad.","Rights are defined by social rules; someone has to draw the lines, like where airspace ends.","Only governments can own property, so individuals have no rights to write down."],"answer":2,"why":"Friedman's airplane shows the point: nothing in nature marks the line. People define rights and enforce them.","targets":["16.2b"],"_v":"85e3d33340"},{"id":"E16-C2-ER04","prompt":"A student says: \"A free market means no rules. The fewer rules, the freer the market.\" What's wrong with this reasoning?","options":["Markets rely on rules about ownership, contracts, and enforcement; removing those can shrink trade.","Nothing. Every rule reduces trade.","Markets need a rule setting every price.","Rules matter only in very large markets."],"answer":0,"why":"The chapter's thesis: markets are built on rules. Some rules block people, but others are what make trade possible.","_v":"8138c7da8e"},{"id":"E16-C2-ER05","prompt":"A student says: \"I have a signed contract, so I'm protected, even though courts here never enforce contracts.\" What's wrong with this reasoning?","options":["Nothing. A signature makes the deal binding.","Contracts only protect large firms.","A contract has to include a price to count.","A contract no one will enforce gives little protection; the signature alone doesn't make the other side perform."],"answer":3,"why":"A right you can't enforce is only a wish with your name on it. The protection comes from enforcement.","_v":"d0ee3a6362"},{"id":"E16-C2-ER06","prompt":"A student says: \"The registry shows I own my land, so it's great collateral, even though courts here never let banks take land from people who don't repay.\" What's wrong with this reasoning?","options":["Land can never serve as collateral.","Collateral only works if the lender can actually claim it; weak enforcement makes the title much less useful to a bank.","Nothing. A clear title is all a bank needs.","The registry must be wrong if courts don't act."],"answer":1,"why":"Title names the owner. Enforcement is what lets a lender count on the land if the loan goes unpaid.","_v":"db2bacba9c"},{"id":"E16-C2-ER07","prompt":"A student says: \"Every fix for weak property rights means more government.\" What's wrong with this reasoning?","options":["Nothing. Only governments can define and protect rights.","Weak property rights can't be fixed at all.","Sometimes the fix is a private rule, like a trade club's arbitration, or removing a rule that blocks people.","Weak rights are always a market failure, so markets fix them."],"answer":2,"why":"Rules can come from governments, private associations, or reputation, and some fixes remove a rule rather than add one.","_v":"f5ccaf118b"},{"id":"E16-C2-ER08","prompt":"A student says: \"When a factory's smoke harms nearby farms, that's just bad luck for the farmers. The market will sort it out.\" What's wrong with this reasoning?","options":["The farmers should simply buy the factory.","Smoke is a public good, so no one is responsible.","Nothing. Prices already include harm to others.","Without liability rules, the cost falls on bystanders and nothing in the market corrects it."],"answer":3,"why":"This is the liability row of the quiet-assumptions table: when it breaks, costs spill onto bystanders with no market correction.","_v":"21d9b8b726"},{"id":"E16-C2-ER09","prompt":"A student says: \"Our city's rules are fine. They just change every few months depending on who's in office.\" What's wrong with this reasoning?","options":["Rules that change unpredictably make investing a bet on politics; rule of law needs rules known in advance.","Nothing. Frequent changes keep rules up to date.","The city simply has too few rules.","Only courts should be allowed to write rules."],"answer":0,"why":"Rule of law means rules are public, stable, and predictably enforced. Constant change undercuts that.","_v":"3d3df1da12"},{"id":"E16-C2-ER10","prompt":"A student says: \"People in Lima's informal economy stayed small because they didn't have good business ideas.\" What's wrong with this reasoning?","options":["Nothing. Ideas decide which businesses grow.","Without title and enforceable contracts, their assets couldn't back loans, so even good businesses hit a ceiling.","Informal businesses had no customers.","Informal property is non-rival, so it can't be sold."],"answer":1,"why":"The chapter says people had skills and customers. What they lacked was the legal title and contracts that let businesses borrow and grow.","_v":"2130b8d17c"},{"id":"E16-C2-ER11","prompt":"A student says: \"I rent this apartment and live in it, so I can sell it to someone else.\" What's wrong with this reasoning?","options":["Nothing. Living somewhere gives you every right to it.","Renters have no rights at all.","Renting gives a right to use the apartment, not a right to sell it; parts of the bundle can belong to different people.","Apartments can't be sold by anyone."],"answer":2,"why":"The bundle can be split. The landlord keeps the right to transfer; the renter holds a right to use.","_v":"10a435ce60"},{"id":"E16-C2-ER12","prompt":"A student says: \"Land rights are secure here. The courts protect them for anyone who knows the right officials.\" What's wrong with this reasoning?","options":["Nothing. Secure rights only matter for people with connections.","Courts never protect land rights anywhere.","The only problem is that the courts are too slow.","Rights enforced only for insiders aren't secure for everyone; rule of law means the same rules apply to all."],"answer":3,"why":"When protection depends on who you know, outsiders can't count on their rights, so they invest and trade less.","_v":"19739ee87c"}]},{"id":"c2-ap","type":"choice","tier":3,"title":"AP-style questions","targets":["16.2a","16.2c","16.2d"],"status":"draft","items":[{"id":"E16-EX-001","prompt":"A farmer and a buyer agree on the price of a parcel, but two families claim to own it. The transaction stalls. Which explanation best identifies the obstacle?","options":["The parties' agreement proves legal transfer is possible, so the remaining barrier must be low demand.","Competing ownership claims make a credible transfer difficult despite the agreed price.","The obstacle is chiefly weak competition among buyers, not the title itself.","The deal can proceed securely if the buyer promises to accept any later court ruling."],"answer":1,"why":"The parties have found a price, but a market transaction also requires a credible claim to transfer the parcel. Clarifying title addresses an institutional problem.","_v":"57295cec01"},{"id":"E16-EX-003","prompt":"A land registry is accurate, but courts enforce property claims only for politically connected owners. Which investment risk remains?","options":["The court may decline to protect the registered owner's claim if the owner lacks political connections.","The registry cannot identify the owner because contracts are enforceable only selectively.","A clear registry by itself eliminates uncertainty for all lenders.","The remaining uncertainty is solely the cost of filing land records, not enforcement."],"answer":0,"why":"Clear records help identify title, while unequal enforcement can still undermine credible rights.","_v":"897f472097"},{"id":"E16-EX-007","prompt":"Two countries have similar resources and entrepreneurial talent. In one, newcomers can register land and enforce contracts cheaply; in the other, officials favor insiders. Which inference is warranted?","options":["The contrast suggests a mechanism by which institutions could affect entry and investment, but cannot alone isolate their causal effect.","Similar resources and talent are sufficient controls to establish that institutional differences caused all later growth.","The countries must invest equally because productive opportunities are initially similar.","Political favoritism matters only for income distribution, not entry or expected returns."],"answer":0,"why":"Economic mechanisms support a plausible prediction, but cross-country comparisons do not independently establish causation.","_v":"dcf9818395"},{"id":"E16-EX-008","prompt":"A town calls a public swimming pool a 'public good' because taxpayers built it. Why is this reasoning incomplete?","options":["Any taxpayer-funded good is public if everyone is entitled to apply for access.","Rivalry and feasible exclusion determine the classification, not the source of funding.","A swimming pool is necessarily nonexcludable if municipal employees operate it.","Government provision makes a facility non-rival until an admission fee is imposed."],"answer":1,"why":"Admissions can restrict access; limited space and congestion make use rival at least at capacity. Ownership and funding alone do not classify the good.","_v":"e2b6e9d17a"},{"id":"E16-EX-013","prompt":"A market platform verifies sellers' identities but cannot ensure they deliver goods after payment. Which additional institution would most directly improve exchange?","options":["A reputation system eliminates the need for any enforcement if enough sellers receive favorable ratings.","Credible contract enforcement adds consequences when a verified seller fails to perform.","Allowing buyers to pay later removes the problem without introducing another risk.","Publishing ownership claims guarantees that every verified seller will deliver."],"answer":1,"why":"Verification helps identify counterparties; enforcement makes promises credible. Both support exchange.","_v":"c74a60801f"},{"id":"E16-EX-015","prompt":"A digital marketplace permits anyone to list products, but sellers cannot establish legal ownership. Which conclusion best follows?","options":["Open listing access cannot establish the seller's authority to transfer the claimed asset.","Open entry guarantees that buyers can enforce ownership rights against third parties.","The main obstacle is insufficient demand rather than disputed entitlements.","An advertised price determines ownership once a buyer accepts it."],"answer":0,"why":"An open platform is not enough when sellers lack credible rights to transfer what they offer.","_v":"67cb6dddb2"},{"id":"E16-EX-017","prompt":"A farmer owns a field. A neighboring cooperative legally controls the only canal access to irrigate it, and no easement has been granted. What does this show about the farmer's rights?","options":["Owning a field includes access to any neighboring infrastructure needed to farm it.","A landowner's rights are specific and may coexist with another person's enforceable easement.","The canal cannot be privately owned if two farms have historically used it.","A field title is invalid unless every adjacent parcel grants unrestricted access."],"answer":1,"why":"A valid land title does not erase distinct access rights that can belong to others.","_v":"46ff1d9d03"},{"id":"E16-EX-018","prompt":"A land-title system accurately records who may occupy and use a parcel, but local rules prohibit its sale. Which ownership distinction matters most?","options":["Recognized use rights do not necessarily include the right to transfer the land.","Without transfer, use of the land must also be prohibited.","An accurate title registry proves that transfers will be enforceable despite the restriction.","The restriction changes whether the land is excludable, rather than which ownership powers apply."],"answer":0,"why":"Knowing who owns a parcel does not necessarily mean that transfer is permitted.","_v":"939941833e"},{"id":"E16-EX-019","prompt":"A factory's emissions damage a neighbor's crops. Both parties own their land. Which conclusion is most defensible?","options":["The factory's title automatically authorizes any use that increases its profits.","The neighbor may claim damages only if the factory never held title.","The rights and remedies must account for the factory's use and the neighbor's harm; ownership is not unlimited.","The relevant entitlements can be determined from total production alone without legal rules."],"answer":2,"why":"Clear rights are essential precisely because ownership does not entail unrestricted harm to others.","_v":"083cebb972"},{"id":"E16-EX-020","prompt":"A buyer obtains a clear title but lenders still refuse collateral because courts rarely execute judgments. What is the remaining problem?","options":["Poor enforcement can make recorded collateral rights hard to realize after default.","Accurate title automatically makes foreclosure reliable even if courts will not act.","The main unresolved problem is simply whether buyers can find the property on a map.","Lenders' reluctance proves that the asset has no economic value."],"answer":0,"why":"Title clarifies the claim; enforceability helps make the claim credible to lenders.","_v":"3eabc32bb2"},{"id":"E16-EX-023","prompt":"A study finds that regions with stronger courts have higher investment. Which additional result would strengthen a causal interpretation?","options":["The correlation also appears when regions are ranked by income, without additional controls.","The regions' investment is measured in the same year as court quality, ensuring a correct direction of causation.","The highest-investment regions report positive perceptions of their courts.","A plausibly independent enforcement reform allows comparison of investment changes with a credible comparison group."],"answer":3,"why":"A design that addresses confounding and timing offers more causal leverage than a raw cross-sectional association.","_v":"dc66743044"},{"id":"E16-EX-026","prompt":"A previously open pond is fenced and access rules are now enforced, but the fish stock and method of harvesting are unchanged. Which statement best describes the effects?","options":["Restricting entry changes the fact that one harvested fish leaves fewer fish for others.","Fencing makes access excludable, while harvesting fish remains rival.","Fencing makes the entire pond non-rival if permit numbers are held constant.","The pond cannot experience overuse once a private owner can exclude visitors, even without management."],"answer":1,"why":"Fencing changes access, not the depletion from catching individual fish.","_v":"ca1b358c04"},{"id":"E16-EX-201","prompt":"A country has clear land titles and fair courts, but no rule says who pays when one person's activity damages another's property. A tannery's waste ruins a neighbor's well. Which outcome is most likely?","options":["The tannery pays, because clear titles automatically assign responsibility for harm.","The neighbor bears the cost, and the tannery has little reason to reduce its waste.","The price of leather rises to cover the neighbor's loss.","The neighbor's title becomes invalid because the well was damaged."],"answer":1,"why":"Clear titles say who owns what, but liability rules decide who pays for harm. Without them, the cost stays with the neighbor and the tannery's choices don't change.","_v":"944faee859"},{"id":"E16-EX-202","prompt":"Many legal systems once held that a landowner owned the sky above their land. Courts later allowed airplanes to fly high overhead without permission. What does this change best show?","options":["The courts discovered the true natural boundary of land ownership.","Landowners never had any rights above their land.","Property rights are defined by social rules, and those rules can be redrawn as circumstances change.","Airspace is a public good, so it can't be owned."],"answer":2,"why":"Nothing in nature marked the line, so courts drew it. Rights are set, and reset, by people.","targets":["16.2b"],"_v":"3b05b10dae"},{"id":"E16-EX-203","prompt":"City A and City B are alike, except that most homes in City A lack legal title, while nearly all homes in City B have registered title. Which difference would the chapter predict?","options":["Homes in City A sell for more, because titles add paperwork costs in City B.","Homeowners in City A invest more in their homes, since no one can take a title they don't have.","Both cities have the same access to credit, since the homes are physically alike.","Homeowners in City B can more easily borrow against their homes to fund businesses."],"answer":3,"why":"Registered title lets a home serve as collateral. In City A, much of that wealth is dead capital.","_v":"91086bde75"},{"id":"E16-EX-204","prompt":"A government enforces contracts reliably but often changes tax and permit rules without notice. A firm is deciding whether to build a factory that pays off over 20 years. What is the main institutional risk?","options":["Unpredictable rule changes could wipe out the factory's returns, so investing becomes a bet on politics.","The firm's contracts with suppliers can't be enforced.","Reliable contract enforcement removes all risk, so there is none.","The factory's output is non-rival, so it can't earn revenue."],"answer":0,"why":"Contracts hold here, but rule of law also needs rules that are stable and known in advance. A long project is exposed to every surprise change.","_v":"3a5bde3da0"}]}]},{"id":"c3","number":3,"name":"Corruption","activities":[{"id":"c3-sort","type":"sort","tier":1,"title":"Sort the cases","targets":["16.3a"],"status":"draft","bins":["Inclusive","Extractive","Insufficient evidence"],"round_size":6,"cards":[{"id":"E16-C3-F01","text":"Courts apply contract rules equally to new and established firms","bin":0,"why":"Impartial enforcement supports broadly accessible participation.","_v":"bbcef118fd"},{"id":"E16-C3-F02","text":"Contracts are reserved for companies whose owners donate to officials","bin":1,"why":"Political connections determine who receives valuable privileges.","_v":"e0335fd5a5"},{"id":"E16-C3-F03","text":"A country's GDP rises, but no information about institutional rules is available","bin":2,"why":"GDP alone cannot establish whether access and enforcement are broadly inclusive.","_v":"3b8bec2e34"},{"id":"E16-C3-F04","text":"Permit rules are published and decisions can be appealed independently","bin":0,"why":"Transparent rules and appeals constrain discriminatory decisions.","_v":"0989d3bf63"},{"id":"E16-C3-F05","text":"Inspectors privately demand bribes before issuing routine approvals","bin":1,"why":"Unofficial payments distort access and create opportunities for extraction.","_v":"2720f231f8"},{"id":"E16-C3-F06","text":"A port is announced, but rules governing access have not been specified","bin":2,"why":"Without access rules, there is insufficient evidence to classify the institution.","_v":"aca7cca4b6"},{"id":"E16-C3-F07","text":"New firms compete under the same entry requirements as incumbents","bin":0,"why":"Broad entry opportunities are a feature of inclusive institutions.","_v":"88b4c8dab4"},{"id":"E16-C3-F08","text":"Only officials' relatives are eligible to bid on public contracts","bin":1,"why":"Eligibility is restricted to politically favored insiders.","_v":"ac5b7ea219"},{"id":"E16-C3-F09","text":"A new trade agreement is announced without any implementation details","bin":2,"why":"An announcement alone doesn't establish fair access or enforcement.","_v":"61d48f9f58"},{"id":"E16-C3-F10","text":"Regulators waive compliance rules only for their close friends","bin":1,"why":"Selective exemptions give insiders advantages under unequal rules.","_v":"f323d7f1fc"},{"id":"E16-C3-F11","text":"Anyone can register a business online in one day for the same posted fee","bin":0,"why":"Open entry on equal terms lets anyone take part.","_v":"82d5cca8d1"},{"id":"E16-C3-F12","text":"Land titles are kept in a public registry that anyone can search","bin":0,"why":"Public, searchable records spread secure ownership broadly.","_v":"79b7f7cf66"},{"id":"E16-C3-F13","text":"Public contracts go to the lowest qualified bid, and losing bidders can appeal","bin":0,"why":"Open bidding with appeals keeps contracts from being reserved for insiders.","_v":"c1758e503e"},{"id":"E16-C3-F14","text":"Judges are assigned to cases at random, so no one can pick a friendly judge","bin":0,"why":"Random assignment supports impartial enforcement.","_v":"1c39b528ef"},{"id":"E16-C3-F15","text":"Small farmers can use their registered land as collateral at any bank","bin":0,"why":"Secure, usable property rights reach ordinary people, not just the connected.","_v":"b5bc118359"},{"id":"E16-C3-F16","text":"Only firms owned by ruling-party members may import fuel","bin":1,"why":"Entry is reserved for political insiders.","_v":"dc091a51c4"},{"id":"E16-C3-F17","text":"Courts rule for whichever side has ties to the governor","bin":1,"why":"A captured court enforces the law for insiders, not equally.","_v":"ab0d8f2972"},{"id":"E16-C3-F18","text":"Fishing licenses are handed out privately to the mayor's business partners","bin":1,"why":"Access goes to the connected through a private process.","_v":"6ba80fa7c9"},{"id":"E16-C3-F19","text":"A minister's company is exempt from taxes its competitors must pay","bin":1,"why":"Unequal rules give an insider an advantage that has nothing to do with value.","_v":"67257aa86c"},{"id":"E16-C3-F20","text":"A country's stock market rose 20 percent last year","bin":2,"why":"Rising stock prices say nothing about who the rules serve.","_v":"01e3ce0c1f"},{"id":"E16-C3-F21","text":"A new president promises to fight corruption","bin":2,"why":"A promise isn't evidence about how rules are actually applied.","_v":"c02b360e39"},{"id":"E16-C3-F22","text":"Prices in a city's markets look normal, and markets clear every day","bin":2,"why":"Markets on extractive rules still clear and look normal, so prices alone can't tell you who the rules serve.","_v":"a13f043eb2"},{"id":"E16-C3-F23","text":"A country exports more oil than ever before","bin":2,"why":"Export volume doesn't show whether property rights, enforcement, and entry are broadly shared.","_v":"e5dafa4d5c"},{"id":"E16-C3-F24","text":"A government passes an anti-bribery law, but nothing is known yet about how it is enforced","bin":2,"why":"A rule is only as strong as its enforcement, and we don't know that yet.","_v":"42b90a18c2"}]},{"id":"c3-quick","type":"quick","tier":1,"title":"Quick classify","targets":["16.3a"],"status":"draft","labels":["Inclusive","Extractive","Insufficient evidence"],"round_size":8,"items":[{"id":"E16-C3-QK01","prompt":"Courts apply contract rules equally to new and established firms","answer":0,"why":"Impartial enforcement supports broadly accessible participation.","_v":"6f34942e06"},{"id":"E16-C3-QK02","prompt":"Contracts are reserved for companies whose owners donate to officials","answer":1,"why":"Political connections determine who receives valuable privileges.","_v":"27ec1b8872"},{"id":"E16-C3-QK03","prompt":"A country's GDP rises, but no information about institutional rules is available","answer":2,"why":"GDP alone cannot establish whether access and enforcement are broadly inclusive.","_v":"202f051642"},{"id":"E16-C3-QK04","prompt":"Permit rules are published and decisions can be appealed independently","answer":0,"why":"Transparent rules and appeals constrain discriminatory decisions.","_v":"4c0fe59f43"},{"id":"E16-C3-QK05","prompt":"Inspectors privately demand bribes before issuing routine approvals","answer":1,"why":"Unofficial payments distort access and create opportunities for extraction.","_v":"6b2e8c060a"},{"id":"E16-C3-QK06","prompt":"A port is announced, but rules governing access have not been specified","answer":2,"why":"Without access rules, there is insufficient evidence to classify the institution.","_v":"e5373bc25c"},{"id":"E16-C3-QK07","prompt":"New firms compete under the same entry requirements as incumbents","answer":0,"why":"Broad entry opportunities are a feature of inclusive institutions.","_v":"10ca4ab887"},{"id":"E16-C3-QK08","prompt":"Only officials' relatives are eligible to bid on public contracts","answer":1,"why":"Eligibility is restricted to politically favored insiders.","_v":"cc09d22f85"},{"id":"E16-C3-QK09","prompt":"A new trade agreement is announced without any implementation details","answer":2,"why":"An announcement alone doesn't establish fair access or enforcement.","_v":"aa93069e84"},{"id":"E16-C3-QK10","prompt":"Regulators waive compliance rules only for their close friends","answer":1,"why":"Selective exemptions give insiders advantages under unequal rules.","_v":"8e8c7d6e10"},{"id":"E16-C3-QK11","prompt":"Anyone who meets the posted safety standards gets a food-truck permit","answer":0,"why":"Entry depends on published standards, not connections.","_v":"48da2a1b07"},{"id":"E16-C3-QK12","prompt":"Courts apply the same published rules to everyone, and rulings that favor insiders are overturned on appeal","answer":0,"why":"Impartial enforcement that insiders can't bend is a mark of inclusive institutions.","_v":"3991778a08"},{"id":"E16-C3-QK13","prompt":"A newcomer can sue a large, well-connected firm and expect a fair hearing","answer":0,"why":"Impartial enforcement protects outsiders as well as insiders.","_v":"7547d92cd9"},{"id":"E16-C3-QK14","prompt":"Government contracts are awarded through open bidding with published scores","answer":0,"why":"Competitive public contracting lets any qualified firm compete.","_v":"3a16b9b84e"},{"id":"E16-C3-QK15","prompt":"Patents are granted under the same rules to students and large companies","answer":0,"why":"Equal rules spread property rights broadly.","_v":"110c8c8196"},{"id":"E16-C3-QK16","prompt":"Every taxi driver who passes the same test can get a license","answer":0,"why":"Open entry on equal terms is a mark of inclusive institutions.","_v":"ce7365ad96"},{"id":"E16-C3-QK17","prompt":"Independent auditors review the budget, and officials who misuse funds are prosecuted","answer":0,"why":"Detection plus real penalties makes corruption costly.","_v":"61d8645a23"},{"id":"E16-C3-QK18","prompt":"Farmers in every region can register their land for the same small fee","answer":0,"why":"Secure ownership is available to everyone, not just the connected.","_v":"6b76600d66"},{"id":"E16-C3-QK19","prompt":"Import licenses are sold only to the president's relatives","answer":1,"why":"Entry is reserved for insiders.","_v":"4f2e4a29e8"},{"id":"E16-C3-QK20","prompt":"Police ignore safety violations at factories owned by the governor's friends","answer":1,"why":"Rules are enforced unequally to protect insiders.","_v":"418f1d262d"},{"id":"E16-C3-QK21","prompt":"A new bank can open only if it gives shares to a senior official","answer":1,"why":"Officials use their control over entry for private gain.","_v":"e8b05a0fa0"},{"id":"E16-C3-QK22","prompt":"An airline with political allies wins a law that bans any new airline from entering","answer":1,"why":"A protected monopoly keeps competitors out for an insider's benefit.","_v":"0cb85c0e9a"},{"id":"E16-C3-QK23","prompt":"Judges are promoted for ruling in favor of the ruling party's donors","answer":1,"why":"Captured courts serve those who control them.","_v":"79a6620aa6"},{"id":"E16-C3-QK24","prompt":"Inspectors invent delays and then charge fees to remove them","answer":1,"why":"Officials create obstacles so they can sell their removal.","_v":"8c449bc70e"},{"id":"E16-C3-QK25","prompt":"Mining rights go to firms that hire the minister's son","answer":1,"why":"Access depends on connections rather than value.","_v":"5403c01e67"},{"id":"E16-C3-QK26","prompt":"A country's average income rose last year","answer":2,"why":"Income growth alone doesn't show who the rules serve.","_v":"1885baf255"},{"id":"E16-C3-QK27","prompt":"Store shelves are full, and prices adjust each day as supply and demand shift","answer":2,"why":"Markets clear on extractive rules too, so this doesn't settle the question.","_v":"064248738b"},{"id":"E16-C3-QK28","prompt":"A new anti-corruption office is announced, with no details yet on its powers","answer":2,"why":"An announcement without powers or enforcement isn't evidence either way.","_v":"14b34ced0c"},{"id":"E16-C3-QK29","prompt":"The capital city builds a new airport","answer":2,"why":"A new project says nothing about who may use it or how rules are applied.","_v":"3f5d0e9338"},{"id":"E16-C3-QK30","prompt":"A country's largest company earns record profits","answer":2,"why":"Profits could come from serving customers or from protected privileges. We can't tell which.","_v":"244216c374"},{"id":"E16-C3-QK31","prompt":"Foreign tourists visit in record numbers","answer":2,"why":"Tourism numbers don't describe property rights, enforcement, or entry.","_v":"35ca415487"},{"id":"E16-C3-QK32","prompt":"A politician gives a speech praising free markets","answer":2,"why":"Words about markets aren't evidence about how the rules work.","_v":"a943f00c9a"}]},{"id":"c3-match","type":"match","tier":1,"title":"Memory Match","targets":["16.3a","16.3c","16.3d"],"status":"draft","board_size":6,"pairs":[{"id":"E16-C3-MM01","left":"Inclusive institutions","right":"Rules and enforcement that enable broad participation and opportunity.","_v":"f3d22e7ec5"},{"id":"E16-C3-MM02","left":"Extractive institutions","right":"Rules concentrating power or advantages among insiders.","_v":"c303b9946e"},{"id":"E16-C3-MM03","left":"Rent seeking","right":"Spending resources to secure privileges or transfers through institutional influence.","_v":"d46dd0715f"},{"id":"E16-C3-MM04","left":"Corruption","right":"Abuse of entrusted authority for private advantage.","_v":"951151b5b8"},{"id":"E16-C3-MM05","left":"Search costs","right":"Resources spent finding potential partners or information.","_v":"651c1afd92"},{"id":"E16-C3-MM06","left":"Negotiation costs","right":"Resources spent bargaining and reaching agreements.","_v":"37a3322e9a"},{"id":"E16-C3-MM07","left":"Bribe","right":"A private payment to an official to get a decision bent or sped up.","_v":"20ed23910f"},{"id":"E16-C3-MM08","left":"Verification costs","right":"Resources spent checking that a title, seller, or product is what it claims to be.","_v":"adee48d53e"},{"id":"E16-C3-MM09","left":"Enforcement costs","right":"Resources spent making sure the other side keeps its promise.","_v":"4698904dcc"},{"id":"E16-C3-MM10","left":"“Grease the wheels”","right":"The older view that bribes help firms get past slow officials.","_v":"1c080c8ebc"},{"id":"E16-C3-MM11","left":"“Sands the wheels”","right":"The modern view that corruption slows an economy and raises deal costs.","_v":"f513daadb4"},{"id":"E16-C3-MM12","left":"Correlation","right":"Two things tend to move together, without proof that one causes the other.","_v":"ae13f005c3"},{"id":"E16-C3-MM13","left":"Invented obstacle","right":"A delay an official creates in order to charge for removing it.","_v":"6547a6d9b4"},{"id":"E16-C3-MM14","left":"Competitive public contracting","right":"Government work awarded through open bidding that any qualified firm can enter.","_v":"4d77c82d37"},{"id":"E16-C3-MM15","left":"Captured court","right":"A court that rules for insiders instead of applying the law equally.","_v":"e9963e15c1"},{"id":"E16-C3-MM16","left":"Profit seeking","right":"Earning income by creating something customers are willing to pay for.","_v":"d51c809edb"}]},{"id":"c3-detective","type":"detective","tier":1,"title":"Definition Detective","targets":["16.3c"],"status":"draft","rounds":[{"id":"E16-C3-DD01","term":"Corruption","answers":[{"text":"Corruption is the abuse of entrusted authority for private gain.","grade":"A","why":"The key elements are misuse of entrusted power and private benefit."},{"text":"Corruption involves officials obtaining private benefits.","grade":"A-","why":"This misses the essential element of abusing entrusted authority; lawful pay is not corruption."},{"text":"Corruption occurs whenever a government decision benefits any business.","grade":"F","why":"A lawful policy can benefit businesses without corrupt conduct."}],"_v":"2e95177da9"},{"id":"E16-C3-DD02","term":"Rent seeking","answers":[{"text":"Rent seeking involves spending resources to obtain privileges or transfers through political or institutional influence rather than creating new value.","grade":"A","why":"The distinction is between securing favors and creating productive value."},{"text":"Rent seeking means lobbying for special advantages.","grade":"A-","why":"Lobbying can be an example, but rent seeking includes other costly efforts to secure privileges or transfers."},{"text":"Rent seeking means earning profit by producing goods customers value.","grade":"F","why":"Productive exchange is different from seeking special privileges."}],"_v":"0c1ecb3981"},{"id":"E16-C3-DD03","term":"Inclusive institutions","answers":[{"text":"Inclusive institutions spread property rights, impartial enforcement, and open entry across a whole society.","grade":"A","why":"It names all three pieces and says they reach everyone."},{"text":"Inclusive institutions let anyone start a business.","grade":"A-","why":"Open entry is part of it, but secure property rights and impartial enforcement for everyone matter too."},{"text":"Inclusive institutions are rules that include the government in every market decision.","grade":"F","why":"Inclusive describes who the rules serve, not how much the government does."}],"_v":"27d6ff4ec0"},{"id":"E16-C3-DD04","term":"Extractive institutions","answers":[{"text":"Extractive institutions concentrate property rights, enforcement, and entry in the hands of insiders.","grade":"A","why":"It names what is concentrated and who benefits."},{"text":"Extractive institutions are rules that let officials take bribes.","grade":"A-","why":"Bribery can be part of it, but the core idea is rules that reserve advantages for insiders, such as protected monopolies and captured courts."},{"text":"Extractive institutions are the rules for mining and drilling natural resources.","grade":"F","why":"Extractive here means pulling value toward insiders, not taking minerals out of the ground."}],"_v":"52fcec1ca7"},{"id":"E16-C3-DD05","term":"Transaction costs","answers":[{"text":"Transaction costs are everything you pay to make a deal happen beyond the price itself, such as searching, bargaining, checking, and enforcing.","grade":"A","why":"It sets the price aside and names the main kinds of cost."},{"text":"Transaction costs are the time spent searching for a seller.","grade":"A-","why":"Searching is one transaction cost, but bargaining, checking, and enforcing count too."},{"text":"Transaction costs are the price you pay for a good.","grade":"F","why":"The price is left out by definition. Transaction costs are what you pay beyond it."}],"_v":"f87f3fef31"},{"id":"E16-C3-DD06","term":"“Sands the wheels”","answers":[{"text":"The view that corruption slows an economy because it makes rules unpredictable, raises transaction costs, and rewards connections over value.","grade":"A","why":"It states the claim and the reasons the chapter gives for it."},{"text":"The view that corruption makes doing business more expensive.","grade":"A-","why":"That's true, but it leaves out unpredictable rules and the reward for connections over value."},{"text":"The view that small bribes help firms get past slow officials.","grade":"F","why":"That is the older “grease the wheels” view, which most development economists now reject."}],"_v":"cbf6a5c66b"},{"id":"E16-C3-DD07","term":"Correlation","answers":[{"text":"A pattern in which two things tend to move together, which by itself does not show that one causes the other.","grade":"A","why":"It describes the pattern and the caution that comes with it."},{"text":"A pattern in which two things move together.","grade":"A-","why":"Right as far as it goes, but it misses that a correlation alone doesn't prove cause."},{"text":"Proof that one thing causes another.","grade":"F","why":"Fig 16.1 shows an association. Causation could run both ways or come from deeper causes."}],"_v":"050d0b454c"},{"id":"E16-C3-DD08","term":"Transparency (as a tool against corruption)","answers":[{"text":"Opening up records, budgets, and decisions so corruption is easier to detect. It reduces corruption only when someone can act on what is found.","grade":"A","why":"It names the tool and the condition that makes it work."},{"text":"Publishing government records so people can see them.","grade":"A-","why":"That's the tool, but it only bites when someone can act on the information and courts impose a real cost."},{"text":"A law that makes corruption impossible.","grade":"F","why":"Transparency makes corruption harder to hide. It doesn't end it, and it needs enforcement behind it."}],"_v":"23130624da"}]},{"id":"c3-odd","type":"choice","tier":1,"title":"Odd one out","targets":["16.3a","16.3c","16.3d","16.3e"],"status":"draft","note":"Ported from the Chapter 16 pilot (odd-one-out was a pilot interaction there).","items":[{"id":"E16-C3-OO01","prompt":"Three of these involve misuse of entrusted authority for private gain. Which is the odd one out?","options":["Bribe for a permit","A teacher receiving lawful wages","Contract steered to family for favors","Cash demanded to overlook violations"],"answer":1,"why":"Bribery, favoritism in contracts, and extortion abuse entrusted authority. Receiving lawful wages does not.","_v":"b67afe2448"},{"id":"E16-C3-OO02","prompt":"Three of these favor insiders over fair competition. Which is the odd one out?","options":["Hidden licenses for donors","Contracts for relatives","Open bidding with independent appeals","Bribes for preferential access"],"answer":2,"why":"Secret licenses, nepotistic contracts, and bribes favor insiders. Open bidding with independent appeals instead supports fair competition.","_v":"647853f2c6"},{"id":"E16-C3-OO03","prompt":"Three of these are transaction costs. Which is the odd one out?","options":["Hours spent searching listings","A lawyer's fee to check the title","Time spent haggling over terms","The price of the house itself"],"answer":3,"why":"Searching, checking, and bargaining are costs beyond the price. The price itself is not a transaction cost.","_v":"b4563ee6aa"},{"id":"E16-C3-OO04","prompt":"Three of these are features of inclusive institutions. Which is the odd one out?","options":["A monopoly license reserved for a minister's ally","Open entry on the same terms for everyone","Impartial courts","Secure property rights for ordinary people"],"answer":0,"why":"Open entry, impartial courts, and broadly secure rights are inclusive. A reserved monopoly concentrates advantage among insiders.","_v":"312844de29"},{"id":"E16-C3-OO05","prompt":"Three of these are examples of rent-seeking. Which is the odd one out?","options":["Lobbying for a law that bans new competitors","Cutting costs to offer a lower price","Paying an official for an exclusive import license","Donating to win a no-bid contract"],"answer":1,"why":"The first three compete for privileges. Cutting costs competes by creating value for customers.","_v":"5a458b8424"},{"id":"E16-C3-OO06","prompt":"Three of these make corruption harder to hide. Which is the odd one out?","options":["Independent audits","Transparent budgets","Approvals decided privately by one official","A free press"],"answer":2,"why":"Audits, open budgets, and a free press expose corruption. Private, one-person approvals make it easier to hide.","_v":"f725088888"},{"id":"E16-C3-OO07","prompt":"Three of these explain why Fig 16.1 doesn't prove that corruption causes poverty. Which is the odd one out?","options":["Poverty can weaken institutions","Conflict can cause both corruption and poverty","Instability can drive both","Cleaner countries tend to be richer"],"answer":3,"why":"The first three are other explanations for the pattern. The odd one out just restates the pattern.","_v":"c1c107d0cb"},{"id":"E16-C3-OO08","prompt":"Three of these are signs of extractive institutions. Which is the odd one out?","options":["A permit anyone can get by meeting posted standards","Courts that rule for the governor's friends","Business licenses only for party members","Land titles that officials change for a bribe"],"answer":0,"why":"Captured courts, reserved licenses, and titles for sale favor insiders. A permit open to anyone who meets posted standards is inclusive.","_v":"d205a673dd"},{"id":"E16-C3-OO09","prompt":"Three of these lower transaction costs. Which is the odd one out?","options":["A trusted court that enforces contracts","An inspector who invents delays to charge for removing them","A clean land registry","Standard contract templates"],"answer":1,"why":"Courts, clean registries, and standard contracts make deals cheaper. Invented delays add costs to every deal.","_v":"43e9aaf2a8"},{"id":"E16-C3-OO10","prompt":"Three of these are ways corruption “sands the wheels.” Which is the odd one out?","options":["It makes rules unpredictable","It raises transaction costs","It lets every firm compete on equal terms","It rewards connections over value"],"answer":2,"why":"Corruption does the first three. Equal terms for every firm is what corruption takes away.","_v":"6555d17adf"}],"pool_target":10},{"id":"c3-missing","type":"choice","tier":1,"title":"Find the missing piece","targets":["16.3c","16.3e"],"status":"draft","note":"Ported from the Chapter 16 pilot unchanged. Missing Piece is a retirement candidate, so it is not topped up.","items":[{"id":"E16-C3-MP01","prompt":"When public contracts are reserved for donors, firms gain by seeking political ______ rather than creating value.","options":["privilege","rivalry","non-excludability"],"answer":0,"why":"This is a form of rent-seeking.","_v":"b0368c6bff"},{"id":"E16-C3-MP02","prompt":"A cross-country relationship between income and corruption is evidence of ______, not by itself proof of causation.","options":["association","random assignment","universal inevitability"],"answer":0,"why":"Other factors and reverse causality remain possible.","_v":"8e8a145f89"}],"pool_exception":"Find the Missing Piece is a retirement candidate; it keeps its ported items only."},{"id":"c3-applied","type":"choice","tier":2,"title":"Applied cases","targets":["16.3b","16.3d","16.3e"],"status":"draft","items":[{"id":"E16-C3-AP01","prompt":"Bribes appear to speed one permit. Which objection is strongest?","options":["They can encourage slower and arbitrary systems","They end all waiting","They prove permits are useless"],"answer":0,"why":"Individual shortcuts can create institutional costs.","_v":"2fe5b3b6d9"},{"id":"E16-C3-AP02","prompt":"Rich nations tend to show less corruption. What follows?","options":["Proof of a single cause","Association but not proof of causation","Nothing whatsoever"],"answer":1,"why":"Confounding and reverse causation are possible.","_v":"e81bd1c9c7"},{"id":"E16-C3-AP03","prompt":"A donor receives a monopoly license. What happens?","options":["Competition increases","Prices become irrelevant","Entry may be distorted"],"answer":2,"why":"Privilege can protect insiders.","_v":"fa0690780a"},{"id":"E16-C3-AP04","prompt":"Transparent procurement and appeals may improve…","options":["Accountability","Resource abundance","Rivalry"],"answer":0,"why":"Transparency can constrain favoritism.","_v":"ddeb5c11d0"},{"id":"E16-C3-AP05","prompt":"A politician promises to end corruption without enforcement. What matters?","options":["Slogans alone","Credible monitoring and incentives","Only tax rates"],"answer":1,"why":"Effective institutions require incentives and enforcement.","_v":"5c360ca329"},{"id":"E16-C3-AP06","prompt":"Verified seller reviews may lower which cost?","options":["Shipping costs","Verification costs","Scarcity"],"answer":1,"why":"Reliable reviews reduce uncertainty.","_v":"320193c37b"},{"id":"E16-C3-AP07","prompt":"Citywide smog affects thousands. Bargaining is hard because…","options":["Affected parties are numerous","All pollution is non-rival","No one can measure costs"],"answer":0,"why":"Coordination becomes expensive.","_v":"6cb2db168d"},{"id":"E16-C3-AP08","prompt":"A standard contract cuts repeated legal drafting. It lowers…","options":["Rivalry","Physical costs","Negotiation costs"],"answer":2,"why":"Agreed templates reduce time spent bargaining.","_v":"1152e72bcf"},{"id":"E16-C3-AP09","prompt":"Land records let buyers check titles. They reduce…","options":["Verification costs","Weather risk","Population growth"],"answer":0,"why":"Information about ownership is easier to verify.","_v":"fac35dad2d"},{"id":"E16-C3-AP10","prompt":"When can private bargains fail to resolve harms?","options":["Never","When transaction costs overwhelm potential gains","Only under perfect competition"],"answer":1,"why":"Rights, numbers and costs determine feasibility.","_v":"2e3f78b40a"},{"id":"E16-C3-AP11","prompt":"A government publishes independent audits of permit awards. What mechanism could improve market entry?","options":["Audits make land non-rival.","Audits guarantee every applicant a permit.","Audits reduce the ability to conceal favoritism and create incentives for more consistent rules.","Audits eliminate all administrative costs."],"answer":2,"why":"Transparency and independent review can make arbitrary privilege costlier without making policy perfect.","_v":"905c78c632"},{"id":"E16-C3-AP12","prompt":"Officials must be paid at every step of opening a factory. In the chapter's terms, these payments are best described as…","options":["Transaction costs added to the deal","Part of the factory's price","Rent paid to the landowner","A tax that pays for public goods"],"answer":0,"why":"Every bribe and invented delay is a cost beyond the price, collected by the people who captured the rules.","_v":"d3721b291b"}]},{"id":"c3-predict","type":"choice","tier":2,"title":"What changes?","targets":["16.3f"],"status":"draft","items":[{"id":"E16-C3-PR01","prompt":"A licensing agency publishes audit trails for every exception to its rules. What mechanism may change?","options":["Hidden favoritism becomes easier to detect, potentially reducing discretionary rent-seeking.","All permits become legally unnecessary.","The number of firms must double.","Transaction costs immediately become zero."],"answer":0,"why":"More traceability can constrain abuses while leaving enforcement and implementation important.","_v":"8ed0e67a49"},{"id":"E16-C3-PR02","prompt":"A town removes unofficial payments but keeps a legal monopoly for the mayor's allies. What should we predict?","options":["One form of corruption may fall, while exclusionary entry barriers remain.","Competitive entry is automatically restored.","Every firm's costs necessarily rise.","The monopoly becomes a common resource."],"answer":0,"why":"Multiple institutional barriers can reinforce each other. Removing one does not remove the others.","_v":"6fdcb39837"},{"id":"E16-C3-PR03","prompt":"A city stops awarding construction contracts privately to the mayor's friends and switches to open bidding. Which change is most likely?","options":["The mayor's friends keep winning every contract, so nothing changes.","Firms compete more on price and quality, so the city likely gets more for its money.","Firms spend more on lobbying the mayor than before.","Construction costs rise because more firms must be reviewed."],"answer":1,"why":"Open bidding lowers the payoff to connections and raises the payoff to offering a better deal.","_v":"eb8775c3e2"},{"id":"E16-C3-PR04","prompt":"A country publishes every ministry's budget online, but its courts never prosecute officials. What should we predict?","options":["Corruption ends because everything is now public.","Officials stop taking bribes because voters can read the budget.","Some misuse may be exposed, but without enforcement corruption may change little.","Corruption rises because publishing budgets teaches people how to steal."],"answer":2,"why":"Information only bites when someone can act on it and a court can impose a real cost.","_v":"8fb5dd573b"},{"id":"E16-C3-PR05","prompt":"Inspectors who could charge to speed up approvals are replaced by an online system with fixed processing times. Which change is most plausible?","options":["Approvals slow down because no one is paid to hurry.","Approvals are no longer needed at all.","Only large firms can use the new system.","Inspectors lose their reason to invent delays, so approvals become faster and more predictable."],"answer":3,"why":"When no one can sell the removal of a delay, no one gains from creating the delay.","_v":"a0922c2c64"},{"id":"E16-C3-PR06","prompt":"Courts that used to favor insiders become impartial. What happens to the payoff from rent-seeking?","options":["Buying favorable rulings pays off less, so firms shift effort toward serving customers.","It rises, because firms must lobby harder to win cases.","It doesn't change, because courts don't affect business decisions.","Firms stop trying to earn profit at all."],"answer":0,"why":"Impartial courts make influence less valuable, which tilts reward back toward creating value.","_v":"f044523158"},{"id":"E16-C3-PR07","prompt":"An honest land registry replaces one where titles could be changed for a bribe. Which cost falls most directly?","options":["The price buyers pay for the land itself","The cost of checking who really owns a lot","The cost of building on the land","The cost of bargaining over the price with the seller"],"answer":1,"why":"A clean registry makes it cheap to verify ownership. The price itself isn't a transaction cost.","_v":"8d26050f95"},{"id":"E16-C3-PR08","prompt":"A government gives one firm a protected monopoly on cement in exchange for campaign donations. Over time, what is most likely?","options":["New cement firms enter and compete prices down.","Cement prices fall because the firm has no rivals to worry about.","Cement prices stay higher, and new firms with better methods stay out.","Nothing changes, because the cement market still clears."],"answer":2,"why":"A market on extractive rules still clears, but the price carries the rigging: higher prices and blocked entry.","_v":"1e2d9284ab"},{"id":"E16-C3-PR09","prompt":"A new law lets anyone report bribes anonymously, and an independent office must investigate every report. What mechanism changes?","options":["Officials' salaries rise to replace lost bribes.","Bribes become legal once they are reported.","Every reported official is automatically found guilty.","Bribes become more likely to be detected and punished, which raises the cost of trying."],"answer":3,"why":"Making corruption easier to detect and costlier to attempt is the institutional fix the chapter describes.","_v":"c7d136e621"},{"id":"E16-C3-PR10","prompt":"A country's markets look normal: prices clear and shelves are full. A reform then removes import licenses that only insiders could get. What should we predict?","options":["More firms can import, so prices of imported goods may fall even though markets were already clearing.","Nothing changes, because the markets were already clearing.","Prices rise, because the licenses kept the market orderly.","Imports fall, because the insiders stop importing."],"answer":0,"why":"Clearing markets can hide the rigging. Opening entry lets competition push prices down.","_v":"b2f0f12db1"},{"id":"E16-C3-PR11","prompt":"A city replaces three separate offices' stamps and signatures for opening a shop with one online form. Which change is most likely?","options":["More offices are needed to check each online form.","Opening a shop takes less time, and officials have fewer chances to demand payments.","Rent-seeking rises because the form is online.","Only shops that are already open benefit from the change."],"answer":1,"why":"Fewer steps mean lower transaction costs and fewer points where a bribe can be demanded.","_v":"cc10a7d4a5"},{"id":"E16-C3-PR12","prompt":"Insiders who used to win public contracts start losing them to open bidding. Which response is an example of rent-seeking?","options":["They cut costs so they can win more bids.","They improve the quality of their work.","They spend money lobbying to bring back the old rules.","They leave the industry for a more profitable one."],"answer":2,"why":"Lobbying to restore a privilege competes for influence. Cutting costs or improving quality competes to create value.","_v":"cc0255e476"}]},{"id":"c3-repair","type":"choice","tier":2,"title":"Repair the reasoning","targets":["16.3b","16.3e"],"status":"draft","note":"Carried over from #112's error items; the audit recommends rebuilding these as Spot the Blunder sorts.","items":[{"id":"E16-C3-ER01","prompt":"An official says: 'The bribe got the permit done today, so corruption is efficient for everyone.'","options":["Distinguish an individual's immediate gain from broader institutional harms.","Assume all bribes benefit every applicant.","Treat the observed case as proof of nationwide growth."],"answer":0,"why":"System-wide incentives can become worse.","_v":"ffb9aead5f"},{"id":"E16-C3-ER02","prompt":"A study finds corruption and low incomes correlated. A student concludes corruption alone causes all poverty.","options":["Discuss confounding and possible two-way causation.","Declare the conclusion proved.","Reject the data because correlations are meaningless."],"answer":0,"why":"Correlations matter but warrant careful causal interpretation.","_v":"ff61d383b3"},{"id":"E16-C3-ER03","prompt":"A student says: 'Prices in this market clear every day, so its rules must be fair.'","options":["Agree, because clearing prices prove competition is fair.","Say that clearing prices prove the market is rigged.","Say that whether prices clear has nothing to do with markets.","Point out that markets on extractive rules still clear; prices alone don't show who the rules serve."],"answer":3,"why":"The chapter's point: a market on extractive rules still runs and looks neutral.","_v":"f286f29961"},{"id":"E16-C3-ER04","prompt":"A student says: 'Corruption greases the wheels. A bribe helps a business get past slow officials.'","options":["Explain that officials who can charge to remove delays have reason to create them, so bribes tend to slow the system overall.","Agree, because one firm got its permit faster.","Say a bribe can never speed up a single application.","Say slow officials have nothing to do with corruption."],"answer":0,"why":"One payer may gain, but the modern view is that corruption sands the wheels for everyone.","_v":"467200d0c4"},{"id":"E16-C3-ER05","prompt":"A student says: 'Fig 16.1 proves that corruption causes poverty.'","options":["Agree, because the pattern is large and consistent.","Say the figure shows a strong association; poverty can also weaken institutions, and both can share deeper causes.","Say the figure shows that corruption and income are unrelated.","Say the outliers prove there is no link at all."],"answer":1,"why":"The pattern is a correlation. Causation likely runs both ways, and deeper causes can drive both.","_v":"5ea2775d72"},{"id":"E16-C3-ER06","prompt":"A student says: 'Russia has more corruption than its income would suggest, so corruption doesn't affect income.'","options":["Agree, because one counterexample disproves the pattern.","Say Russia's data must be wrong because it doesn't fit.","Explain that one outlier doesn't overturn a broad pattern; resource wealth can lift income despite corruption.","Say Russia shows that corruption raises income."],"answer":2,"why":"Outliers show other factors matter. They don't erase a large, persistent association.","_v":"d0769ca038"},{"id":"E16-C3-ER07","prompt":"A student says: 'If we publish every government contract online, corruption will disappear.'","options":["Agree, because corruption depends on secrecy.","Say publishing contracts has no effect at all.","Say only higher salaries for officials can reduce corruption.","Add that information only reduces corruption when someone can act on it and courts impose a real cost."],"answer":3,"why":"Transparency helps, but a rule is only as strong as the enforcement behind it.","_v":"b06242b825"},{"id":"E16-C3-ER08","prompt":"A student says: 'Lobbying for an exclusive license is just another way to compete, like building a better product.'","options":["Distinguish competing for privileges (rent-seeking) from competing to create value for customers.","Agree, because both raise the firm's profit.","Say all lobbying is illegal corruption.","Say building a better product is also rent-seeking."],"answer":0,"why":"Both can raise profit, but only one creates value. Not all lobbying is illegal.","_v":"df46717619"},{"id":"E16-C3-ER09","prompt":"A student says: 'Buying a used car costs only the sticker price.'","options":["Agree, because the price includes everything.","Add the transaction costs: searching listings, test-driving, haggling, and arranging a loan.","Say the sticker price is itself a transaction cost.","Say only the dealer pays transaction costs."],"answer":1,"why":"Transaction costs are everything beyond the price that it takes to make the deal happen.","_v":"0ce07171a1"},{"id":"E16-C3-ER10","prompt":"A student says: 'Extractive institutions only matter in countries with mines and oil wells.'","options":["Agree, because extractive refers to natural resources.","Say extractive institutions exist only in poor countries.","Explain that extractive means rules that concentrate rights, enforcement, and entry among insiders, in any industry.","Say any tax is an extractive institution."],"answer":2,"why":"The term describes who the rules serve, not what industry they govern.","_v":"713983232c"},{"id":"E16-C3-ER11","prompt":"A student says: 'A small bribe can't do much harm.'","options":["Agree, because a small bribe barely changes one firm's costs.","Say only bribes above a legal limit count as corruption.","Say small bribes help the poor by speeding up services.","Explain that small bribes add up across many deals, raise transaction costs, and reward officials for creating obstacles."],"answer":3,"why":"The harm is in the incentives the system creates, not just the size of one payment.","_v":"3adde2a4c5"},{"id":"E16-C3-ER12","prompt":"A student says: 'A country with a free press can't have serious corruption.'","options":["Explain that a free press helps expose corruption, but it reduces corruption only when courts and officials act on what is exposed.","Agree, because reporters will find every bribe.","Say a free press makes corruption worse.","Say press freedom has nothing to do with corruption."],"answer":0,"why":"Exposure matters, but it has to be backed by someone empowered to act.","_v":"3e766002d6"}]},{"id":"c3-ap","type":"choice","tier":3,"title":"AP-style questions","targets":["16.3a","16.3b","16.3c","16.3d","16.3e","16.3f"],"status":"draft","items":[{"id":"E16-EX-002","prompt":"A city eliminates permit fees, but the mayor still chooses which new firms may enter based on personal connections. Which conclusion is most defensible?","options":["Removing official fees necessarily makes entry competitive, even if approvals stay discretionary.","Lower fees remove one cost, but selective permission still protects some firms from entry.","The main remaining obstacle is a lack of enforceable private titles rather than the approval rule.","Personal discretion matters only if an official actually collects a bribe."],"answer":1,"why":"Removing a fee may reduce one cost; arbitrary favoritism can still obstruct open entry and investment.","_v":"0bda95bdaf"},{"id":"E16-EX-003","prompt":"A land registry is accurate, but courts enforce property claims only for politically connected owners. Which investment risk remains?","options":["The court may decline to protect the registered owner's claim if the owner lacks political connections.","The registry cannot identify the owner because contracts are enforceable only selectively.","A clear registry by itself eliminates uncertainty for all lenders.","The remaining uncertainty is solely the cost of filing land records, not enforcement."],"answer":0,"why":"Clear records help identify title, while unequal enforcement can still undermine credible rights.","_v":"897f472097"},{"id":"E16-EX-004","prompt":"A port official demands a payment to process routine documents. One firm pays and ships early. What is the strongest evaluation of the payment's broader effects?","options":["The faster shipment is evidence that the permit system's net social benefits exceed its costs.","The payment changes only the distribution of government revenue and not firm incentives.","One applicant may benefit while officials gain incentives to delay others or favor payers.","If the payment is unofficial, the firm cannot receive any genuine private benefit."],"answer":2,"why":"Separate the firm's private incentive from the institution-wide incentive for officials to create or exploit bottlenecks.","_v":"d8aab8930d"},{"id":"E16-EX-007","prompt":"Two countries have similar resources and entrepreneurial talent. In one, newcomers can register land and enforce contracts cheaply; in the other, officials favor insiders. Which inference is warranted?","options":["The contrast suggests a mechanism by which institutions could affect entry and investment, but cannot alone isolate their causal effect.","Similar resources and talent are sufficient controls to establish that institutional differences caused all later growth.","The countries must invest equally because productive opportunities are initially similar.","Political favoritism matters only for income distribution, not entry or expected returns."],"answer":0,"why":"Economic mechanisms support a plausible prediction, but cross-country comparisons do not independently establish causation.","_v":"dcf9818395"},{"id":"E16-EX-014","prompt":"Two equally productive firms apply for permits. The incumbent receives approval automatically, while the newcomer must negotiate a discretionary payment. Which principle is most threatened?","options":["The firms face unequal entry conditions because discretionary approval privileges the incumbent.","The market chiefly suffers from weak enforcement of contracts between the applicants and their customers.","The problem is only a higher administrative fee, not how approvals are allocated.","Entry is competitive if both companies can submit applications regardless of unequal decisions."],"answer":0,"why":"Discretionary advantage changes the terms of entry, potentially protecting insiders regardless of productivity.","_v":"85ac05e4f6"},{"id":"E16-EX-016","prompt":"An impartial court system exists, but changes in permit eligibility are announced only after applications close. What institutional improvement is most relevant?","options":["Raise eligibility requirements to ensure that fewer unsuccessful applicants waste resources.","Permit only incumbent firms so firms can invest under known rules.","Announce entry criteria before applications and apply them consistently.","Shift all entry decisions to the same courts that enforce private contracts."],"answer":2,"why":"Predictable rules allow firms to plan; impartial courts cannot undo every cost of arbitrary regulatory surprises.","_v":"addc759d3a"},{"id":"E16-EX-021","prompt":"A city introduces a public permit queue to reduce favoritism. Applications still experience delays, and the number of cases changes seasonally. Which information is most useful for assessing whether favoritism declined?","options":["Compare a single recent applicant with a highly connected applicant from before the change.","Ask staff whether the public queue makes them feel more accountable.","Compare exception rates and processing outcomes across connected and unconnected applicants over time, while considering other changes.","Check whether total permit applications rose, without examining how cases were treated."],"answer":2,"why":"A transparent, comparable record can investigate favoritism; one anecdote cannot establish the system-wide effect.","_v":"ad1741d114"},{"id":"E16-EX-022","prompt":"A company spends more on lobbying for an exclusive license than improving its product. Which economic mechanism best explains the concern?","options":["The firm may be rent-seeking: expending resources to secure privileges rather than compete on productivity.","The firm's lobbying expenditures show that the license will necessarily reduce prices.","Seeking special protection is economically equivalent to investing in a new production method.","The lobbying demonstrates corruption in every case, independent of legality or influence."],"answer":0,"why":"The issue is the incentive to gain through special protection rather than productivity; not all lobbying is illegal.","_v":"d0ba17fd9a"},{"id":"E16-EX-023","prompt":"A study finds that regions with stronger courts have higher investment. Which additional result would strengthen a causal interpretation?","options":["The correlation also appears when regions are ranked by income, without additional controls.","The regions' investment is measured in the same year as court quality, ensuring a correct direction of causation.","The highest-investment regions report positive perceptions of their courts.","A plausibly independent enforcement reform allows comparison of investment changes with a credible comparison group."],"answer":3,"why":"A design that addresses confounding and timing offers more causal leverage than a raw cross-sectional association.","_v":"dc66743044"},{"id":"E16-EX-024","prompt":"A well-connected supplier receives a contract despite a higher bid and weaker quality. Which consequence is most plausible?","options":["A higher winning bid establishes that the supplier's quality-adjusted costs must be lowest.","Favoritism may reduce competitive discipline and the value obtained for public spending.","The outcome shows only a distributional change among suppliers, not any potential efficiency cost.","Competition must increase because other suppliers will respond with stronger bids regardless of future access."],"answer":1,"why":"Favored selection can distort competition and reduce value, though the magnitude requires evidence.","_v":"98d7c3db97"},{"id":"E16-EX-301","prompt":"In one country, import licenses go only to firms linked to the ruling family. Markets for imported goods clear, and shelves are stocked. Which statement is most accurate?","options":["Because the market clears, the licensing system has no efficiency cost.","Because insiders control imports, the market cannot reach an equilibrium price.","The licenses mainly lower transaction costs for importers by reducing the number of firms.","The market clears, but the licenses limit entry, so prices can stay higher and the gain flows to insiders."],"answer":3,"why":"A market on extractive rules still clears. The cost shows up as blocked entry and prices that carry the insiders' advantage.","_v":"62e17df50d"},{"id":"E16-EX-302","prompt":"In Fig 16.1, Botswana is cleaner than its income alone would predict, and Russia is richer than its low (more corrupt) score would predict, partly because of its natural resources. What is the best way to use these outliers?","options":["They show that other factors, such as resource wealth, also shape income, so the association is not a one-to-one rule.","They show that corruption and income are unrelated.","They prove that corruption raises income in resource-rich countries.","They should be dropped from the figure because they don't fit the pattern."],"answer":0,"why":"Outliers point to other causes. They don't erase the broad association, and they shouldn't be thrown out.","_v":"57a5e11bb3"},{"id":"E16-EX-303","prompt":"An official can approve a building permit in one week but usually takes six months unless paid. What is the strongest argument that such payments harm the wider economy, even if each paying firm gains?","options":["Paying firms save time, so total output must rise.","Officials gain a reason to create and keep delays, which raises transaction costs for every applicant.","The payments are only transfers, so they don't change anyone's incentives.","The harm falls only on firms that refuse to pay, so it isn't a wider cost."],"answer":1,"why":"The self-feeding problem: an official who can sell the removal of an obstacle has every reason to invent it.","_v":"74b502d37e"},{"id":"E16-EX-304","prompt":"A country posts every public contract and its winning bid online. Two years later, contract prices are unchanged, and no official has been charged. Which explanation fits the chapter's argument best?","options":["Transparency always lowers prices, so the posted data must be wrong.","Contract prices can fall only if officials' pay is raised first.","No one with power to act used the information, so exposing favoritism carried no real cost.","Posting contracts raised transaction costs for bidders, which cancelled out the gains."],"answer":2,"why":"Information only bites when someone can act on it and a court can impose a real cost.","_v":"42a18ffda1"},{"id":"E16-EX-305","prompt":"Two firms each spend $1 million. Firm A develops a cheaper way to produce its product. Firm B lobbies for a law that blocks new competitors. From society's point of view, what is the key difference?","options":["There is no difference, since both spent the same amount to raise profit.","Firm B's spending is better, because it gives the firm more certainty to invest.","Firm A's spending is rent-seeking, because it is aimed at higher profit.","Firm A's spending creates value; Firm B's mainly shifts value to itself and may reduce competition."],"answer":3,"why":"Rent-seeking competes for privileges. Profit seeking through a better method creates value for customers.","_v":"60d76c9168"},{"id":"E16-EX-306","prompt":"A reform cuts the steps to register a business from twelve offices to one and removes officials' discretion over approval. Which outcome is most likely?","options":["Fewer chances to demand bribes and lower transaction costs, so more new firms enter.","Corruption rises, because fewer officials are watching firms.","Entry falls, because the single office now has a monopoly on approvals.","Prices of all goods rise, because more firms are competing."],"answer":0,"why":"Fewer steps and no discretion mean fewer points where a payment can be demanded, which lowers the cost of entry.","_v":"7d14779452"}]}]},{"id":"c4","number":4,"name":"Public Goods & Common Resources","activities":[{"id":"c4-sort","type":"sort","tier":1,"title":"Sort the cases","targets":["16.4a"],"status":"draft","bins":["Private","Club","Common resource","Public"],"round_size":6,"cards":[{"id":"E16-C4-F01","text":"A sandwich purchased for individual consumption","bin":0,"why":"Eating the sandwich leaves less of it for others, and a seller can restrict access.","_v":"c79170a271"},{"id":"E16-C4-F02","text":"A password-protected video stream with ample server capacity","bin":1,"why":"Access is controllable while another viewer adds little congestion.","_v":"e3f2ca920d"},{"id":"E16-C4-F03","text":"Fish in an open-access lake","bin":2,"why":"Each harvested fish reduces the stock, and excluding fishers is difficult.","_v":"22fb2791e8"},{"id":"E16-C4-F04","text":"A national defense system protecting everyone in its territory","bin":3,"why":"Its protection is broadly shared and exclusion is generally difficult.","_v":"f4d18bdf8f"},{"id":"E16-C4-F05","text":"A reserved seat on a sold-out airplane","bin":0,"why":"One passenger's seat is unavailable to another; a ticket restricts access.","_v":"9feff2f842"},{"id":"E16-C4-F06","text":"An uncongested toll bridge with controlled entry","bin":1,"why":"Extra drivers impose little congestion while toll gates allow exclusion.","_v":"cc57538240"},{"id":"E16-C4-F07","text":"Groundwater pumped from a difficult-to-police open aquifer","bin":2,"why":"Withdrawals reduce the stock available to others and access is difficult to control.","_v":"b268e437db"},{"id":"E16-C4-F08","text":"A region-wide tornado siren that anyone nearby can hear","bin":3,"why":"Warnings are non-rival across listeners and difficult to restrict.","_v":"22703dfaf4"},{"id":"E16-C4-F09","text":"An apple sold at a grocery store","bin":0,"why":"Consumption uses up the apple and the retailer controls access.","_v":"9847738722"},{"id":"E16-C4-F10","text":"A subscription digital course with room for additional viewers","bin":1,"why":"A login restricts access even when serving one more user adds little congestion.","_v":"cea104109b"},{"id":"E16-C4-F11","text":"Fish from an unrestricted coastal fishery","bin":2,"why":"One catch reduces available fish and practical exclusion is difficult.","_v":"43bbc79a58"},{"id":"E16-C4-F12","text":"A publicly audible emergency radio alert for a whole city","bin":3,"why":"Additional listeners do not diminish the alert and nonpayers can still hear it.","_v":"8f41259753"},{"id":"E16-C4-F13","text":"A free fireworks display visible across town; one more resident can see the same show without reducing anyone else's view","bin":3,"why":"One more viewer does not reduce anyone else's view, and a show visible across town is hard to withhold from individual residents.","_v":"8cc2aa6a73"},{"id":"E16-C4-F14","text":"A shared pasture where anyone may let cattle graze, with no enforced entry limits","bin":2,"why":"Each animal eats grass that lessens what remains for others, and access is not restricted.","_v":"715716ba9e"},{"id":"E16-C4-F15","text":"Trees are harvested from an open-access forest with no permits or entry limits","bin":2,"why":"Each tree removed leaves fewer trees for others, and access is not restricted.","_v":"28a296e4cf"},{"id":"E16-C4-F16","text":"A haircut at a barbershop","bin":0,"why":"The barber's time spent on your haircut can't go to someone else, and the shop can refuse anyone who won't pay.","_v":"34b1aeb1f5"},{"id":"E16-C4-F17","text":"A pair of running shoes from a shoe store","bin":0,"why":"Once you wear the shoes, no one else can, and the store hands them over only after payment.","_v":"5cb45d0efd"},{"id":"E16-C4-F18","text":"A slice of pizza from a food truck","bin":0,"why":"Your slice is gone once you eat it, and the truck can keep it until you pay.","_v":"bfb16ad2b0"},{"id":"E16-C4-F19","text":"A gym that checks membership cards and has plenty of open machines","bin":1,"why":"The card check keeps non-members out, and with machines to spare, one more member takes little from others.","_v":"23081d0f8b"},{"id":"E16-C4-F20","text":"A cable TV channel available only to paying subscribers","bin":1,"why":"Non-subscribers can be blocked, and one more household watching doesn't reduce the show for anyone else.","_v":"ccde38f505"},{"id":"E16-C4-F21","text":"A movie in a half-empty theater that checks tickets","bin":1,"why":"Tickets keep non-payers out, and with empty seats, one more viewer takes little from others.","_v":"8efe1326ab"},{"id":"E16-C4-F22","text":"Wild berries in a public forest with no limits on picking","bin":2,"why":"Berries one person picks are gone for others, and no one is kept from picking.","_v":"d6585110e2"},{"id":"E16-C4-F23","text":"A city program that tracks disease outbreaks","bin":3,"why":"Everyone in the city gets the protection, and protecting one more person doesn't reduce it for others.","_v":"4833a7d5bf"},{"id":"E16-C4-F24","text":"A flood-control levee protecting every home in a river town","bin":3,"why":"No home behind the levee can be left unprotected, and protecting one more home doesn't weaken the protection for others.","_v":"42f3f8b6d6"}]},{"id":"c4-quick-rival","type":"quick","tier":1,"title":"Rival or non-rival?","targets":["16.4a"],"status":"draft","note":"Derived from the four-goods sort cards: Private and Common are rival; Club and Public are non-rival.","labels":["Rival","Non-rival"],"round_size":8,"items":[{"id":"E16-C4-RV01","prompt":"A sandwich purchased for individual consumption","answer":0,"why":"Eating the sandwich leaves less of it for others, and a seller can restrict access.","_v":"4535608251"},{"id":"E16-C4-RV02","prompt":"A password-protected video stream with ample server capacity","answer":1,"why":"Access is controllable while another viewer adds little congestion.","_v":"505695289e"},{"id":"E16-C4-RV03","prompt":"Fish in an open-access lake","answer":0,"why":"Each harvested fish reduces the stock, and excluding fishers is difficult.","_v":"ed727821e1"},{"id":"E16-C4-RV04","prompt":"A national defense system protecting everyone in its territory","answer":1,"why":"Its protection is broadly shared and exclusion is generally difficult.","_v":"bc9e19aab3"},{"id":"E16-C4-RV05","prompt":"A reserved seat on a sold-out airplane","answer":0,"why":"One passenger's seat is unavailable to another; a ticket restricts access.","_v":"7b91987b2f"},{"id":"E16-C4-RV06","prompt":"An uncongested toll bridge with controlled entry","answer":1,"why":"Extra drivers impose little congestion while toll gates allow exclusion.","_v":"9686996f21"},{"id":"E16-C4-RV07","prompt":"Groundwater pumped from a difficult-to-police open aquifer","answer":0,"why":"Withdrawals reduce the stock available to others and access is difficult to control.","_v":"0c62893be2"},{"id":"E16-C4-RV08","prompt":"A region-wide tornado siren that anyone nearby can hear","answer":1,"why":"Warnings are non-rival across listeners and difficult to restrict.","_v":"d1938d93c8"},{"id":"E16-C4-RV09","prompt":"An apple sold at a grocery store","answer":0,"why":"Consumption uses up the apple and the retailer controls access.","_v":"0eccf46a2e"},{"id":"E16-C4-RV10","prompt":"A subscription digital course with room for additional viewers","answer":1,"why":"A login restricts access even when serving one more user adds little congestion.","_v":"4e4b594040"},{"id":"E16-C4-RV11","prompt":"Fish from an unrestricted coastal fishery","answer":0,"why":"One catch reduces available fish and practical exclusion is difficult.","_v":"35b77fc0a5"},{"id":"E16-C4-RV12","prompt":"A publicly audible emergency radio alert for a whole city","answer":1,"why":"Additional listeners do not diminish the alert and nonpayers can still hear it.","_v":"d2b1430d94"},{"id":"E16-C4-QS-R01","prompt":"One person eats a sandwich for lunch.","answer":0,"why":"The sandwich is used up; another person cannot eat that same sandwich.","_v":"80e8b0685f"},{"id":"E16-C4-QS-R02","prompt":"One passenger occupies the last seat on an airplane.","answer":0,"why":"When one passenger takes the seat, it is unavailable to another passenger.","_v":"d11e1f9ece"},{"id":"E16-C4-QS-R03","prompt":"A driver pumps one gallon of gasoline into a car.","answer":0,"why":"Using the gallon leaves less fuel for anyone else.","_v":"2b3b1e7114"},{"id":"E16-C4-QS-R04","prompt":"A fisher catches one fish in an open-access lake.","answer":0,"why":"The catch leaves fewer fish in the lake for other fishers.","_v":"d8eccecc00"},{"id":"E16-C4-QS-R05","prompt":"One more listener tunes in to a local over-the-air radio broadcast.","answer":1,"why":"The extra listener can hear the same broadcast without taking it away from existing listeners.","_v":"468eaa5432"},{"id":"E16-C4-QS-R06","prompt":"One more resident receives protection from the same national-defense system.","answer":1,"why":"Protecting another resident does not reduce the protection others receive.","_v":"b4394a99b0"},{"id":"E16-C4-QS-R07","prompt":"One more person watches a free fireworks display from an open area with an unobstructed view.","answer":1,"why":"The additional viewer can see the same display without reducing anyone else's view.","_v":"5838328344"},{"id":"E16-C4-QS-R08","prompt":"One more subscriber streams a video while the service has ample server capacity.","answer":1,"why":"With capacity available, another viewer does not reduce the video access others receive.","_v":"3e733756f9"},{"id":"E16-C4-RV13","prompt":"A student takes the last chocolate milk from the cafeteria cooler.","answer":0,"why":"Once that carton is taken, no one else can have it.","_v":"d80c5b5b85"},{"id":"E16-C4-RV14","prompt":"A hiker eats an energy bar on the trail.","answer":0,"why":"The bar is used up; no one else can eat it.","_v":"53a7bca698"},{"id":"E16-C4-RV15","prompt":"One more car squeezes onto a jammed highway at rush hour.","answer":0,"why":"On a crowded road, each extra car slows everyone else down.","_v":"c02b8a48fe"},{"id":"E16-C4-RV16","prompt":"A family rents the last kayak available at the lake.","answer":0,"why":"While they use it, no other family can rent that kayak.","_v":"499486324f"},{"id":"E16-C4-RV17","prompt":"A hunter takes a deer from a forest where hunting is open to all.","answer":0,"why":"The deer taken is one fewer for every other hunter.","_v":"34658ad93c"},{"id":"E16-C4-RV18","prompt":"A shopper buys the last carton of eggs on the shelf.","answer":0,"why":"Buying that carton leaves none for the next shopper.","_v":"a3171ae745"},{"id":"E16-C4-RV19","prompt":"One more ship steers by a lighthouse's light.","answer":1,"why":"Another ship seeing the light doesn't dim it for the others.","_v":"3cafe70088"},{"id":"E16-C4-RV20","prompt":"One more person checks the time on a town's clock tower.","answer":1,"why":"Reading the clock doesn't use it up for anyone else.","_v":"7e7d051418"},{"id":"E16-C4-RV21","prompt":"One more person listens to a street musician in a quiet plaza.","answer":1,"why":"With room to spare, one more listener doesn't take the music away from others.","_v":"aed279d7cd"},{"id":"E16-C4-RV22","prompt":"One more driver uses a GPS satellite signal to find a route.","answer":1,"why":"The signal works just as well for every other receiver.","_v":"c5ca000e1e"},{"id":"E16-C4-RV23","prompt":"One more student uses the Pythagorean theorem to solve a problem.","answer":1,"why":"An idea isn't used up; anyone can use it at the same time.","_v":"4b58c71d57"},{"id":"E16-C4-RV24","prompt":"One more person enjoys a mountain view from a public road.","answer":1,"why":"One more person looking doesn't leave less of the view for anyone else.","_v":"52fd34bcf8"}]},{"id":"c4-quick-exclude","type":"quick","tier":1,"title":"Excludable or not?","targets":["16.4a"],"status":"draft","note":"Derived from the four-goods sort cards: Private and Club are excludable; Common and Public are hard to exclude.","labels":["Excludable","Hard to exclude"],"round_size":8,"items":[{"id":"E16-C4-EX01","prompt":"A sandwich purchased for individual consumption","answer":0,"why":"Eating the sandwich leaves less of it for others, and a seller can restrict access.","_v":"4535608251"},{"id":"E16-C4-EX02","prompt":"A password-protected video stream with ample server capacity","answer":0,"why":"Access is controllable while another viewer adds little congestion.","_v":"ce03e1a236"},{"id":"E16-C4-EX03","prompt":"Fish in an open-access lake","answer":1,"why":"Each harvested fish reduces the stock, and excluding fishers is difficult.","_v":"519ab2cd0c"},{"id":"E16-C4-EX04","prompt":"A national defense system protecting everyone in its territory","answer":1,"why":"Its protection is broadly shared and exclusion is generally difficult.","_v":"bc9e19aab3"},{"id":"E16-C4-EX05","prompt":"A reserved seat on a sold-out airplane","answer":0,"why":"One passenger's seat is unavailable to another; a ticket restricts access.","_v":"7b91987b2f"},{"id":"E16-C4-EX06","prompt":"An uncongested toll bridge with controlled entry","answer":0,"why":"Extra drivers impose little congestion while toll gates allow exclusion.","_v":"00f83784e3"},{"id":"E16-C4-EX07","prompt":"Groundwater pumped from a difficult-to-police open aquifer","answer":1,"why":"Withdrawals reduce the stock available to others and access is difficult to control.","_v":"dedf36ef15"},{"id":"E16-C4-EX08","prompt":"A region-wide tornado siren that anyone nearby can hear","answer":1,"why":"Warnings are non-rival across listeners and difficult to restrict.","_v":"d1938d93c8"},{"id":"E16-C4-EX09","prompt":"An apple sold at a grocery store","answer":0,"why":"Consumption uses up the apple and the retailer controls access.","_v":"0eccf46a2e"},{"id":"E16-C4-EX10","prompt":"A subscription digital course with room for additional viewers","answer":0,"why":"A login restricts access even when serving one more user adds little congestion.","_v":"a160798f4b"},{"id":"E16-C4-EX11","prompt":"Fish from an unrestricted coastal fishery","answer":1,"why":"One catch reduces available fish and practical exclusion is difficult.","_v":"0370614108"},{"id":"E16-C4-EX12","prompt":"A publicly audible emergency radio alert for a whole city","answer":1,"why":"Additional listeners do not diminish the alert and nonpayers can still hear it.","_v":"d2b1430d94"},{"id":"E16-C4-QS-E01","prompt":"A sandwich shop can refuse to hand over a sandwich unless the buyer pays.","answer":0,"why":"The seller can control who receives the sandwich.","_v":"8a99e74990"},{"id":"E16-C4-QS-E02","prompt":"An airline checks tickets before letting passengers board reserved seats.","answer":0,"why":"A ticket lets the airline restrict access to the seats.","_v":"5af5ef63a8"},{"id":"E16-C4-QS-E03","prompt":"A password is required to watch a streaming video.","answer":0,"why":"The service can deny access to people without the password.","_v":"191d010cb0"},{"id":"E16-C4-QS-E04","prompt":"A bicycle is kept in its owner's locked garage.","answer":0,"why":"The owner can keep unauthorized users from taking the bicycle.","_v":"5bddf9bd98"},{"id":"E16-C4-QS-E05","prompt":"A free fireworks display is visible across town, with no ticket or gate.","answer":1,"why":"Organizers cannot practically stop individual residents from seeing the display.","_v":"a83e4e563d"},{"id":"E16-C4-QS-E06","prompt":"A national-defense system protects everyone in the territory it defends.","answer":1,"why":"It is not practical to withhold territorial protection from individual residents.","_v":"dc03eafe56"},{"id":"E16-C4-QS-E07","prompt":"Anyone with a radio receiver can hear a free over-the-air broadcast.","answer":1,"why":"The station cannot feasibly prevent particular nonpayers from receiving the signal.","_v":"3e42dddae9"},{"id":"E16-C4-QS-E08","prompt":"Anyone may fish in an open-access lake; no permit or enforcement keeps newcomers out.","answer":1,"why":"Access is difficult to restrict in this open-access fishery.","_v":"9a5933d923"},{"id":"E16-C4-EX13","prompt":"A concert venue scans tickets at its only gate.","answer":0,"why":"People without a ticket can be turned away at the gate.","_v":"5fb938be96"},{"id":"E16-C4-EX14","prompt":"An app's premium features unlock only after you pay.","answer":0,"why":"The app can lock out anyone who hasn't paid.","_v":"8455934d2b"},{"id":"E16-C4-EX15","prompt":"A car wash takes payment before the wash starts.","answer":0,"why":"No payment, no wash, so non-payers are easy to keep out.","_v":"3b81731cfa"},{"id":"E16-C4-EX16","prompt":"A water utility can shut off service to a home that doesn't pay its bill.","answer":0,"why":"The utility can cut off a non-paying home.","_v":"3b50f66b8b"},{"id":"E16-C4-EX17","prompt":"A software company requires a paid license key to install its program.","answer":0,"why":"Without a key, the program won't install, so non-payers are kept out.","_v":"cbc3ee3228"},{"id":"E16-C4-EX18","prompt":"A theme park checks wristbands at each ride.","answer":0,"why":"Staff can turn away anyone without a wristband.","_v":"c6c2fa74c3"},{"id":"E16-C4-EX19","prompt":"Anyone walking down the street can enjoy a neighbor's flower garden.","answer":1,"why":"The owner can't practically stop passersby from seeing the flowers.","_v":"37d10786dc"},{"id":"E16-C4-EX20","prompt":"A county's mosquito spraying lowers disease risk for everyone who lives there.","answer":1,"why":"No resident can be left out of the lower risk, paid or not.","_v":"c5315e06fe"},{"id":"E16-C4-EX21","prompt":"Anyone on the coast can see a lighthouse's beam.","answer":1,"why":"The light can't be hidden from boats or people that didn't pay for it.","_v":"a5872acd14"},{"id":"E16-C4-EX22","prompt":"Any boat may fish in the open ocean far from shore.","answer":1,"why":"No one practically keeps boats out of those waters.","_v":"4a8b51ded5"},{"id":"E16-C4-EX23","prompt":"Any driver can use a city street with no tolls or gates.","answer":1,"why":"With no toll or gate, nothing keeps non-payers off the street.","_v":"a943c5cd01"},{"id":"E16-C4-EX24","prompt":"Everyone on a block benefits from a new streetlight.","answer":1,"why":"The light falls on everyone nearby, whether they helped pay or not.","_v":"a8100af6e0"}]},{"id":"c4-match","type":"match","tier":1,"title":"Memory Match","targets":["16.4a"],"status":"draft","board_size":6,"pairs":[{"id":"E16-C4-MM01","left":"Rivalry","right":"One person's use reduces what remains available to others.","_v":"c1ad398d46"},{"id":"E16-C4-MM02","left":"Excludability","right":"Ability to prevent some people from accessing a good.","_v":"3c33c12e60"},{"id":"E16-C4-MM03","left":"Common resource","right":"Rival in use but difficult to exclude users.","_v":"0a3418161b"},{"id":"E16-C4-MM04","left":"Public good","right":"Non-rival and difficult to exclude users.","_v":"7e9e261685"},{"id":"E16-C4-MM05","left":"Private good","right":"A good both rival in use and excludable.","_v":"9e7f3d6ea2"},{"id":"E16-C4-MM06","left":"Club good","right":"A good excludable but largely non-rival until congestion develops.","_v":"5de6cfb0a7"},{"id":"E16-C4-MM07","left":"Free rider","right":"Someone who benefits from a good without paying for it.","_v":"c38d524de3"},{"id":"E16-C4-MM08","left":"Underprovision","right":"Too little of a good gets produced because people can benefit without paying.","_v":"824117a1c0"},{"id":"E16-C4-MM09","left":"Overuse","right":"The typical problem of a common resource: users take more than is good for the group.","_v":"1a7bb629a1"},{"id":"E16-C4-MM10","left":"Congestion","right":"Crowding that makes one more user reduce what others get.","_v":"be4c175dc2"},{"id":"E16-C4-MM11","left":"Non-rival","right":"Another person can use it without leaving less for anyone else.","_v":"8d387c0797"},{"id":"E16-C4-MM12","left":"Non-excludable","right":"People who don't pay can't practically be kept from using it.","_v":"39de19d4d4"},{"id":"E16-C4-MM13","left":"Tax funding","right":"A usual response to a public good, since voluntary payments fall short.","_v":"7408dab792"},{"id":"E16-C4-MM14","left":"Membership fees","right":"A common way to manage access to a club good.","_v":"88e4b2f8ec"},{"id":"E16-C4-MM15","left":"Quota","right":"A limit on how much each user may take from a shared resource.","_v":"c2e780f08e"},{"id":"E16-C4-MM16","left":"Four-goods grid","right":"Sorts goods by two questions: can non-payers be kept out, and does one person's use subtract from another's?","_v":"37cbd687ec"}]},{"id":"c4-detective","type":"detective","tier":1,"title":"Definition Detective","targets":["16.4a","16.4e"],"status":"draft","rounds":[{"id":"E16-C4-DD01","term":"Common resources","answers":[{"text":"Common resources are rival in use and difficult to exclude people from using.","grade":"A","why":"Both rivalry and difficulty of exclusion are defining properties."},{"text":"Common resources are difficult to exclude people from.","grade":"A-","why":"That is often true, but rivalry in use is also essential."},{"text":"Common resources are non-rival because everyone can access them.","grade":"F","why":"Open access does not prevent depletion or congestion."}],"_v":"80d9294b83"},{"id":"E16-C4-DD02","term":"Public goods","answers":[{"text":"Public goods are non-rival in use and difficult to exclude people from benefiting.","grade":"A","why":"Both non-rivalry and non-excludability matter."},{"text":"Public goods can benefit many people at the same time.","grade":"A-","why":"That leaves out the important distinction of whether exclusion is feasible."},{"text":"Public goods are simply whatever government agencies purchase.","grade":"F","why":"The source of funding does not determine rivalry or excludability."}],"_v":"686979d440"},{"id":"E16-C4-DD03","term":"Private goods","answers":[{"text":"Private goods are rival in use, and sellers can keep people who don't pay from using them.","grade":"A","why":"Both rivalry and excludability define a private good."},{"text":"Private goods are things you can buy in a store.","grade":"A-","why":"Many are, but the definition rests on rivalry and excludability, not where you buy it."},{"text":"Private goods are goods made by private companies instead of the government.","grade":"F","why":"Who makes or pays for a good doesn't decide what kind of good it is."}],"_v":"a793fea7a9"},{"id":"E16-C4-DD04","term":"Club goods","answers":[{"text":"Club goods are excludable but non-rival, at least until they get crowded.","grade":"A","why":"People can be kept out, and one more user takes little away from the others until congestion sets in."},{"text":"Club goods are things you need a membership to use.","grade":"A-","why":"Membership shows excludability, but the definition also needs non-rival use."},{"text":"Club goods are rival and hard to exclude people from.","grade":"F","why":"That describes a common resource."}],"_v":"a5e2a142aa"},{"id":"E16-C4-DD05","term":"Rivalry","answers":[{"text":"A good is rival when one person's use leaves less of it for others.","grade":"A","why":"That is the test: does my use subtract from yours?"},{"text":"A good is rival when it can run out.","grade":"A-","why":"Close, but the test is whether one person's use takes something away from another person's use."},{"text":"A good is rival when people who don't pay can be kept from using it.","grade":"F","why":"That is excludability, a separate question."}],"_v":"060dcfe6a9"},{"id":"E16-C4-DD06","term":"Excludability","answers":[{"text":"A good is excludable when people who don't pay can practically be kept from using it.","grade":"A","why":"That is the test: can non-payers be kept out?"},{"text":"A good is excludable when it has a price.","grade":"A-","why":"A price usually means the seller can keep people out, but the test is whether keeping non-payers out is possible."},{"text":"A good is excludable when one person's use leaves less for others.","grade":"F","why":"That is rivalry, a separate question."}],"_v":"2f540b2846"},{"id":"E16-C4-DD07","term":"Free rider","answers":[{"text":"A free rider benefits from a good without paying for it, because non-payers can't be kept out.","grade":"A","why":"It names the benefit, the missing payment, and why it happens."},{"text":"A free rider is someone who doesn't pay.","grade":"A-","why":"Not paying is part of it, but a free rider still gets the benefit."},{"text":"A free rider is someone who uses up a shared resource so others get less.","grade":"F","why":"That describes overuse of a common resource, not free riding."}],"_v":"ae261a92b1"},{"id":"E16-C4-DD08","term":"Overuse of a common resource","answers":[{"text":"Because a common resource is rival and no one can be kept out, users take more than is good for the group, and the stock runs down.","grade":"A","why":"It explains overuse with both features of a common resource."},{"text":"Overuse happens when too many people use something.","grade":"A-","why":"Close, but it leaves out why: no one can be kept out, and each use leaves less for others."},{"text":"Overuse happens when people refuse to pay for a public good.","grade":"F","why":"That is free riding, which leads to too little of a good, not too much use."}],"_v":"f480d301ec"}]},{"id":"c4-odd","type":"choice","tier":1,"title":"Odd one out","targets":["16.4a"],"status":"draft","note":"Ported from the Chapter 16 pilot (Odd One Out, marked pilot there), November 6, 2026.","items":[{"id":"E16-C4-OO01","prompt":"Three of these involve rival use. Which is the odd one out?","options":["A fish removed from a lake","An eaten apple","A seat on a full bus","An additional listener to a radio broadcast"],"answer":3,"why":"A caught fish, eaten apple, and occupied seat reduce what remains available to others. Another listener generally does not diminish access to the radio broadcast.","_v":"b9c33b7231"},{"id":"E16-C4-OO02","prompt":"Three of these are difficult to exclude people from enjoying. Which is the odd one out?","options":["A lighthouse signal","National defense benefits","Clean air over a city","A password-protected streaming video"],"answer":3,"why":"Lighthouse signals, national defense, and ambient clean air are difficult to withhold from particular people. A password-protected stream is excludable.","_v":"0d896e5c0a"},{"id":"E16-C4-OO03","prompt":"Three of these are club goods. Which is the odd one out?","options":["A streaming service with room for more viewers","A gym open only to members","An uncrowded toll road","Fish in an open-access lake"],"answer":3,"why":"The gym, the stream, and the toll road can keep out people who don't pay, and one more user takes little from others. Fish in an open lake are rival and hard to fence off, so they're a common resource.","_v":"5660a1f231"},{"id":"E16-C4-OO04","prompt":"Three of these are private goods. Which is the odd one out?","options":["A pair of shoes","A sandwich","A gallon of gasoline","A city's tornado siren"],"answer":3,"why":"A sandwich, shoes, and gasoline are rival, and a seller can refuse them to someone who won't pay. A siren is heard by everyone nearby at once, so it is a public good.","_v":"31ee09b17d"},{"id":"E16-C4-OO05","prompt":"Three of these are common resources. Which is the odd one out?","options":["A lighthouse's light","Wild berries in a forest with no limits on picking","Fish in the open ocean","Groundwater anyone may pump"],"answer":0,"why":"Ocean fish, open groundwater, and wild berries are rival and hard to keep people from. A lighthouse's light is non-rival, so it is a public good.","_v":"d506f43822"},{"id":"E16-C4-OO06","prompt":"Three of these are public goods. Which is the odd one out?","options":["National defense","A city program that tracks disease outbreaks","A flood-control levee for a whole town","A free parking space on a busy street"],"answer":3,"why":"Defense, a levee, and disease tracking protect everyone at once. A parking space holds one car at a time, so it is rival: a common resource when it is free.","_v":"9b3786cba0"},{"id":"E16-C4-OO07","prompt":"Three of these are excludable. Which is the odd one out?","options":["A neighbor's flower garden seen from the street","Software that needs a license key","A haircut at a barbershop","A concert behind a ticket gate"],"answer":0,"why":"The concert, the software, and the haircut can be withheld from non-payers. No one can practically stop passersby from seeing a front garden.","_v":"2130324dbc"},{"id":"E16-C4-OO08","prompt":"Three of these are non-rival, at least while uncrowded. Which is the odd one out?","options":["A math formula","A radio broadcast","A GPS satellite signal","A slice of pizza"],"answer":3,"why":"One more listener, user, or receiver takes nothing from the others. A slice of pizza is gone once someone eats it.","_v":"bfcb82f79b"},{"id":"E16-C4-OO09","prompt":"Three of these problems come from free riding. Which is the odd one out?","options":["Neighbors who skip dues for a street patrol that still protects them","Towns that won't chip in for a shared levee that protects them too","Residents who won't donate to a fireworks show they watch anyway","Fishers who take so many fish that the stock collapses"],"answer":3,"why":"The first three benefit without paying. Taking too many fish is overuse of a common resource.","_v":"a9170594ee"},{"id":"E16-C4-OO10","prompt":"Three of these become more rival when they get crowded. Which is the odd one out?","options":["A highway","A gym","A swimming pool","National defense"],"answer":3,"why":"Crowds at a pool, highway, or gym mean each extra person takes space from others. Protecting one more resident doesn't crowd national defense.","_v":"37db44886f"}],"pool_target":10},{"id":"c4-missing","type":"choice","tier":1,"title":"Find the missing piece","targets":["16.4a"],"status":"draft","note":"Ported from the Chapter 16 pilot, November 6, 2026. Missing Piece is a retirement candidate, so it was not expanded.","items":[{"id":"E16-C4-MP01","prompt":"Fish removed from an open-access lake are ______ because one catch leaves fewer fish for others.","options":["rival","non-rival","necessarily excludable"],"answer":0,"why":"Consumption depletes the shared stock.","_v":"8b861f7737"},{"id":"E16-C4-MP02","prompt":"A login requirement makes a streaming service more ______, even if additional viewers face little congestion.","options":["excludable","rival by definition","physically scarce"],"answer":0,"why":"Access can be restricted separately from rivalry.","_v":"1b8fa0bd94"}],"pool_exception":"Find the Missing Piece is a retirement candidate; it keeps its ported items only."},{"id":"c4-applied","type":"choice","tier":2,"title":"Applied cases","targets":["16.4c","16.4d","16.4f"],"status":"draft","items":[{"id":"E16-C4-AP01","prompt":"A toll road becomes congested. What changes?","options":["Excludability disappears","Rivalry increases","It becomes pure public"],"answer":1,"why":"Congestion makes road use rival.","_v":"6d2029a746"},{"id":"E16-C4-AP02","prompt":"A fishery gains enforceable permits. Fish then become…","options":["Non-rival","Automatically abundant","More excludable but still rival"],"answer":2,"why":"Access control does not change depletion.","_v":"0a49a14a2b"},{"id":"E16-C4-AP03","prompt":"Why might streetlights be underfunded privately?","options":["Free riding","Their light is rival","They have zero cost"],"answer":0,"why":"Nonexcludable benefits invite free riding.","_v":"1f9f311ef8"},{"id":"E16-C4-AP04","prompt":"A streaming service is congested. Which is most accurate?","options":["It is never rival","Rivalry depends on capacity","It is no longer excludable"],"answer":1,"why":"Congestion changes marginal crowding.","_v":"81f1eea0b9"},{"id":"E16-C4-AP05","prompt":"Publicly provided bottles of water are…","options":["Necessarily public goods","Never scarce","Still rival and potentially excludable"],"answer":2,"why":"Funding does not define the category.","_v":"8a59046f59"},{"id":"E16-C4-AP06","prompt":"A beach becomes crowded enough that each new visitor reduces others' enjoyment, although entry remains free. What changed?","options":["The service became more rival, even though exclusion is still difficult.","The beach became perfectly excludable.","Congestion proves it is a pure public good.","The beach stopped being scarce."],"answer":0,"why":"Congestion affects rivalry, while open access concerns excludability.","_v":"0ddaa72ebb"},{"id":"E16-C4-AP07","prompt":"A town adds a gate and paid passes to a dog park that is rarely crowded. Which kind of good is the park now closest to?","options":["Private good","Public good","Common resource","Club good"],"answer":3,"why":"The gate makes it excludable, and an uncrowded park is largely non-rival.","_v":"fb2319161c"},{"id":"E16-C4-AP08","prompt":"A town's free Wi-Fi slows to a crawl when many people log on at once. What does the slowdown show?","options":["The network is now a private good","Use has become rival because of congestion","The network became excludable"],"answer":1,"why":"Each extra user now takes speed away from others. Nothing changed about who can log on.","_v":"652c6e6a15"},{"id":"E16-C4-AP09","prompt":"Why do many towns pay for mosquito spraying with taxes instead of selling it to each household?","options":["Households that don't pay still benefit, so few would pay on their own","Taxes make the spraying excludable","Spraying is rival, so it has to be rationed"],"answer":0,"why":"The lower disease risk reaches everyone, so voluntary sales invite free riding.","_v":"8bdadaf075"},{"id":"E16-C4-AP10","prompt":"Anyone may graze cattle on a shared hillside, and the grass gets thinner each year. Which problem is this?","options":["Overuse of a common resource","Free riding on a public good","Congestion at a club good"],"answer":0,"why":"The grass is rival and no one is kept out, so ranchers graze more than the hillside can support.","_v":"f98802673a"},{"id":"E16-C4-AP11","prompt":"A company sells a computer program by download. Each extra copy costs almost nothing, and a license key blocks non-payers. How would you classify the program?","options":["Common resource: rival and hard to exclude","Public good: non-rival and hard to exclude","Club good: excludable and largely non-rival","Private good: rival and excludable"],"answer":2,"why":"The key keeps non-payers out, and one more copy takes nothing from other users.","_v":"86f7d0250e"},{"id":"E16-C4-AP12","prompt":"A private company runs weather satellites and gives its forecasts away free on broadcast TV. Which statement is most accurate?","options":["It can't be a public good because a private firm provides it","It is a common resource because each viewer uses up the forecast","The broadcast forecast has public-good features even though a private firm provides it"],"answer":2,"why":"The category depends on rivalry and excludability, not on who provides the good.","_v":"7a2bc5a062"}]},{"id":"c4-predict","type":"choice","tier":2,"title":"What changes?","targets":["16.4a"],"status":"draft","items":[{"id":"E16-C4-PR01","prompt":"A city fences an open-access fishery and enforces permits. Which property changes most directly?","options":["Excludability rises; catching fish remains rival.","Fish become non-rival.","The lake must become a public good.","Free riding in siren funding necessarily vanishes."],"answer":0,"why":"Rights of access can be restricted separately from rivalry in consumption.","_v":"ea499d28af"},{"id":"E16-C4-PR02","prompt":"A public swimming pool approaches capacity on a hot day. What happens to rivalry?","options":["An additional swimmer imposes more crowding, increasing rivalry.","Admission becomes impossible to restrict.","Water becomes a pure public good.","Congestion removes scarcity."],"answer":0,"why":"The extent of rivalry can depend on congestion and capacity.","_v":"cae38c52a7"},{"id":"E16-C4-PR03","prompt":"A streaming service drops its password and lets anyone watch for free. Which property changes most directly?","options":["The stream becomes rival","Excludability falls, and one more viewer still adds little crowding","It becomes a private good","Each episode gets used up"],"answer":1,"why":"Removing the password removes the way to keep non-payers out. Rivalry doesn't change.","_v":"47be75544c"},{"id":"E16-C4-PR04","prompt":"A gym that was rarely busy now has a line for every machine after 5 p.m. What changes?","options":["The gym becomes a public good","The machines become non-rival","Use becomes more rival at busy hours, and member checks still keep non-members out","The gym becomes hard to exclude people from"],"answer":2,"why":"Crowding makes one more member take something from others. The card check is unchanged.","_v":"09f2a65a27"},{"id":"E16-C4-PR05","prompt":"A county starts charging, and enforcing, a fee on each ton of fish caught in a bay anyone could fish before. What is the most likely effect?","options":["The fish become non-rival","Fishers catch more, because they have paid","Fishers take fewer fish, because each catch now costs something","The bay becomes a public good"],"answer":2,"why":"A price on each catch makes fishers weigh the cost of taking more.","_v":"fa9f1fb2eb"},{"id":"E16-C4-PR06","prompt":"A neighborhood pays for its streetlights with voluntary donations. Many residents stop donating once they see the lights stay on anyway. What is likely over time?","options":["Donations rise, since everyone benefits","Too little money comes in to keep the lights working","The lights become excludable","Each light gets used up faster"],"answer":1,"why":"Non-donors keep the benefit, so free riding leaves the lights underfunded.","_v":"8e32581ddf"},{"id":"E16-C4-PR07","prompt":"A community garden that anyone could walk into adds a locked gate, with keys only for members. Each member farms their own plot. What kind of good is each plot now?","options":["Club good: the plots are non-rival","Common resource: the garden is outdoors","Public good: the garden is shared","Private good: the plot is rival and the gate keeps others out"],"answer":3,"why":"One member's plot can't be farmed by another, and the gate allows exclusion.","_v":"cf6ef90d88"},{"id":"E16-C4-PR08","prompt":"A new road opens beside a jammed free highway, and traffic on the old highway now flows freely. What happens to rivalry on the old highway?","options":["It doesn't change, because rivalry never depends on traffic","The highway becomes excludable","It rises","It falls: one more car now slows others very little"],"answer":3,"why":"How rival a road is depends on crowding. Less traffic means less rivalry.","_v":"6fd4411314"},{"id":"E16-C4-PR09","prompt":"A city starts billing drivers each time they enter downtown, using license-plate cameras. Which property of downtown streets changes most directly?","options":["Nothing changes, since streets are government property","The streets become non-rival","Excludability rises, since the city can now charge every driver who enters","The streets become a public good"],"answer":2,"why":"The cameras give the city a way to charge drivers who enter, which makes access excludable.","_v":"e97b19947a"},{"id":"E16-C4-PR10","prompt":"A state buys a private toll bridge and keeps charging the same toll. The bridge is rarely crowded. Does the bridge's category change?","options":["No: it is still excludable and largely non-rival, so a club good","Yes: government ownership makes it a public good","Yes: it becomes rival","Yes: it becomes a common resource"],"answer":0,"why":"Who owns the bridge doesn't change whether drivers can be kept out or whether one more car crowds others.","_v":"4fd34800a7"},{"id":"E16-C4-PR11","prompt":"Neighbors pay voluntary dues for a security patrol that drives past every house on the street. Some stop paying, and the patrol still drives past their homes. What does this show?","options":["Free riding: non-payers keep the benefit, so dues may fall short","Excludability: the patrol can easily skip non-payers","Rivalry: patrolling one house uses up protection for others","Overuse: the patrol is being used up"],"answer":0,"why":"The patrol can't practically protect only the payers, so some neighbors benefit without paying.","_v":"d1f19b807e"},{"id":"E16-C4-PR12","prompt":"A video game company puts so many players on one server that the game lags for everyone. Which description fits best?","options":["The game has become a public good","The game is no longer excludable","The lag has made the game non-rival","The game is excludable, and crowding has made it more rival"],"answer":3,"why":"Accounts still keep non-payers out. The crowding means each extra player takes something from the others.","_v":"0b8d0afe25"}]},{"id":"c4-repair","type":"choice","tier":2,"title":"Repair the reasoning","targets":["16.4f"],"status":"draft","note":"Carried over from #112's error items; the audit recommends rebuilding these as Spot the Blunder sorts.","items":[{"id":"E16-C4-ER01","prompt":"A student says: 'Once a lake charges an entrance fee, the fish become non-rival.'","options":["Explain that access restrictions do not prevent fish depletion.","Agree because payment changes physical rivalry.","Conclude that all fees increase fish stocks."],"answer":0,"why":"Rivalry and excludability are different axes.","_v":"7f234f9da4"},{"id":"E16-C4-ER02","prompt":"A student labels bottled water a pure public good because it is distributed by the city.","options":["Classify bottles by consumption and exclusion, not provider.","Accept government funding as the definition.","Assume every bottle is non-rival."],"answer":0,"why":"Each bottle can be used up and access can be controlled.","_v":"780d597fa9"},{"id":"E16-C4-ER03","prompt":"A student says: 'Public schools are public goods because the government runs them.'","options":["Classify by rivalry and excludability: schools can turn students away, and seats are partly rival.","Agree, because government provision makes a good public.","Say schools are common resources because they are free."],"answer":0,"why":"Who provides a good doesn't decide its category.","_v":"d2c73a650a"},{"id":"E16-C4-ER04","prompt":"A student says: 'National defense is rival because the army can only be in one place at a time.'","options":["Agree, so defense is a private good.","Point out that protecting one more resident doesn't reduce anyone else's protection.","Say defense is excludable because soldiers check IDs."],"answer":1,"why":"Rivalry asks whether one more person's use subtracts from others'. For defense of a territory, it doesn't.","_v":"7b1c84d243"},{"id":"E16-C4-ER05","prompt":"A student says: 'A good is a public good if it's important to society.'","options":["Agree, since valuable goods deserve public funding.","Say only goods with no price can be public goods.","Separate value from category: a public good is non-rival and hard to exclude people from."],"answer":2,"why":"Being valuable and being a public good are different claims.","_v":"523daaba99"},{"id":"E16-C4-ER06","prompt":"A student says: 'Groundwater is a public good because no one owns the aquifer.'","options":["Agree, since no owner means a public good.","Point out that water one farm pumps is gone for others, so it is a common resource.","Say groundwater is excludable because pumps cost money."],"answer":1,"why":"Groundwater is rival and hard to exclude people from, which makes it a common resource.","_v":"fe66f9c91a"},{"id":"E16-C4-ER07","prompt":"A student says: 'A streaming service is a private good because you have to pay for it.'","options":["Note that it's excludable but largely non-rival, so it's a club good.","Agree, paying makes it private.","Say it's a public good because so many people watch."],"answer":0,"why":"Paying shows excludability. One more viewer takes little from others, so it isn't rival.","_v":"cc6a6bdbc3"},{"id":"E16-C4-ER08","prompt":"A student says: 'Free riding means using up a resource so others get less.'","options":["Agree.","Say free riding only happens with private goods.","Explain that free riding means benefiting without paying; using up a resource is overuse."],"answer":2,"why":"Free riding is about payment. Overuse is about a rival resource running down.","_v":"427bbf2251"},{"id":"E16-C4-ER09","prompt":"A student says: 'A toll road can't be a club good, because governments build roads.'","options":["Agree.","Explain that tolls make it excludable and, when uncrowded, it's largely non-rival, whoever built it.","Say all roads are common resources."],"answer":1,"why":"The builder doesn't matter. Tolls allow exclusion, and an uncrowded road is largely non-rival.","_v":"969e90313d"},{"id":"E16-C4-ER10","prompt":"A student says: 'Once a club good gets crowded, it becomes a public good.'","options":["Explain that crowding makes it more rival, which moves it away from a public good.","Agree, since more people are using it.","Say crowding makes it non-excludable."],"answer":0,"why":"Public goods are non-rival. Crowding adds rivalry, and the gate still allows exclusion.","_v":"55ba5adc25"},{"id":"E16-C4-ER11","prompt":"A student says: 'A lighthouse can't be a public good, since a private company could build one.'","options":["Agree.","Say the light is rival.","Say the provider doesn't matter: ships can't be kept from seeing the light, and one ship's use doesn't dim it."],"answer":2,"why":"The category depends on the good's features, not on who supplies it.","_v":"5556a1ec16"},{"id":"E16-C4-ER12","prompt":"A student says: 'Rival and excludable mean the same thing.'","options":["Explain that they are two separate questions: does use subtract from others (rivalry), and can non-payers be kept out (excludability)?","Agree, they always go together.","Say rivalry only matters for public goods."],"answer":0,"why":"A club good is excludable but non-rival, and a common resource is rival but hard to exclude, so the two can differ.","_v":"4e68e56785"}]},{"id":"c4-edge","type":"choice","tier":2,"title":"Edge cases","targets":["16.4a"],"status":"draft","note":"Ported from the Chapter 16 pilot (Slow Practice: Edge cases), November 6, 2026.","items":[{"id":"E16-C4-EC01","prompt":"Suppose a public library currently lets anyone enter its reading room. It could make entry excludable by ______.","options":["requiring a verified access card at the only entrance and turning away people without one","adding shelves while keeping the same open entrance","extending its hours for all visitors","placing more chairs inside"],"answer":0,"why":"An enforced access rule lets staff keep nonmembers out. More shelves, hours, or chairs do not by themselves restrict access.","_v":"f910b1403e"},{"id":"E16-C4-EC02","prompt":"During finals week, the library's study seats become rivalrous when ______.","options":["every seat is occupied, so one person's use means another cannot use that seat","the library checks cards at the entrance","the building stays open later while seats remain empty","the catalog becomes searchable online"],"answer":0,"why":"A specific seat can be used by only one person at a time. Full capacity makes one patron's use reduce the seating available to others; a card check would affect excludability.","_v":"860439830e"},{"id":"E16-C4-EC03","prompt":"Suppose a public school district limits enrollment to students inside its boundaries. Enrollment becomes excludable to nonresidents when staff ______.","options":["verify addresses and deny enrollment to applicants outside the boundary","publish the school calendar","share lesson materials online","add more desks to classrooms"],"answer":0,"why":"Public ownership does not make enrollment automatically non-excludable. A boundary rule backed by address checks lets the district keep some applicants out.","_v":"ec11be1bd0"},{"id":"E16-C4-EC04","prompt":"A teacher has one hour of individual tutoring appointments. That tutoring time is rivalrous because ______.","options":["an hour used by one student cannot also be given to another student at the same time","the school serves all enrolled students without a fee","the lesson is recorded and posted online","parents can view grades online"],"answer":0,"why":"The teacher's appointment time is limited. One student's use of a time slot leaves less of that same service for other students.","_v":"270c463677"},{"id":"E16-C4-EC05","prompt":"A city's rose garden inside a public park is open to everyone. It could make access to the garden excludable by ______.","options":["closing alternate entrances, staffing the gate, and checking tickets","adding more benches while leaving all entrances open","posting photos of the garden online","planting more flowers"],"answer":0,"why":"A gate with enforcement can restrict who enters the garden. People may still enjoy a view from outside, so be precise about whether you mean entry to the garden or seeing it.","_v":"8dd3d9cc26"},{"id":"E16-C4-EC06","prompt":"A public park trail is quiet at sunrise. Later, its narrow bridge becomes crowded. Use becomes rivalrous when ______.","options":["another hiker causes delay or blocks passage for people already on the bridge","the city installs a staffed entrance gate","the city removes a sign-in requirement","the trail map is posted online"],"answer":0,"why":"Congestion makes one more user's presence reduce the space or ease of passage available to others. A gate would change excludability instead.","_v":"21e95a0ac8"},{"id":"E16-C4-EC07","prompt":"An outdoor light show is visible from nearby hills. The city fences a viewing lawn and checks tickets, but cannot block views from outside. This makes ______ excludable; the show itself remains ______ to people with a clear view.","options":["access to the lawn; non-excludable","the show; excludable","access to the lawn; rivalrous","the hills; excludable"],"answer":0,"why":"The gate controls entry to the lawn, not the light visible from outside. The viewing lawn can become rivalrous when crowded, but a gate alone does not make the outside view excludable.","_v":"8e9d50bb37"},{"id":"E16-C4-EC08","prompt":"If the same light show moves inside an opaque tent and tickets are checked at its only entrance, access to the performance becomes more excludable because ______.","options":["both entry and the ability to see the show are controlled","one viewer's sight reduces what every other viewer can see","the performance becomes a physical object","the city has removed all access rules"],"answer":0,"why":"An opaque enclosure blocks the free outside view, and a checked entrance can keep non-ticket holders out. Whether the seating is rivalrous still depends on capacity and crowding.","_v":"4c208bcd5b"},{"id":"E16-C4-EC09","prompt":"A free over-the-air radio program could become excludable without becoming rivalrous if the station ______.","options":["scrambles its signal and issues paid decoders, while one authorized listener does not reduce the broadcast others receive","turns down the transmitter whenever a new listener tunes in","blocks every other station in the area","moves the transmitter to a public park"],"answer":0,"why":"Encryption and decoder access control can exclude nonpayers. With enough broadcast capacity, another authorized listener still does not take the program away from anyone else.","_v":"6537f12b36"},{"id":"E16-C4-EC10","prompt":"Suppose a city pool has plenty of open lanes and is well below its safe capacity. It adds a staffed turnstile and requires paid passes. Access becomes ______, while the pool remains ______ at this level of use.","options":["excludable; non-rival","non-excludable; rivalrous","rivalrous; excludable","non-rival; non-excludable"],"answer":0,"why":"The pass check and turnstile make it possible to keep nonpayers out. With ample room, one more swimmer does not reduce others' use; that could change once the pool nears capacity.","_v":"8a7def3330"},{"id":"E16-C4-EC11","prompt":"At the same pool, all safe swimming lanes are full. A new swimmer would reduce space for those already swimming. Use is now more ______ because ______.","options":["rivalrous; one more swimmer diminishes space and safety available to others","excludable; staff can turn away nonpayers","non-excludable; the pool is publicly owned","non-rival; everyone is using the same water"],"answer":0,"why":"At capacity, additional use creates congestion and takes space or safety from current swimmers. Public ownership and admission rules concern different dimensions.","_v":"954107da12"},{"id":"E16-C4-EC12","prompt":"A single city-owned parking space sits behind an entry arm. Drivers need a paid permit to enter, and staff turn away unauthorized vehicles. A car occupies the spot, so it is ______.","options":["both excludable and rivalrous","excludable and non-rival","non-excludable and rivalrous","non-excludable and non-rival"],"answer":0,"why":"Permit checks and the entry arm let staff exclude unauthorized drivers. One car occupies the single spot, so another driver cannot use it at the same time.","_v":"be1e4f05e0"},{"id":"E16-C4-EC13","prompt":"A city charges at the only gate to a beach parking lot, but an ungated public path still leads to the beach. Parking is excludable, but beach access remains ______ because ______.","options":["non-excludable; people can reach the sand without using the paid lot","excludable; the parking fee automatically controls every route","rivalrous; no one can see the water","non-rival; paid parking spaces cannot be occupied"],"answer":0,"why":"Property rights over a parking lot do not automatically control the beach. The open path leaves beach access available without paying for parking; crowding could separately make beach use rivalrous.","_v":"e3ccd4066d"},{"id":"E16-C4-EC14","prompt":"A public campground assigns one family to each individual campsite per night, checks reservations, and turns away others. That campsite is ______ because ______.","options":["both excludable and rivalrous; staff enforce a reservation, and one family's use prevents another family from using the same site that night","non-excludable and non-rival; government ownership guarantees free shared use","excludable and non-rival; a reservation does not use the site","non-excludable and rivalrous; entry is unrestricted even though the site is reserved"],"answer":0,"why":"Reservation checks make access excludable, and one group's use occupies that particular site for the night. Public ownership does not determine either dimension.","_v":"ef08087ff5"},{"id":"E16-C4-EC15","prompt":"A library has one physical copy of a popular book. While one reader has it checked out, the copy is rivalrous because ______.","options":["no other reader can borrow that same copy until it is returned","the library receives public funding","the title appears in the online catalog","the library is open to the public"],"answer":0,"why":"The particular printed copy is scarce while it is checked out. The library's public status does not make that copy non-rival; loan records and return rules also control who may use it at a given time.","_v":"6df56f1ffb"}]},{"id":"c4-ap","type":"choice","tier":3,"title":"AP-style questions","targets":["16.4a","16.4c","16.4d","16.4e","16.4f"],"status":"draft","items":[{"id":"E16-EX-005","prompt":"A town issues limited fishing permits for an overused lake. Which change follows most directly?","options":["Permits can reduce physical rivalry by ensuring that each fish caught remains available to others.","Enforced permits can make access more excludable, while fish remain rival when harvested.","The defining effect is to make the fishery a public good financed by permit fees.","Without a catch limit, a permit system always prevents excessive harvesting."],"answer":1,"why":"Permits can alter excludability, not the physical rivalry of fish. Their effectiveness depends on rules and enforcement.","_v":"ff0abe3b0c"},{"id":"E16-EX-006","prompt":"A lighthouse shines toward a busy shipping channel. Its visible warning signal is available to every passing vessel, and one ship's use does not meaningfully diminish its usefulness to others. The operator cannot feasibly restrict who sees the signal. Which conclusion follows?","options":["The signal is rival because additional ships require separate light, though access is hard to restrict.","The signal is non-rival and hard to exclude, so some beneficiaries may avoid paying.","The signal is excludable whenever the lighthouse has a private operator, even without access controls.","The signal is non-rival, but that alone establishes no financing concern because every user benefits."],"answer":1,"why":"The signal is non-rival and hard to exclude from use. Free riding may make selling access difficult.","_v":"bd872f02c2"},{"id":"E16-EX-008","prompt":"A town calls a public swimming pool a 'public good' because taxpayers built it. Why is this reasoning incomplete?","options":["Any taxpayer-funded good is public if everyone is entitled to apply for access.","Rivalry and feasible exclusion determine the classification, not the source of funding.","A swimming pool is necessarily nonexcludable if municipal employees operate it.","Government provision makes a facility non-rival until an admission fee is imposed."],"answer":1,"why":"Admissions can restrict access; limited space and congestion make use rival at least at capacity. Ownership and funding alone do not classify the good.","_v":"e2b6e9d17a"},{"id":"E16-EX-025","prompt":"An orchard owner wants to fund an insect-warning broadcast that all nearby farms can hear. Why might voluntary subscriptions underfund the service?","options":["Each listener uses up part of the warning signal, reducing what others can hear.","Only farms that subscribe can possibly benefit if the message is openly broadcast.","Nonpaying farms can benefit from the warning, making private collection difficult.","A warning service has no marginal benefit after the first farm receives the message."],"answer":2,"why":"The signal is largely non-rival and hard to restrict, so beneficiaries may hope others pay.","_v":"29aa19eff6"},{"id":"E16-EX-026","prompt":"A previously open pond is fenced and access rules are now enforced, but the fish stock and method of harvesting are unchanged. Which statement best describes the effects?","options":["Restricting entry changes the fact that one harvested fish leaves fewer fish for others.","Fencing makes access excludable, while harvesting fish remains rival.","Fencing makes the entire pond non-rival if permit numbers are held constant.","The pond cannot experience overuse once a private owner can exclude visitors, even without management."],"answer":1,"why":"Fencing changes access, not the depletion from catching individual fish.","_v":"ca1b358c04"},{"id":"E16-EX-027","prompt":"A city opens a fee-free parking garage and it fills at lunchtime. Why is it inaccurate to describe each parking space as a pure public good?","options":["A space used by one driver cannot be occupied simultaneously by another, even when parking is free.","Because a city owns the garage, exclusion is automatically impossible, so the issue must be funding.","A zero posted fee means parking has no opportunity cost even when the garage is full.","Every user receives the same benefit from the garage regardless of crowding and waiting."],"answer":0,"why":"Rival parking capacity remains rival whether access is charged or free.","_v":"a57f117df4"},{"id":"E16-EX-028","prompt":"A village considers both stocking a depleted fishery and constructing a warning siren. Which policy comparison is best?","options":["Both problems can be solved solely by producing more physical resources, without changing incentives.","The fishery and siren should both charge identical per-use prices because both are non-rival.","The fishery's chief issue is free riding on consumption; the siren's chief issue is depletion from use.","The fishery needs institutions that manage rival harvesting; siren financing must address benefits that are hard to exclude."],"answer":3,"why":"Common-resource overuse and public-good underprovision involve different mechanisms and need not have the same solution.","_v":"1f09db5b81"},{"id":"E16-EX-401","prompt":"A city's free downtown park is lightly used on weekdays but packed on summer weekends, when visitors crowd each other off the lawns. No fence or fee is planned. Which describes the park on a summer weekend?","options":["A club good, because it is non-rival and excludable","A public good, because the city provides it for free","A common resource: hard to exclude, and crowded use leaves less room for others","A private good, because each visitor uses up space and can be excluded"],"answer":2,"why":"With no fence or fee, the park is hard to exclude people from. Crowding makes use rival, so on busy weekends it behaves like a common resource.","_v":"d7d9713188"},{"id":"E16-EX-402","prompt":"A firm finds a way to block non-payers from receiving its over-the-air weather broadcast. One more paying listener still takes nothing from the others. The broadcast moves from…","options":["a public good to a common resource","a common resource to a private good","a club good to a private good","a public good to a club good"],"answer":3,"why":"Blocking non-payers makes the broadcast excludable. It stays non-rival, so it moves from public good to club good.","_v":"1266a79b5d"},{"id":"E16-EX-403","prompt":"Ten households each value a shared streetlight at $30. The light costs $200, and no household can be kept from its light. Each household decides alone whether to pay. Which outcome is most likely, and why?","options":["The light won't be built, because its light is rival","The light may not get built: total value ($300) exceeds the cost, but each household hopes others will pay","The light gets built, because each household values it at more than its $20 share","The light gets built, because total value exceeds the cost"],"answer":1,"why":"Total value is 10 × $30 = $300, more than the $200 cost, so the light is worth building. But since no one can be kept from the light, each household is tempted to free ride, and voluntary payments can fall short.","_v":"f69734948b"},{"id":"E16-EX-404","prompt":"Which pairing correctly matches a good with the problem typical of its category?","options":["A sandwich: underprovision because of free riding","Open-access groundwater: overuse and depletion","A members-only gym: free riding by non-members","National defense: congestion at the gate"],"answer":1,"why":"Groundwater anyone may pump is a common resource, and overuse is its typical problem. Defense invites free riding, a gym faces access and congestion, and a sandwich is a private good.","_v":"872c35660c"},{"id":"E16-EX-405","prompt":"A town calls its new toll-free bridge a public good. At rush hour the bridge is jammed, and each extra car slows every other car. Which classification fits rush hour best?","options":["Private good, because drivers pay with their time","Club good, because it can keep out non-payers","Common resource: hard to exclude, and rival when congested","Public good, because the town built it"],"answer":2,"why":"With no toll, drivers can't be kept off. When jammed, each extra car takes something from the others, so use is rival.","_v":"713bb79159"},{"id":"E16-EX-406","prompt":"Which change would turn a common resource into something closer to a private good?","options":["Letting more ranchers onto the pasture","Paying for the pasture with tax money","Giving individual ranchers enforceable ownership of separate plots of a shared pasture","Planting grass that grows faster"],"answer":2,"why":"Enforceable ownership of each plot lets an owner keep others out, while the grass stays rival. Rival and excludable is a private good.","_v":"ca5695df67"},{"id":"E16-EX-407","prompt":"Which statement about classifying goods is correct?","options":["Excludable goods are always rival","Non-rival goods can never be excluded","A good's category depends on rivalry and excludability, and congestion can change how rival a good is","A good is a public good whenever it is provided for free"],"answer":2,"why":"The two questions decide the category. Club goods show that excludable goods can be non-rival, and crowding can make a non-rival good rival.","_v":"e9281eb75c"},{"id":"E16-EX-408","prompt":"A nonprofit runs a mosquito-control program that lowers disease risk for everyone in a county, and it asks residents for donations. Which prediction is best supported?","options":["Asking for donations turns the program into a club good","The program will be overused like a common resource","Donations will match the program's value, since every resident gains","Donations will likely fall short of the program's value, because non-donors are protected too"],"answer":3,"why":"The protection is non-rival and hard to withhold from non-donors, so free riding makes voluntary funding fall short.","_v":"3b5df27d1e"},{"id":"E16-EX-409","prompt":"A good is non-rival, and its provider can cheaply keep out people who don't pay. Which example fits, and which problem is typical of it?","options":["A pair of shoes; free riding","A satellite TV channel; managing access and congestion","A coastal fishery; overuse","National defense; free riding"],"answer":1,"why":"Non-rival and excludable is a club good, like a subscription channel. Its typical problems are access and congestion.","_v":"2aa4922eba"}]}]}],"readiness":{"streak":5,"items":[{"id":"E16-EX-001","prompt":"A farmer and a buyer agree on the price of a parcel, but two families claim to own it. The transaction stalls. Which explanation best identifies the obstacle?","options":["The parties' agreement proves legal transfer is possible, so the remaining barrier must be low demand.","Competing ownership claims make a credible transfer difficult despite the agreed price.","The obstacle is chiefly weak competition among buyers, not the title itself.","The deal can proceed securely if the buyer promises to accept any later court ruling."],"answer":1,"why":"The parties have found a price, but a market transaction also requires a credible claim to transfer the parcel. Clarifying title addresses an institutional problem.","_v":"57295cec01"},{"id":"E16-EX-002","prompt":"A city eliminates permit fees, but the mayor still chooses which new firms may enter based on personal connections. Which conclusion is most defensible?","options":["Removing official fees necessarily makes entry competitive, even if approvals stay discretionary.","Lower fees remove one cost, but selective permission still protects some firms from entry.","The main remaining obstacle is a lack of enforceable private titles rather than the approval rule.","Personal discretion matters only if an official actually collects a bribe."],"answer":1,"why":"Removing a fee may reduce one cost; arbitrary favoritism can still obstruct open entry and investment.","_v":"0bda95bdaf"},{"id":"E16-EX-003","prompt":"A land registry is accurate, but courts enforce property claims only for politically connected owners. Which investment risk remains?","options":["The court may decline to protect the registered owner's claim if the owner lacks political connections.","The registry cannot identify the owner because contracts are enforceable only selectively.","A clear registry by itself eliminates uncertainty for all lenders.","The remaining uncertainty is solely the cost of filing land records, not enforcement."],"answer":0,"why":"Clear records help identify title, while unequal enforcement can still undermine credible rights.","_v":"897f472097"},{"id":"E16-EX-004","prompt":"A port official demands a payment to process routine documents. One firm pays and ships early. What is the strongest evaluation of the payment's broader effects?","options":["The faster shipment is evidence that the permit system's net social benefits exceed its costs.","The payment changes only the distribution of government revenue and not firm incentives.","One applicant may benefit while officials gain incentives to delay others or favor payers.","If the payment is unofficial, the firm cannot receive any genuine private benefit."],"answer":2,"why":"Separate the firm's private incentive from the institution-wide incentive for officials to create or exploit bottlenecks.","_v":"d8aab8930d"},{"id":"E16-EX-005","prompt":"A town issues limited fishing permits for an overused lake. Which change follows most directly?","options":["Permits can reduce physical rivalry by ensuring that each fish caught remains available to others.","Enforced permits can make access more excludable, while fish remain rival when harvested.","The defining effect is to make the fishery a public good financed by permit fees.","Without a catch limit, a permit system always prevents excessive harvesting."],"answer":1,"why":"Permits can alter excludability, not the physical rivalry of fish. Their effectiveness depends on rules and enforcement.","_v":"ff0abe3b0c"},{"id":"E16-EX-006","prompt":"A lighthouse shines toward a busy shipping channel. Its visible warning signal is available to every passing vessel, and one ship's use does not meaningfully diminish its usefulness to others. The operator cannot feasibly restrict who sees the signal. Which conclusion follows?","options":["The signal is rival because additional ships require separate light, though access is hard to restrict.","The signal is non-rival and hard to exclude, so some beneficiaries may avoid paying.","The signal is excludable whenever the lighthouse has a private operator, even without access controls.","The signal is non-rival, but that alone establishes no financing concern because every user benefits."],"answer":1,"why":"The signal is non-rival and hard to exclude from use. Free riding may make selling access difficult.","_v":"bd872f02c2"},{"id":"E16-EX-007","prompt":"Two countries have similar resources and entrepreneurial talent. In one, newcomers can register land and enforce contracts cheaply; in the other, officials favor insiders. Which inference is warranted?","options":["The contrast suggests a mechanism by which institutions could affect entry and investment, but cannot alone isolate their causal effect.","Similar resources and talent are sufficient controls to establish that institutional differences caused all later growth.","The countries must invest equally because productive opportunities are initially similar.","Political favoritism matters only for income distribution, not entry or expected returns."],"answer":0,"why":"Economic mechanisms support a plausible prediction, but cross-country comparisons do not independently establish causation.","_v":"dcf9818395"},{"id":"E16-EX-008","prompt":"A town calls a public swimming pool a 'public good' because taxpayers built it. Why is this reasoning incomplete?","options":["Any taxpayer-funded good is public if everyone is entitled to apply for access.","Rivalry and feasible exclusion determine the classification, not the source of funding.","A swimming pool is necessarily nonexcludable if municipal employees operate it.","Government provision makes a facility non-rival until an admission fee is imposed."],"answer":1,"why":"Admissions can restrict access; limited space and congestion make use rival at least at capacity. Ownership and funding alone do not classify the good.","_v":"e2b6e9d17a"},{"id":"E16-EX-013","prompt":"A market platform verifies sellers' identities but cannot ensure they deliver goods after payment. Which additional institution would most directly improve exchange?","options":["A reputation system eliminates the need for any enforcement if enough sellers receive favorable ratings.","Credible contract enforcement adds consequences when a verified seller fails to perform.","Allowing buyers to pay later removes the problem without introducing another risk.","Publishing ownership claims guarantees that every verified seller will deliver."],"answer":1,"why":"Verification helps identify counterparties; enforcement makes promises credible. Both support exchange.","_v":"c74a60801f"},{"id":"E16-EX-014","prompt":"Two equally productive firms apply for permits. The incumbent receives approval automatically, while the newcomer must negotiate a discretionary payment. Which principle is most threatened?","options":["The firms face unequal entry conditions because discretionary approval privileges the incumbent.","The market chiefly suffers from weak enforcement of contracts between the applicants and their customers.","The problem is only a higher administrative fee, not how approvals are allocated.","Entry is competitive if both companies can submit applications regardless of unequal decisions."],"answer":0,"why":"Discretionary advantage changes the terms of entry, potentially protecting insiders regardless of productivity.","_v":"85ac05e4f6"},{"id":"E16-EX-015","prompt":"A digital marketplace permits anyone to list products, but sellers cannot establish legal ownership. Which conclusion best follows?","options":["Open listing access cannot establish the seller's authority to transfer the claimed asset.","Open entry guarantees that buyers can enforce ownership rights against third parties.","The main obstacle is insufficient demand rather than disputed entitlements.","An advertised price determines ownership once a buyer accepts it."],"answer":0,"why":"An open platform is not enough when sellers lack credible rights to transfer what they offer.","_v":"67cb6dddb2"},{"id":"E16-EX-016","prompt":"An impartial court system exists, but changes in permit eligibility are announced only after applications close. What institutional improvement is most relevant?","options":["Raise eligibility requirements to ensure that fewer unsuccessful applicants waste resources.","Permit only incumbent firms so firms can invest under known rules.","Announce entry criteria before applications and apply them consistently.","Shift all entry decisions to the same courts that enforce private contracts."],"answer":2,"why":"Predictable rules allow firms to plan; impartial courts cannot undo every cost of arbitrary regulatory surprises.","_v":"addc759d3a"},{"id":"E16-EX-017","prompt":"A farmer owns a field. A neighboring cooperative legally controls the only canal access to irrigate it, and no easement has been granted. What does this show about the farmer's rights?","options":["Owning a field includes access to any neighboring infrastructure needed to farm it.","A landowner's rights are specific and may coexist with another person's enforceable easement.","The canal cannot be privately owned if two farms have historically used it.","A field title is invalid unless every adjacent parcel grants unrestricted access."],"answer":1,"why":"A valid land title does not erase distinct access rights that can belong to others.","_v":"46ff1d9d03"},{"id":"E16-EX-018","prompt":"A land-title system accurately records who may occupy and use a parcel, but local rules prohibit its sale. Which ownership distinction matters most?","options":["Recognized use rights do not necessarily include the right to transfer the land.","Without transfer, use of the land must also be prohibited.","An accurate title registry proves that transfers will be enforceable despite the restriction.","The restriction changes whether the land is excludable, rather than which ownership powers apply."],"answer":0,"why":"Knowing who owns a parcel does not necessarily mean that transfer is permitted.","_v":"939941833e"},{"id":"E16-EX-019","prompt":"A factory's emissions damage a neighbor's crops. Both parties own their land. Which conclusion is most defensible?","options":["The factory's title automatically authorizes any use that increases its profits.","The neighbor may claim damages only if the factory never held title.","The rights and remedies must account for the factory's use and the neighbor's harm; ownership is not unlimited.","The relevant entitlements can be determined from total production alone without legal rules."],"answer":2,"why":"Clear rights are essential precisely because ownership does not entail unrestricted harm to others.","_v":"083cebb972"},{"id":"E16-EX-020","prompt":"A buyer obtains a clear title but lenders still refuse collateral because courts rarely execute judgments. What is the remaining problem?","options":["Poor enforcement can make recorded collateral rights hard to realize after default.","Accurate title automatically makes foreclosure reliable even if courts will not act.","The main unresolved problem is simply whether buyers can find the property on a map.","Lenders' reluctance proves that the asset has no economic value."],"answer":0,"why":"Title clarifies the claim; enforceability helps make the claim credible to lenders.","_v":"3eabc32bb2"},{"id":"E16-EX-021","prompt":"A city introduces a public permit queue to reduce favoritism. Applications still experience delays, and the number of cases changes seasonally. Which information is most useful for assessing whether favoritism declined?","options":["Compare a single recent applicant with a highly connected applicant from before the change.","Ask staff whether the public queue makes them feel more accountable.","Compare exception rates and processing outcomes across connected and unconnected applicants over time, while considering other changes.","Check whether total permit applications rose, without examining how cases were treated."],"answer":2,"why":"A transparent, comparable record can investigate favoritism; one anecdote cannot establish the system-wide effect.","_v":"ad1741d114"},{"id":"E16-EX-022","prompt":"A company spends more on lobbying for an exclusive license than improving its product. Which economic mechanism best explains the concern?","options":["The firm may be rent-seeking: expending resources to secure privileges rather than compete on productivity.","The firm's lobbying expenditures show that the license will necessarily reduce prices.","Seeking special protection is economically equivalent to investing in a new production method.","The lobbying demonstrates corruption in every case, independent of legality or influence."],"answer":0,"why":"The issue is the incentive to gain through special protection rather than productivity; not all lobbying is illegal.","_v":"d0ba17fd9a"},{"id":"E16-EX-023","prompt":"A study finds that regions with stronger courts have higher investment. Which additional result would strengthen a causal interpretation?","options":["The correlation also appears when regions are ranked by income, without additional controls.","The regions' investment is measured in the same year as court quality, ensuring a correct direction of causation.","The highest-investment regions report positive perceptions of their courts.","A plausibly independent enforcement reform allows comparison of investment changes with a credible comparison group."],"answer":3,"why":"A design that addresses confounding and timing offers more causal leverage than a raw cross-sectional association.","_v":"dc66743044"},{"id":"E16-EX-024","prompt":"A well-connected supplier receives a contract despite a higher bid and weaker quality. Which consequence is most plausible?","options":["A higher winning bid establishes that the supplier's quality-adjusted costs must be lowest.","Favoritism may reduce competitive discipline and the value obtained for public spending.","The outcome shows only a distributional change among suppliers, not any potential efficiency cost.","Competition must increase because other suppliers will respond with stronger bids regardless of future access."],"answer":1,"why":"Favored selection can distort competition and reduce value, though the magnitude requires evidence.","_v":"98d7c3db97"},{"id":"E16-EX-025","prompt":"An orchard owner wants to fund an insect-warning broadcast that all nearby farms can hear. Why might voluntary subscriptions underfund the service?","options":["Each listener uses up part of the warning signal, reducing what others can hear.","Only farms that subscribe can possibly benefit if the message is openly broadcast.","Nonpaying farms can benefit from the warning, making private collection difficult.","A warning service has no marginal benefit after the first farm receives the message."],"answer":2,"why":"The signal is largely non-rival and hard to restrict, so beneficiaries may hope others pay.","_v":"29aa19eff6"},{"id":"E16-EX-026","prompt":"A previously open pond is fenced and access rules are now enforced, but the fish stock and method of harvesting are unchanged. Which statement best describes the effects?","options":["Restricting entry changes the fact that one harvested fish leaves fewer fish for others.","Fencing makes access excludable, while harvesting fish remains rival.","Fencing makes the entire pond non-rival if permit numbers are held constant.","The pond cannot experience overuse once a private owner can exclude visitors, even without management."],"answer":1,"why":"Fencing changes access, not the depletion from catching individual fish.","_v":"ca1b358c04"},{"id":"E16-EX-027","prompt":"A city opens a fee-free parking garage and it fills at lunchtime. Why is it inaccurate to describe each parking space as a pure public good?","options":["A space used by one driver cannot be occupied simultaneously by another, even when parking is free.","Because a city owns the garage, exclusion is automatically impossible, so the issue must be funding.","A zero posted fee means parking has no opportunity cost even when the garage is full.","Every user receives the same benefit from the garage regardless of crowding and waiting."],"answer":0,"why":"Rival parking capacity remains rival whether access is charged or free.","_v":"a57f117df4"},{"id":"E16-EX-028","prompt":"A village considers both stocking a depleted fishery and constructing a warning siren. Which policy comparison is best?","options":["Both problems can be solved solely by producing more physical resources, without changing incentives.","The fishery and siren should both charge identical per-use prices because both are non-rival.","The fishery's chief issue is free riding on consumption; the siren's chief issue is depletion from use.","The fishery needs institutions that manage rival harvesting; siren financing must address benefits that are hard to exclude."],"answer":3,"why":"Common-resource overuse and public-good underprovision involve different mechanisms and need not have the same solution.","_v":"1f09db5b81"}],"spiral":[{"chapter":14,"unit":2,"title":"Poverty and incentives","items":[{"id":"E14-SPIRAL-01","prompt":"A transfer program reduces benefits by one dollar for each extra dollar a recipient earns. What concern does this raise?","options":["The benefit phaseout can weaken the financial return to additional work.","The transfer automatically eliminates poverty traps.","The policy increases the marginal reward to working.","The policy necessarily eliminates income inequality."],"answer":0,"why":"A steep benefit phaseout can create a high effective marginal tax rate and reduce the net reward to earning more.","_v":"436a612f1f"},{"id":"E14-SPIRAL-02","prompt":"A policy raises a household's cash benefit but sharply reduces support when the household starts working. What should an economist examine?","options":["Only the total program budget.","How net income changes as earnings increase, including withdrawn benefits.","Whether the household prefers cash to groceries.","Only the program's average benefit."],"answer":1,"why":"The budget constraint and effective marginal incentives depend on both wages and benefit withdrawal.","_v":"73c409399e"},{"id":"E14-SPIRAL-03","prompt":"Two poverty policies spend the same amount, but one discourages employment much more. Which trade-off deserves attention?","options":["Both programs must have identical behavioral effects.","The policy's administrative name.","How the assistance reaches families while preserving incentives to work.","Whether every recipient works the same hours."],"answer":2,"why":"Policy design can affect both redistribution and incentives; equal spending need not imply equal outcomes.","_v":"957505756c"}]},{"chapter":15,"unit":3,"title":"Elasticity","items":[{"id":"E15-SPIRAL-01","prompt":"Demand for a product is relatively inelastic. Its price rises 10%. Which outcome is most consistent?","options":["Quantity demanded falls by more than 10%.","Quantity demanded falls by less than 10%.","Quantity demanded must increase.","The demand curve shifts right."],"answer":1,"why":"Inelastic demand means the percentage change in quantity demanded is smaller in magnitude than the percentage change in price.","_v":"2c427d416b"},{"id":"E15-SPIRAL-02","prompt":"A seller raises price and total revenue rises. What does that suggest about demand over that price change?","options":["Demand was relatively inelastic.","Demand was perfectly elastic.","Supply necessarily shifted left.","The good must be inferior."],"answer":0,"why":"When price rises and quantity falls proportionally less, revenue increases, indicating inelastic demand over that interval.","_v":"4b7a7c3a2e"},{"id":"E15-SPIRAL-03","prompt":"Why is demand often more elastic over a longer time horizon?","options":["Consumers have more time to find substitutes or adjust habits.","The law of demand stops applying.","Every market becomes perfectly competitive.","The supply curve must be vertical."],"answer":0,"why":"Substitution and adjustment generally become easier with more time, increasing price responsiveness.","_v":"f2a9c827d8"}]}]},"version":"1eb3ff6608"};
